@PluginDescriptor(
	name = "Codex Ledger",
	description = "Your net worth over time: bank, inventory, gear, Grand Exchange and more, with a day book of where your gold came from and went",
	tags = {"wealth", "net worth", "bank", "value", "gp", "profit", "grand exchange", "ledger", "codex"}
)
public class CodexLedgerPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(CodexLedgerPlugin.class);
	private static final String LEDGER_KEY = "ledger";
	/** Where a save that could not be read at all is set aside, untouched, before the ledger starts afresh. */
	static final String DAMAGED_KEY = "ledgerUnreadable";
	/** Characters the saved ledger may take before its oldest detail is trimmed; a typical account saves 40-120k. */
	private static final int SAVE_BUDGET = 200_000;
	/** Codex Session Chronicle's group and journal key, read and never written, for what pays. */
	static final String CHRONICLE_GROUP = "codexsessionchronicle";
	static final String CHRONICLE_JOURNAL = "journal";
	private final Saver saver = new Saver(SAVE_BUDGET);
	/** Ticks between revaluing what is held, about a minute. */
	private static final int REVALUE_TICKS = 100;
	/**
	 * Ticks between saves while something has changed, about five minutes. The ledger is also saved
	 * on logout, on a profile switch, when the plugin stops and when the client closes.
	 */
	private static final int SAVE_TICKS = 500;
	/**
	 * Ticks between saves when only the time logged in moved, about half an hour: the whole book is
	 * written each time, so standing still does not rewrite it every five minutes.
	 */
	private static final int PLAY_SAVE_TICKS = 3_000;
	/** Ticks between refreshing the panel and plaque while the ledger keeps changing. */
	private static final int PUBLISH_TICKS = 3;
	/**
	 * Ticks after login before anything is counted, so the exchange offers and the rune pouch have
	 * arrived and are counted in the same breath as the inventory they may have gone into.
	 */
	private static final int SYNC_TICKS = 3;
	/** Ticks after login before the summary. */
	private static final int SUMMARY_TICKS = 8;
	private static final int GE_SLOTS = 8;
	private static final int[] POUCH_RUNES = {
		VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6
	};
	private static final int[] POUCH_AMOUNTS = {
		VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6
	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private Gson gson;

	@Inject
	private CodexLedgerConfig config;

	@Inject
	private ScheduledExecutorService executor;

	/** Hands each item picture's load callback over only until it arrives. */
	private final IconWatch iconWatch = new IconWatch();
	private final WorthPlaque plaque = new WorthPlaque();
	private final Map<Integer, String> names = new HashMap<>();
	/** What each item is, worked out once on the client thread. */
	private final Map<Integer, Kind> kinds = new HashMap<>();
	/** The account's real Magic level as last seen logged in, 0 until then. */
	private int magicLevel;
	/** High alchemy values by item id; they never change. */
	private final Map<Integer, Long> highAlch = new HashMap<>();

	private LedgerPanel panel;
	private NavigationButton navButton;

	private String profile;
	private Ledger ledger;
	private boolean dirty;
	/** The panel was closed when the ledger last changed, so it has not been sent a copy since. */
	private volatile boolean panelBehind;
	/** Session Chronicle's filed sessions for this account, or empty without it. */
	private List<Earnings.Logged> chronicle = Collections.emptyList();
	/** Codex Bank Steward's copy of the bank for this account, read while the ledger waits for the real one; null without it. */
	private BankCopy bankCopy;
	/** The copy priced, and the tick it was priced at; priced again about once a minute while waiting. */
	private BankCopy.Estimate estimate;
	private int estimatedAt;
	private boolean unsaved;
	/** Time logged in counted since the last save, saved with the next change or at the slower pace. */
	private boolean playUnsaved;
	private int ticks;
	private int loggedInTicks = -1;
	private long worthAtLogin = -1;
	/** True once the offers and rune pouch have been read since login; nothing is settled before. */
	private boolean synced;
	private boolean pouchChanged;
	/** Set at the login screen, so the summary is written once a login and not again after a world hop. */
	private boolean fromLoginScreen;
	private boolean summaryDue;

	@Provides
	CodexLedgerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexLedgerConfig.class);
	}

	@Override
	protected void startUp()
	{
		ItemIcons icons = new ItemIcons()
		{
			@Override
			public BufferedImage icon(int itemId, Runnable onLoaded)
			{
				AsyncBufferedImage image = itemManager.getImage(itemId);
				// Only until it arrives: a loaded picture would run the callback again on every paint.
				iconWatch.watch(image, onLoaded, image::onLoaded);
				return image;
			}

			@Override
			public boolean hasArrived(BufferedImage image)
			{
				return iconWatch.hasArrived(image);
			}
		};
		panel = new LedgerPanel(icons);
		panel.setShare(new ShareActions()
		{
			@Override
			public void save(BufferedImage card, String fileName)
			{
				saveCard(card, fileName);
			}

			@Override
			public void copy(BufferedImage card)
			{
				copyCard(card);
			}
		});
		panel.setOnOpen(() ->
		{
			if (panelBehind)
			{
				clientThread.invoke(this::publish);
			}
		});
		navButton = NavigationButton.builder()
			.tooltip("Codex Ledger")
			.icon(Sigil.icon(16))
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		plaque.setEnabled(config.showPlaque());
		overlayManager.add(plaque);
		clientThread.invokeLater(() ->
		{
			loadProfile();
			GameState state = client.getGameState();
			if (state == GameState.LOGGED_IN)
			{
				loggedInTicks = SYNC_TICKS;
				observeAll();
			}
			else if (state == GameState.LOADING)
			{
				// Turned on during a teleport's loading screen: the player is in the world, so the read
				// waits for LOGGED_IN like a login's would, but this is no login and gets no summary.
				loggedInTicks = 0;
			}
			else if (state != GameState.HOPPING && state != GameState.CONNECTION_LOST)
			{
				// Turned on at the login screen, whose event has already gone by: the next login still gets its summary.
				fromLoginScreen = true;
			}
			publish();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(plaque);
		clientToolbar.removeNavigation(navButton);
		// A card still waiting for its pictures is never saved or copied once the plugin is off.
		CardPictures.cancel();
		clientThread.invokeLater(() ->
		{
			save();
			ledger = null;
			profile = null;
			chronicle = Collections.emptyList();
			bankCopy = null;
			estimate = null;
			magicLevel = 0;
			names.clear();
			synced = false;
			loggedInTicks = -1;
		});
		panel = null;
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		// ConfigManager writes its changes to disk in this same event, before a save queued on the
		// client thread runs, so a save made here has to be sent on by hand or it is never written.
		CompletableFuture<Void> done = new CompletableFuture<>();
		clientThread.invokeLater(() ->
		{
			try
			{
				if (save())
				{
					configManager.sendConfig();
				}
			}
			finally
			{
				done.complete(null);
			}
		});
		event.waitFor(done);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			if (loggedInTicks < 0)
			{
				loggedInTicks = 0;
			}
			if (fromLoginScreen)
			{
				fromLoginScreen = false;
				summaryDue = true;
				worthAtLogin = ledger != null && ledger.isReady() ? ledger.getTotal() : -1;
			}
		}
		else if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			// The client forgets the offers while away; they are read afresh after logging back in.
			loggedInTicks = -1;
			synced = false;
			if (ledger != null)
			{
				ledger.pause();
			}
			if (state == GameState.LOGIN_SCREEN)
			{
				fromLoginScreen = true;
				summaryDue = false;
				save();
				dirty = true;
				publish();
			}
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		save();
		loadProfile();
		worthAtLogin = ledger != null && ledger.isReady() ? ledger.getTotal() : -1;
		synced = false;
		if (client.getGameState() == GameState.LOGGED_IN && loggedInTicks >= SYNC_TICKS)
		{
			observeAll();
		}
		publish();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CHRONICLE_GROUP.equals(event.getGroup()))
		{
			// Session Chronicle filed a session: what pays may have moved.
			if (CHRONICLE_JOURNAL.equals(event.getKey()) && profile != null && profile.equals(event.getProfile()))
			{
				clientThread.invokeLater(() ->
				{
					readChronicle();
					publish();
				});
			}
			return;
		}
		if (BankCopy.GROUP.equals(event.getGroup()))
		{
			// Bank Steward saw the bank: the estimate shown before the ledger begins may have moved.
			if (BankCopy.KEY.equals(event.getKey()) && profile != null && profile.equals(event.getProfile()))
			{
				clientThread.invokeLater(() ->
				{
					readBankCopy();
					publish();
				});
			}
			return;
		}
		// The ledger itself is saved in this group too, every few minutes; only the settings matter here.
		if (CodexLedgerConfig.GROUP.equals(event.getGroup()) && event.getProfile() == null)
		{
			plaque.setEnabled(config.showPlaque());
			if ("goal".equals(event.getKey()) || "goalName".equals(event.getKey()) || "nameOnCard".equals(event.getKey()))
			{
				clientThread.invokeLater(this::publish);
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		GameState state = client.getGameState();
		// A teleport's loading screen can carry the tab it used, so a change seen while loading in the
		// same world is kept; the loading screens of a login or hop are left to the full read after it.
		if (ledger == null || state != GameState.LOGGED_IN && !(state == GameState.LOADING && synced))
		{
			return;
		}
		Store store = store(event.getContainerId());
		if (store != null)
		{
			ledger.observe(store, contents(event.getItemContainer()));
		}
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		int slot = event.getSlot();
		if (ledger == null || !synced || slot < 0 || slot >= GE_SLOTS || client.getGameState() != GameState.LOGGED_IN)
		{
			// Until the offers are read whole after login, a single slot could look like a collection.
			return;
		}
		ledger.offer(slot, offer(event.getOffer()));
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		// What the death takes leaves the account a few ticks later, when the player is sent home.
		// A death in a raid or a safe minigame takes nothing; what is eaten after it is supplies.
		Player me = client.getLocalPlayer();
		if (ledger != null && me != null && event.getActor() == me && !safeDeath(me))
		{
			ledger.died(System.currentTimeMillis());
		}
	}

	/** True where the game keeps everything on death: the raids and the safe minigames and arenas. */
	private boolean safeDeath(Player me)
	{
		LocalPoint local = me.getLocalLocation();
		int region = local == null ? -1 : WorldPoint.fromLocalInstance(client, local).getRegionID();
		return SafeDeath.isSafe(region, client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) > 0,
			client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS));
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		for (int varbit : POUCH_RUNES)
		{
			pouchChanged |= event.getVarbitId() == varbit;
		}
		for (int varbit : POUCH_AMOUNTS)
		{
			pouchChanged |= event.getVarbitId() == varbit;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (ledger == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		ticks++;
		if (loggedInTicks >= 0)
		{
			loggedInTicks++;
		}
		if (!synced)
		{
			if (loggedInTicks < SYNC_TICKS)
			{
				return;
			}
			observeAll();
		}
		if (pouchChanged)
		{
			pouchChanged = false;
			ledger.observe(Store.RUNE_POUCH, runePouch());
		}
		if (!pricesReady())
		{
			return;
		}
		if (ledger.played(System.currentTimeMillis(), ZoneId.systemDefault()))
		{
			playUnsaved = true;
		}
		ledger.setAtExchange(atExchange());
		if (ledger.hasPending() || ticks % REVALUE_TICKS == 0)
		{
			if (ledger.settle(System.currentTimeMillis(), itemManager::getItemPrice, ZoneId.systemDefault()))
			{
				dirty = true;
				unsaved = true;
			}
		}
		if (summaryDue && loggedInTicks >= SUMMARY_TICKS)
		{
			summaryDue = false;
			summary();
		}
		if (unsaved && ticks % SAVE_TICKS == 0 || playUnsaved && ticks % PLAY_SAVE_TICKS == 0)
		{
			save();
		}
		if (dirty && ticks % PUBLISH_TICKS == 0 || ticks % REVALUE_TICKS == 1)
		{
			publish();
		}
	}

	/** Prices load in the background after the client starts; nothing is valued before they are in. */
	private boolean pricesReady()
	{
		return itemManager.getItemPrice(ItemID.ABYSSAL_WHIP) > 0;
	}

	private static Store store(int containerId)
	{
		switch (containerId)
		{
			case InventoryID.BANK:
				return Store.BANK;
			case InventoryID.INV:
				return Store.INVENTORY;
			case InventoryID.WORN:
				return Store.EQUIPMENT;
			case InventoryID.SEED_VAULT:
				return Store.SEED_VAULT;
			case InventoryID.LOOTING_BAG:
				return Store.LOOTING_BAG;
			default:
				return null;
		}
	}

	private Map<Integer, Long> contents(ItemContainer container)
	{
		Map<Integer, Long> items = new HashMap<>();
		if (container == null)
		{
			return items;
		}
		for (Item item : container.getItems())
		{
			// A bank placeholder keeps the item's slot but holds none of it; folded into the item it would count as owned.
			if (item.getId() < 0 || item.getQuantity() <= 0 || isPlaceholder(item.getId()))
			{
				continue;
			}
			items.merge(itemManager.canonicalize(item.getId()), (long) item.getQuantity(), Long::sum);
		}
		return items;
	}

	/** True for a bank placeholder: the faded slot an item leaves behind when all of it is taken out. */
	private boolean isPlaceholder(int itemId)
	{
		return itemManager.getItemComposition(itemId).getPlaceholderTemplateId() != -1;
	}

	/** An offer as the ledger keeps it, or null for an empty slot. */
	private static Offer offer(GrandExchangeOffer offer)
	{
		if (offer == null)
		{
			return null;
		}
		switch (offer.getState())
		{
			case BUYING:
			case BOUGHT:
			case CANCELLED_BUY:
				return new Offer(offer.getItemId(), true, offer.getTotalQuantity(), offer.getPrice(), offer.getQuantitySold(),
					offer.getSpent(), offer.getState() == GrandExchangeOfferState.BUYING);
			case SELLING:
			case SOLD:
			case CANCELLED_SELL:
				return new Offer(offer.getItemId(), false, offer.getTotalQuantity(), offer.getPrice(), offer.getQuantitySold(),
					offer.getSpent(), offer.getState() == GrandExchangeOfferState.SELLING);
			default:
				return null;
		}
	}

	/** The runes in the rune pouch, read from the varbits the game keeps them in whether the pouch is carried or not. */
	private Map<Integer, Long> runePouch()
	{
		Map<Integer, Long> runes = new HashMap<>();
		EnumComposition ids = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		for (int i = 0; i < POUCH_RUNES.length; i++)
		{
			int rune = client.getVarbitValue(POUCH_RUNES[i]);
			int amount = client.getVarbitValue(POUCH_AMOUNTS[i]);
			int itemId = rune > 0 && ids != null ? ids.getIntValue(rune) : -1;
			if (itemId > 0 && amount > 0)
			{
				runes.merge(itemId, (long) amount, Long::sum);
			}
		}
		return runes;
	}

	/** True while the Grand Exchange or a bank's collection box is open, where offers are collected. */
	private boolean atExchange()
	{
		return visible(InterfaceID.GeOffers.UNIVERSE) || visible(InterfaceID.GeCollect.UNIVERSE);
	}

	private boolean visible(int component)
	{
		Widget widget = client.getWidget(component);
		return widget != null && !widget.isHidden();
	}

	/**
	 * Reads every place the client already has, all at once: after login once the offers have
	 * arrived, and when the plugin starts with the player logged in.
	 */
	private void observeAll()
	{
		synced = true;
		pouchChanged = false;
		for (int id : new int[]{InventoryID.INV, InventoryID.WORN, InventoryID.BANK, InventoryID.SEED_VAULT, InventoryID.LOOTING_BAG})
		{
			ItemContainer container = client.getItemContainer(id);
			if (container != null)
			{
				ledger.observe(store(id), contents(container));
			}
		}
		ledger.observe(Store.RUNE_POUCH, runePouch());
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		for (int i = 0; i < GE_SLOTS; i++)
		{
			ledger.offer(i, offers != null && i < offers.length ? offer(offers[i]) : null);
		}
	}

	private void loadProfile()
	{
		profile = configManager.getRSProfileKey();
		ledger = null;
		chronicle = Collections.emptyList();
		bankCopy = null;
		estimate = null;
		magicLevel = 0;
		if (profile == null)
		{
			return;
		}
		String saved = configManager.getRSProfileConfiguration(CodexLedgerConfig.GROUP, LEDGER_KEY);
		ledger = Ledger.read(gson, saved);
		if ((ledger == null || ledger.isMended()) && saved != null && !saved.trim().isEmpty())
		{
			// Some or all of it could not be read (the ledger then keeps what it can, or starts afresh),
			// and the next save writes over it. The save is set aside first as it was, one copy only,
			// never over a fuller one (see Ledger.setAside).
			String kept = configManager.getRSProfileConfiguration(CodexLedgerConfig.GROUP, DAMAGED_KEY);
			if (Ledger.setAside(kept, saved))
			{
				log.warn("Part of the saved ledger could not be read; it is kept as it was as {}", DAMAGED_KEY);
				configManager.setConfiguration(CodexLedgerConfig.GROUP, profile, DAMAGED_KEY, saved);
			}
		}
		if (ledger == null)
		{
			ledger = new Ledger();
		}
		ledger.setKinds(this::kind);
		saver.reset();
		readChronicle();
		readBankCopy();
		unsaved = false;
		playUnsaved = false;
		dirty = true;
	}

	/** Writes the ledger to the profile if it changed, time logged in included, and says whether it did. */
	private boolean save()
	{
		if (profile == null || ledger == null || !unsaved && !playUnsaved)
		{
			return false;
		}
		unsaved = false;
		playUnsaved = false;
		// A very busy account gives up the oldest detail rather than let the profile grow.
		String json = saver.save(ledger, gson::toJson);
		configManager.setConfiguration(CodexLedgerConfig.GROUP, profile, LEDGER_KEY, json);
		return true;
	}

	private void summary()
	{
		if (!config.loginSummary() || ledger == null || !ledger.isReady())
		{
			return;
		}
		long total = ledger.getTotal();
		ZoneId zone = ZoneId.systemDefault();
		LocalDate today = Instant.now().atZone(zone).toLocalDate();
		long change = Report.of(ledger, 1, today, 0).change();
		ChatMessageBuilder line = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT).append("Codex Ledger: ")
			.append(ChatColorType.NORMAL).append("your worth is ")
			.append(ChatColorType.HIGHLIGHT).append(Format.coins(total))
			.append(ChatColorType.NORMAL).append(", " + Format.signed(change) + " today.");
		if (worthAtLogin >= 0 && worthAtLogin != total)
		{
			line.append(" While you were away it moved " + Format.signed(total - worthAtLogin) + ".");
		}
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(line.build())
			.build());
	}

	/** Sends the panel a copy of the ledger with every name it needs, so Swing never reads what the client thread writes. */
	private void publish()
	{
		dirty = false;
		LedgerPanel target = panel;
		long now = System.currentTimeMillis();
		if (ledger == null)
		{
			plaque.show(null, 0);
			if (target != null)
			{
				SwingUtilities.invokeLater(() -> target.update(null, Collections.emptyMap(), null, LedgerPanel.State.LOGGED_OUT, now));
			}
			return;
		}
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		if (ledger.isReady() && loggedIn)
		{
			plaque.show(ledger.getTotal(), Report.of(ledger, 1, Instant.ofEpochMilli(now).atZone(ZoneId.systemDefault()).toLocalDate(), 0).change());
		}
		else
		{
			plaque.show(null, 0);
		}
		if (target == null || !target.isShowing())
		{
			// Copying a big ledger for a closed panel is wasted work on the client thread: it is copied when the panel opens.
			panelBehind = true;
			return;
		}
		panelBehind = false;
		Ledger copy = gson.fromJson(gson.toJson(ledger), Ledger.class).repair();
		for (int id : copy.holdings().keySet())
		{
			name(id);
		}
		for (Offer offer : copy.getOffers().values())
		{
			name(offer.getItem());
		}
		for (int id : copy.getBook().keySet())
		{
			name(id);
		}
		for (Day day : copy.getDays())
		{
			for (int id : day.getItems().keySet())
			{
				name(id);
			}
			for (int id : day.getDeals().keySet())
			{
				name(id);
			}
		}
		if (loggedIn && client.getRealSkillLevel(Skill.MAGIC) > 0)
		{
			magicLevel = client.getRealSkillLevel(Skill.MAGIC);
		}
		// Ironmen cannot sell, so "better alched than sold" means nothing to them; nor can anyone cast it below 55 Magic.
		Alchemy alchemy = client.getVarbitValue(VarbitID.IRONMAN) > 0 || magicLevel < Alchemy.MAGIC_LEVEL ? null
			// The ledger prices only what is held, so the rune's price is asked of the exchange itself.
			: Alchemy.of(copy.holdings(), copy::price, this::highAlch, itemManager.getItemPrice(Alchemy.NATURE_RUNE));
		if (alchemy != null)
		{
			for (Alchemy.Line line : alchemy.getLines())
			{
				name(line.getItemId());
			}
		}
		Earnings earnings = chronicle.isEmpty() ? null : Earnings.of(chronicle, now);
		BankCopy.Estimate guess = copy.isReady() ? null : estimate();
		Map<Integer, String> shownNames = new HashMap<>(names);
		Player player = client.getLocalPlayer();
		String name = loggedIn && player != null ? player.getName() : null;
		LedgerPanel.State state = !loggedIn ? LedgerPanel.State.LOGGED_OUT : copy.isReady() ? LedgerPanel.State.READY : LedgerPanel.State.WAITING_FOR_BANK;
		LedgerPanel.Goal goal = new LedgerPanel.Goal(Math.max(0, config.goal()) * 1_000_000L, config.goalName());
		boolean nameOnCard = config.nameOnCard();
		SwingUtilities.invokeLater(() ->
		{
			target.setGoal(goal);
			target.setShowName(nameOnCard);
			target.setAlchemy(alchemy);
			target.setEarnings(earnings);
			target.setEstimate(guess);
			target.update(copy, shownNames, name, state, now);
		});
	}

	/** Reads Codex Bank Steward's copy of the bank for this account; never writes it. Null when it is not installed. */
	private void readBankCopy()
	{
		estimate = null;
		bankCopy = null;
		if (ledger != null && ledger.isReady())
		{
			// The ledger has its own bank: the copy would only ever be a worse guess.
			return;
		}
		try
		{
			bankCopy = BankCopy.read(gson, configManager.getRSProfileConfiguration(BankCopy.GROUP, BankCopy.KEY));
		}
		catch (RuntimeException e)
		{
			log.debug("Could not read Codex Bank Steward's bank", e);
		}
	}

	/** The copy priced at today's prices, kept for about a minute; null without a copy or before prices load. */
	private BankCopy.Estimate estimate()
	{
		if (bankCopy == null || !pricesReady())
		{
			return null;
		}
		if (estimate == null || ticks - estimatedAt >= REVALUE_TICKS)
		{
			estimate = bankCopy.estimate(itemManager::getItemPrice);
			estimatedAt = ticks;
		}
		return estimate;
	}

	/** Reads Codex Session Chronicle's filed sessions for this account; never writes them. Empty when it is not installed. */
	private void readChronicle()
	{
		chronicle = Collections.emptyList();
		String json = configManager.getRSProfileConfiguration(CHRONICLE_GROUP, CHRONICLE_JOURNAL);
		if (json == null || json.isEmpty())
		{
			return;
		}
		// Another plugin's format may change under us; without it there is simply no "what pays".
		chronicle = Earnings.read(gson, json);
	}

	/** An item's high alchemy value, asked on the client thread and kept; 0 for an item that cannot be alched. */
	private long highAlch(int itemId)
	{
		Long known = highAlch.get(itemId);
		if (known == null)
		{
			ItemComposition item = itemManager.getItemComposition(itemId);
			known = item == null ? 0L : (long) Math.max(0, item.getHaPrice());
			highAlch.put(itemId, known);
		}
		return known;
	}

	/** What an item is: coins, gear, supplies or materials. Asked on the client thread while settling. */
	private Kind kind(int itemId)
	{
		Kind known = kinds.get(itemId);
		if (known != null)
		{
			return known;
		}
		// A noted platebody is still gear: the game gives a note no stats and no menu of its own.
		int base = itemManager.canonicalize(itemId);
		ItemComposition item = itemManager.getItemComposition(base);
		ItemStats stats = itemManager.getItemStats(base);
		boolean equipable = stats != null && stats.isEquipable() && stats.getEquipment() != null;
		Kind kind = Kinds.of(itemId, item.getName(), item.getInventoryActions(), equipable,
			equipable ? stats.getEquipment().getSlot() : -1, item.isStackable());
		kinds.put(itemId, kind);
		return kind;
	}

	private void name(int itemId)
	{
		names.computeIfAbsent(itemId, id -> itemManager.getItemComposition(id).getName());
	}

	/** Asks where to save the ledger card, then writes it off the Swing thread. */
	private void saveCard(BufferedImage card, String fileName)
	{
		LedgerPanel view = panel;
		List<Filepath> chosen = new Filepath.Chooser()
			.setIsSave()
			.setAcceptsFiles()
			.setDialogTitle("Save ledger card")
			.addExtensionFilter("PNG image", "png")
			.setDefaultExtension("png")
			.setFileName(fileName)
			.showDialog(view);
		if (chosen == null || chosen.isEmpty())
		{
			return;
		}
		Filepath target = chosen.get(0);
		executor.execute(() ->
		{
			String note;
			try (OutputStream out = target.openOutputStream())
			{
				ImageIO.write(card, "png", out);
				note = "Saved as " + target.getFileName() + ".";
			}
			catch (IOException e)
			{
				log.warn("Could not save the ledger card", e);
				note = "The card could not be saved: " + e.getMessage();
			}
			String shown = note;
			LedgerPanel p = panel;
			if (p != null)
			{
				SwingUtilities.invokeLater(() -> p.shareNote(shown));
			}
		});
	}

	private void copyCard(BufferedImage card)
	{
		String note;
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new ImageTransfer(ImageTransfer.opaque(card)), null);
			note = "Copied. Paste it anywhere you share pictures.";
		}
		catch (IllegalStateException e)
		{
			note = "The clipboard is busy, try again in a moment.";
		}
		LedgerPanel p = panel;
		if (p != null)
		{
			p.shareNote(note);
		}
	}
}

package com.codex.ledger;

import com.codex.ledger.ui.Theme;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.Transferable;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;

/** Hands the ledger card to the system clipboard as a picture. */
final class ImageTransfer implements Transferable
{
	private final BufferedImage image;

	ImageTransfer(BufferedImage image)
	{
		this.image = image;
	}

	/**
	 * The card on a solid backing. Some clipboards (Windows among them) drop transparency and
	 * would paint its rounded corners black, so they are filled with the card's own ink.
	 */
	static BufferedImage opaque(BufferedImage card)
	{
		BufferedImage out = new BufferedImage(card.getWidth(), card.getHeight(), BufferedImage.TYPE_INT_RGB);
		Graphics2D g = out.createGraphics();
		g.setColor(Theme.INK_DEEP);
		g.fillRect(0, 0, out.getWidth(), out.getHeight());
		g.drawImage(card, 0, 0, null);
		g.dispose();
		return out;
	}

	@Override
	public DataFlavor[] getTransferDataFlavors()
	{
		return new DataFlavor[]{DataFlavor.imageFlavor};
	}

	@Override
	public boolean isDataFlavorSupported(DataFlavor flavor)
	{
		return DataFlavor.imageFlavor.equals(flavor);
	}

	@Override
	public Object getTransferData(DataFlavor flavor) throws UnsupportedFlavorException
	{
		if (!isDataFlavorSupported(flavor))
		{
			throw new UnsupportedFlavorException(flavor);
		}
		return image;
	}
}

package com.codex.ledger.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.function.IntToLongFunction;

/**
 * What the account holds that is worth more cast into coins with High Level Alchemy than sold on
 * the Grand Exchange: per item, the high alchemy value less a nature rune, against the price after
 * the exchange's tax. Only items with a price are weighed (anything else cannot be sold to compare).
 */
public final class Alchemy
{
	public static final int COINS = 995;
	public static final int PLATINUM = 13204;
	public static final int NATURE_RUNE = 561;
	/** The Magic level High Level Alchemy is cast from. */
	public static final int MAGIC_LEVEL = 55;
	/** Lines shown at most. */
	public static final int SHOWN = 8;
	/** A line must make at least this much over selling to be worth the casts. */
	public static final long MIN_GAIN = 10_000;

	/** One item better alched than sold. */
	public static final class Line
	{
		private final int itemId;
		private final long quantity;
		private final long alch;
		private final long sale;

		Line(int itemId, long quantity, long alch, long sale)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.alch = alch;
			this.sale = sale;
		}

		public int getItemId()
		{
			return itemId;
		}

		public long getQuantity()
		{
			return quantity;
		}

		/** Coins one cast leaves, after its nature rune. */
		public long getAlch()
		{
			return alch;
		}

		/** Coins one sells for after tax. */
		public long getSale()
		{
			return sale;
		}

		/** How much more alching them all makes than selling them all. */
		public long gain()
		{
			return quantity * (alch - sale);
		}
	}

	private final List<Line> lines;
	private final long gain;
	private final long casts;

	private Alchemy(List<Line> lines, long gain, long casts)
	{
		this.lines = Collections.unmodifiableList(lines);
		this.gain = gain;
		this.casts = casts;
	}

	/**
	 * @param holdings everything held, by item id
	 * @param price the Grand Exchange price of one, 0 when it has none
	 * @param highAlch the high alchemy value of one, 0 when it cannot be alched
	 * @param natureRune the Grand Exchange price of a nature rune, looked up whether or not any are held;
	 *     0 when unknown, and then nothing is called better alched rather than count the rune as free
	 */
	public static Alchemy of(Map<Integer, Long> holdings, IntToLongFunction price, IntToLongFunction highAlch, long natureRune)
	{
		List<Line> all = new ArrayList<>();
		long gain = 0;
		long casts = 0;
		if (natureRune <= 0)
		{
			return new Alchemy(all, 0, 0);
		}
		long rune = natureRune;
		for (Map.Entry<Integer, Long> e : holdings.entrySet())
		{
			int id = e.getKey();
			long qty = e.getValue() == null ? 0 : e.getValue();
			if (qty <= 0 || id == COINS || id == PLATINUM || id == NATURE_RUNE)
			{
				continue;
			}
			long each = price.applyAsLong(id);
			if (each <= 0)
			{
				continue;
			}
			// Asked only for priced items: each first ask looks the item up in the game's cache.
			long ha = highAlch.applyAsLong(id);
			if (ha <= 0)
			{
				continue;
			}
			long sale = each - Offer.tax(id, 1, each);
			long alch = ha - rune;
			if (alch <= sale)
			{
				continue;
			}
			Line line = new Line(id, qty, alch, sale);
			if (line.gain() < MIN_GAIN)
			{
				continue;
			}
			all.add(line);
			gain += line.gain();
			casts += qty;
		}
		all.sort((a, b) -> Long.compare(b.gain(), a.gain()));
		return new Alchemy(all, gain, casts);
	}

	/** Every item better alched, most gained first. */
	public List<Line> getLines()
	{
		return lines;
	}

	/** How much more alching them all makes than selling. */
	public long getGain()
	{
		return gain;
	}

	/** Casts it takes to alch them all. */
	public long getCasts()
	{
		return casts;
	}

	public boolean isEmpty()
	{
		return lines.isEmpty();
	}
}

package com.codex.ledger.core;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Codex Bank Steward's saved copy of the bank, read (never written) so the ledger can say roughly
 * what the account is worth before it has seen the bank itself. It is only ever an estimate shown
 * while the ledger waits: nothing in it is booked, and the ledger still begins at the real bank.
 *
 * <p>The saved form is Bank Steward's {@code bankV1}:
 * {@code {"version":1,"savedAt":ms,"items":{"id":qty},"truncated":bool}}, ids already folded to
 * the item itself the way {@code ItemManager.canonicalize} folds them.
 */
public final class BankCopy
{
	public static final String GROUP = "codexbanksteward";
	public static final String KEY = "bankV1";
	/** Readers take no more kinds of item than Bank Steward ever writes. */
	static final int MAX_ITEMS = 2000;

	private final Map<Integer, Long> items;
	private final long savedAt;
	private final boolean truncated;

	BankCopy(Map<Integer, Long> items, long savedAt, boolean truncated)
	{
		this.items = Collections.unmodifiableMap(items);
		this.savedAt = savedAt;
		this.truncated = truncated;
	}

	/** Reads the saved copy, or null when there is none or it cannot be read. */
	public static BankCopy read(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		try
		{
			JsonElement root = gson.fromJson(json, JsonElement.class);
			if (root == null || !root.isJsonObject())
			{
				return null;
			}
			JsonObject o = root.getAsJsonObject();
			JsonElement list = o.get("items");
			if (list == null || !list.isJsonObject())
			{
				return null;
			}
			Map<Integer, Long> items = new HashMap<>();
			for (Map.Entry<String, JsonElement> e : list.getAsJsonObject().entrySet())
			{
				Integer id = id(e.getKey());
				Long qty = number(e.getValue());
				if (id != null && id > 0 && qty != null && qty > 0 && items.size() < MAX_ITEMS)
				{
					// No stack in the game holds more than this, whatever the copy claims.
					items.put(id, Math.min(qty, Integer.MAX_VALUE));
				}
			}
			Long savedAt = number(o.get("savedAt"));
			JsonElement cut = o.get("truncated");
			boolean truncated = cut != null && cut.isJsonPrimitive() && cut.getAsJsonPrimitive().isBoolean() && cut.getAsBoolean();
			return items.isEmpty() ? null : new BankCopy(items, savedAt == null || savedAt < 0 ? 0 : savedAt, truncated);
		}
		catch (JsonParseException | IllegalStateException | UnsupportedOperationException | NumberFormatException e)
		{
			return null;
		}
	}

	private static Integer id(String key)
	{
		try
		{
			return Integer.parseInt(key.trim());
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private static Long number(JsonElement e)
	{
		if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber())
		{
			return null;
		}
		return e.getAsLong();
	}

	/** What the copy is worth at these prices; items with no price count as nothing, as in the ledger. */
	public long value(Prices prices)
	{
		long total = 0;
		for (Map.Entry<Integer, Long> e : items.entrySet())
		{
			// Each figure is at most a stack's or an item's top price, so the product fits; the sum is held at its ceiling.
			long price = Math.min(prices.price(e.getKey()), Integer.MAX_VALUE);
			if (price > 0)
			{
				long worth = price * e.getValue();
				total = total > Long.MAX_VALUE - worth ? Long.MAX_VALUE : total + worth;
			}
		}
		return total;
	}

	public Map<Integer, Long> getItems()
	{
		return items;
	}

	/** When Bank Steward last saw the bank, epoch ms; 0 when it did not say. */
	public long getSavedAt()
	{
		return savedAt;
	}

	/** True when the bank held more kinds of item than Bank Steward keeps, so the copy is short. */
	public boolean isTruncated()
	{
		return truncated;
	}

	/** The estimate the panel shows while the ledger waits for the bank. */
	public static final class Estimate
	{
		private final long bank;
		private final long savedAt;
		private final int kinds;
		private final boolean truncated;

		public Estimate(long bank, long savedAt, int kinds, boolean truncated)
		{
			this.bank = bank;
			this.savedAt = savedAt;
			this.kinds = kinds;
			this.truncated = truncated;
		}

		/** The copied bank's worth at today's prices. */
		public long getBank()
		{
			return bank;
		}

		public long getSavedAt()
		{
			return savedAt;
		}

		/** Kinds of item in the copy. */
		public int getKinds()
		{
			return kinds;
		}

		public boolean isTruncated()
		{
			return truncated;
		}
	}

	/** The estimate at these prices. */
	public Estimate estimate(Prices prices)
	{
		return new Estimate(value(prices), savedAt, items.size(), truncated);
	}
}

package com.codex.ledger.core;

/**
 * Where a day's play came from: the gold made or lost, split by how it happened. Market (prices
 * moving on what was held) is not play and is kept apart.
 */
public enum Channel
{
	/** Bought and sold on the Grand Exchange, against the market price and after tax. */
	EXCHANGE("Exchange"),
	/** Items that came in from anywhere else. */
	LOOT("Loot"),
	/** Items that went out other than by a sale. */
	USED("Supplies"),
	/** Coins that came in from anywhere but the exchange. */
	COINS_IN("Coins in"),
	/** Coins that went out to anything but the exchange. */
	COINS_OUT("Coins out"),
	/** Lost on death, less what was got back. */
	DEATHS("Deaths");

	private final String label;

	Channel(String label)
	{
		this.label = label;
	}

	public String getLabel()
	{
		return label;
	}
}

package com.codex.ledger.core;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * One page of the day book: the worth the day opened and closed on, its high and low, and how
 * the change splits into what the player gained or spent (play) and what prices did (market).
 */
public final class Day
{
	/** Items kept on a page once its day is over. */
	static final int KEPT_ITEMS = 16;
	/** Items kept on a page older than the Trades page reaches, where only the biggest movers matter. */
	static final int OLD_ITEMS = 6;
	/** Items a page may hold while its day is still being written. */
	static final int OPEN_ITEMS = 300;
	/** Items traded on the exchange kept on a page once its day is over; the day's trade totals stay whole. */
	static final int KEPT_DEALS = 24;

	private String date;
	private long open;
	private long close;
	private long high;
	private long low;
	private long play;
	private long market;
	private Map<Integer, Flow> items = new HashMap<>();

	// Where the day's play came from. Together they make up the play figure; pages written before
	// they were kept read them as nothing. See Channel.
	/** Bought and sold on the exchange: what was paid or received against the market price, after tax. */
	private long ex;
	/** Items that came in from anywhere else: loot, gathering, shops, rewards. */
	private long loot;
	/** Items that went out other than by a sale: eaten, used up, alched, dropped. */
	private long used;
	/** Coins that came in from anywhere but the exchange: alchemy, shops, rewards. */
	private long cin;
	/** Coins that went out to anything but the exchange: shops, fees, upkeep. */
	private long cout;
	/** Lost on death, less what was got back from the gravestone or Death. */
	private long dead;

	/** The day's trades on the exchange, by item; trimmed to the biggest once the day is over. */
	private Map<Integer, Deal> deals = new HashMap<>();
	/** The whole day's trading, which trimming leaves alone. */
	private Deal trades = new Deal();
	/** Milliseconds logged in on this day; nothing on pages written before it was kept. */
	private long ms;
	/** Worth by kind when the page last settled, by {@link Kind} ordinal; null before kinds were kept. */
	private long[] kinds;
	/** Worth each kind gained or lost by its items coming and going, prices held, by {@link Kind} ordinal. */
	private long[] moved;

	public Day()
	{
	}

	Day(String date, long open)
	{
		this.date = date;
		this.open = open;
		this.close = open;
		this.high = open;
		this.low = open;
	}

	void flow(int itemId, long quantity, long value, long drift, long tradedQuantity, long tradedValue)
	{
		if (value == 0 && drift == 0 && tradedValue == 0)
		{
			return;
		}
		Flow flow = items.computeIfAbsent(itemId, k -> new Flow());
		flow.add(quantity, value, drift);
		flow.traded(tradedQuantity, tradedValue);
		if (items.size() > OPEN_ITEMS)
		{
			trim(OPEN_ITEMS / 2);
		}
	}

	void totals(long play, long market, long close)
	{
		this.play += play;
		this.market += market;
		this.close = close;
		high = Math.max(high, close);
		low = Math.min(low, close);
	}

	/** Books part of the day's play to where it came from. */
	void channel(Channel channel, long value)
	{
		switch (channel)
		{
			case EXCHANGE:
				ex += value;
				break;
			case LOOT:
				loot += value;
				break;
			case USED:
				used += value;
				break;
			case COINS_IN:
				cin += value;
				break;
			case COINS_OUT:
				cout += value;
				break;
			default:
				dead += value;
				break;
		}
	}

	/** The day's deal in an item, opened if this is its first trade of the day. */
	Deal deal(int itemId)
	{
		if (deals == null)
		{
			deals = new HashMap<>();
		}
		return deals.computeIfAbsent(itemId, k -> new Deal());
	}

	/** What the day's trading came to, every item together. */
	public Deal getTrades()
	{
		if (trades == null)
		{
			trades = new Deal();
		}
		return trades;
	}

	public Map<Integer, Deal> getDeals()
	{
		return deals == null ? new HashMap<>() : deals;
	}

	/** Part of the day's play by where it came from. */
	public long channel(Channel channel)
	{
		switch (channel)
		{
			case EXCHANGE:
				return ex;
			case LOOT:
				return loot;
			case USED:
				return used;
			case COINS_IN:
				return cin;
			case COINS_OUT:
				return cout;
			default:
				return dead;
		}
	}

	void played(long elapsed)
	{
		ms += elapsed;
	}

	/** Time logged in on this day, or 0 on pages written before it was kept. */
	public long getPlayedMs()
	{
		return ms;
	}

	void kinds(long[] byKind)
	{
		kinds = byKind;
	}

	void moved(long[] byKind)
	{
		if (moved == null || moved.length != byKind.length)
		{
			moved = new long[byKind.length];
		}
		for (int i = 0; i < byKind.length; i++)
		{
			moved[i] += byKind[i];
		}
	}

	/**
	 * What each kind gained or lost on this day from its items coming and going, never from prices moving,
	 * or null when it was not told apart.
	 */
	public long[] getMoved()
	{
		return moved == null || moved.length != Kind.values().length ? null : moved.clone();
	}

	/** Worth by kind when the day last settled, or null when it was not told apart. */
	public long[] getKinds()
	{
		return kinds == null || kinds.length != Kind.values().length ? null : kinds.clone();
	}

	/** Worth found in a place seen for the first time is opening balance, not a gain. */
	void found(long value)
	{
		open += value;
		high = Math.max(high, open);
		low = Math.min(low, open);
	}

	/** Keeps only the items that mattered most. */
	void trim(int keep)
	{
		if (items.size() <= keep)
		{
			return;
		}
		List<Map.Entry<Integer, Flow>> list = new ArrayList<>(items.entrySet());
		list.sort(Comparator.comparingLong((Map.Entry<Integer, Flow> e) -> e.getValue().weight()).reversed());
		Map<Integer, Flow> kept = new HashMap<>();
		for (int i = 0; i < keep; i++)
		{
			kept.put(list.get(i).getKey(), list.get(i).getValue());
		}
		items = kept;
	}

	/** Keeps only the items traded the most. The day's trade totals are kept whole. */
	void trimDeals(int keep)
	{
		if (deals == null || deals.size() <= keep)
		{
			return;
		}
		if (keep <= 0)
		{
			deals = new HashMap<>();
			return;
		}
		List<Map.Entry<Integer, Deal>> list = new ArrayList<>(deals.entrySet());
		list.sort(Comparator.comparingLong((Map.Entry<Integer, Deal> e) -> e.getValue().weight()).reversed());
		Map<Integer, Deal> kept = new HashMap<>();
		for (int i = 0; i < keep; i++)
		{
			kept.put(list.get(i).getKey(), list.get(i).getValue());
		}
		deals = kept;
	}

	/** Mends a page read back from storage, where any part may be missing. */
	void repair()
	{
		if (items == null)
		{
			items = new HashMap<>();
		}
		items.keySet().removeIf(id -> id == null);
		items.values().removeIf(f -> f == null);
		if (deals == null)
		{
			deals = new HashMap<>();
		}
		deals.keySet().removeIf(id -> id == null);
		deals.values().removeIf(d -> d == null);
		if (trades == null)
		{
			trades = new Deal();
		}
	}

	public String getDate()
	{
		return date;
	}

	public long getOpen()
	{
		return open;
	}

	public long getClose()
	{
		return close;
	}

	public long getHigh()
	{
		return high;
	}

	public long getLow()
	{
		return low;
	}

	public long getPlay()
	{
		return play;
	}

	public long getMarket()
	{
		return market;
	}

	public long change()
	{
		return close - open;
	}

	public Map<Integer, Flow> getItems()
	{
		return items == null ? new HashMap<>() : items;
	}
}

package com.codex.ledger.core;

/**
 * What the player did with one item on the Grand Exchange over a stretch of time: how many were
 * bought and for how much, how many were sold and for how much after tax, and the profit the
 * sales made over what those same items had cost.
 *
 * <p>Sales are matched against the average cost of the items bought while the ledger was
 * watching. Items sold that were never bought on the ledger's watch (loot, or bought before it
 * began) have no cost to match, so their sale is kept apart and makes no profit or loss.
 */
public final class Deal
{
	/** Bought: items and the coins paid. */
	private long bq;
	private long bc;
	/** Sold: items and the coins received after tax. */
	private long sq;
	private long sc;
	/** Tax the exchange kept from the sales. */
	private long tx;
	/** Profit on the sales that were matched to a cost. */
	private long p;
	/** Sold with no cost to match: items and the coins they brought. */
	private long uq;
	private long uc;

	public Deal()
	{
	}

	void bought(long quantity, long coins)
	{
		bq += quantity;
		bc += coins;
	}

	void sold(long quantity, long coins, long tax, long profit, long unmatched, long unmatchedCoins)
	{
		sq += quantity;
		sc += coins;
		tx += tax;
		p += profit;
		uq += unmatched;
		uc += unmatchedCoins;
	}

	void add(Deal other)
	{
		bought(other.bq, other.bc);
		sold(other.sq, other.sc, other.tx, other.p, other.uq, other.uc);
	}

	public long getBought()
	{
		return bq;
	}

	public long getBuyCoins()
	{
		return bc;
	}

	public long getSold()
	{
		return sq;
	}

	/** Coins the sales brought in, after tax. */
	public long getSaleCoins()
	{
		return sc;
	}

	public long getTax()
	{
		return tx;
	}

	/** Profit on the sales matched to what the items had cost, after tax. */
	public long getProfit()
	{
		return p;
	}

	/** Items sold with no cost to match, whose sale makes no profit or loss here. */
	public long getUnmatched()
	{
		return uq;
	}

	public long getUnmatchedCoins()
	{
		return uc;
	}

	/** Coins that changed hands either way. */
	public long volume()
	{
		return bc + sc + tx;
	}

	/** The profit against what the matched sales had cost, or 0 when nothing matched. */
	public double roi()
	{
		long matchedCoins = sc - uc;
		long cost = matchedCoins - p;
		return cost <= 0 ? 0 : p / (double) cost;
	}

	/** How much this deal mattered, for ranking and trimming. */
	long weight()
	{
		return Math.abs(p) * 4 + volume();
	}
}

package com.codex.ledger.core;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * What pays: net worth gained an hour played, by what the play was spent on. The activities come
 * from Codex Session Chronicle's journal (group "codexsessionchronicle", key "journal"), read and
 * never written: each filed session's "startedAt", "playedMs", "activity" (its main monster or
 * skill) and the net worth this ledger had as it began and ended ("worthStart", "worthNow"). So the
 * figure counts everything: loot, supplies used, deaths, trades and prices moving.
 */
public final class Earnings
{
	/** Days of sessions counted. */
	public static final int DAYS = 30;
	/** A session must be at least this long for its rate to count, as Chronicle's own records do. */
	static final long MIN_PLAYED_MS = 15 * 60_000L;
	/** More than any account is worth; a worth past it (or below nothing) is a damaged save. */
	static final long MAX_WORTH = 10_000_000_000_000L;
	/** A session's play may run this far past the time since it began, for clocks a moment apart. */
	static final long CLOCK_SLACK_MS = 60_000L;
	/** Activities shown at most. */
	public static final int SHOWN = 6;

	/** One of Chronicle's filed sessions, as far as the ledger needs it. */
	public static final class Logged
	{
		long startedAt;
		long playedMs;
		Long worthStart;
		Long worthNow;
		String activity;

		Logged()
		{
		}

		Logged(long startedAt, long playedMs, Long worthStart, Long worthNow, String activity)
		{
			this.startedAt = startedAt;
			this.playedMs = playedMs;
			this.worthStart = worthStart;
			this.worthNow = worthNow;
			this.activity = activity;
		}
	}

	/**
	 * Reads Chronicle's saved journal; empty when there is none or it cannot be read. A session that
	 * cannot be read is left out on its own, so one broken entry does not hide the rest.
	 */
	public static List<Logged> read(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return Collections.emptyList();
		}
		JsonElement root;
		try
		{
			root = gson.fromJson(json, JsonElement.class);
		}
		catch (RuntimeException e)
		{
			return Collections.emptyList();
		}
		if (root == null || !root.isJsonArray())
		{
			return Collections.emptyList();
		}
		List<Logged> out = new ArrayList<>();
		for (JsonElement entry : root.getAsJsonArray())
		{
			try
			{
				Logged s = entry.isJsonObject() ? gson.fromJson(entry, Logged.class) : null;
				if (s != null)
				{
					out.add(s);
				}
			}
			catch (RuntimeException e)
			{
				// This session only; the others still count.
			}
		}
		return out;
	}

	/** One activity's earnings over the window. */
	public static final class Line
	{
		private final String name;
		private int sessions;
		private long playedMs;
		private long change;

		Line(String name)
		{
			this.name = name;
		}

		public String getName()
		{
			return name;
		}

		public int getSessions()
		{
			return sessions;
		}

		public long getPlayedMs()
		{
			return playedMs;
		}

		/** Net worth gained over its sessions. */
		public long getChange()
		{
			return change;
		}

		/** Net worth gained an hour played. */
		public long perHour()
		{
			return playedMs <= 0 ? 0 : Math.round(change * 3_600_000.0 / playedMs);
		}
	}

	private final List<Line> lines;
	private final int days;

	private Earnings(List<Line> lines, int days)
	{
		this.lines = Collections.unmodifiableList(lines);
		this.days = days;
	}

	/**
	 * Earnings by activity over the last {@link #DAYS} days, best paying first. Sessions without both
	 * worth figures (Ledger had not seen the bank), without an activity or shorter than a quarter of
	 * an hour are left out; so is a second session begun at the same moment.
	 */
	public static Earnings of(Collection<Logged> journal, long now)
	{
		long from = now - DAYS * 86_400_000L;
		Map<String, Line> by = new LinkedHashMap<>();
		Set<Long> seen = new HashSet<>();
		long earliest = now;
		for (Logged s : journal)
		{
			if (s == null || s.activity == null || s.activity.trim().isEmpty() || s.worthStart == null || s.worthNow == null
				|| s.playedMs < MIN_PLAYED_MS || s.startedAt < from || s.startedAt > now
				// Played for longer than the time since it began, or worth no account has: not a session that happened.
				|| s.playedMs > now - s.startedAt + CLOCK_SLACK_MS || !plausible(s.worthStart) || !plausible(s.worthNow)
				|| !seen.add(s.startedAt))
			{
				continue;
			}
			String name = s.activity.trim();
			Line line = by.computeIfAbsent(name.toLowerCase(Locale.ROOT), k -> new Line(name));
			line.sessions++;
			line.playedMs += s.playedMs;
			line.change += s.worthNow - s.worthStart;
			earliest = Math.min(earliest, s.startedAt);
		}
		List<Line> lines = new ArrayList<>(by.values());
		lines.sort((a, b) -> Long.compare(b.perHour(), a.perHour()));
		int days = (int) Math.max(1, Math.min(DAYS, (now - earliest + 86_399_999L) / 86_400_000L));
		return new Earnings(lines, days);
	}

	private static boolean plausible(long worth)
	{
		return worth >= 0 && worth <= MAX_WORTH;
	}

	/** Activities, best paying an hour first. */
	public List<Line> getLines()
	{
		return lines;
	}

	/** Days the sessions were counted over: fewer than {@link #DAYS} while the journal is younger. */
	public int getDays()
	{
		return days;
	}

	public boolean isEmpty()
	{
		return lines.isEmpty();
	}
}

package com.codex.ledger.core;

/**
 * What one item did to the account's worth over a stretch of time: how many came or went,
 * what that came to at the day's prices, and how much the price moving changed what was held.
 */
public final class Flow
{
	/** Net quantity gained (or lost, when negative). */
	private long q;
	/** Value gained or lost by quantity changing, at the price of the moment. */
	private long v;
	/** Value gained or lost by the price moving on what was already held. */
	private long d;
	/** The part of the quantity that was bought or sold on the Grand Exchange. */
	private long tq;
	/** What that part came to at the price of the moment. */
	private long tv;

	public Flow()
	{
	}

	public Flow(long quantity, long value, long drift)
	{
		this.q = quantity;
		this.v = value;
		this.d = drift;
	}

	void add(long quantity, long value, long drift)
	{
		q += quantity;
		v += value;
		d += drift;
	}

	void traded(long quantity, long value)
	{
		tq += quantity;
		tv += value;
	}

	void add(Flow other)
	{
		add(other.q, other.v, other.d);
		traded(other.tq, other.tv);
	}

	public long getQuantity()
	{
		return q;
	}

	public long getValue()
	{
		return v;
	}

	public long getDrift()
	{
		return d;
	}

	/** The quantity gained or lost other than by trading on the Grand Exchange. */
	public long getOwnQuantity()
	{
		return q - tq;
	}

	/** The value gained or lost other than by trading on the Grand Exchange. */
	public long getOwnValue()
	{
		return v - tv;
	}

	/** How much this item mattered either way, for ranking and trimming. */
	long weight()
	{
		return Math.abs(v) + Math.abs(d);
	}
}

package com.codex.ledger.core;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

/**
 * Where the account's worth is heading: how fast it has grown over the last month, counted over
 * every calendar day (days off included, so the pace is an honest one), and when a goal falls at
 * that pace.
 */
public final class Forecast
{
	/** Days the pace is taken over. */
	public static final int WINDOW = 30;
	/** Days of pages needed before a pace means anything. */
	public static final int MIN_DAYS = 3;
	/** Further than this and the date says nothing useful. */
	static final long HORIZON_DAYS = 3_650;
	/** Round figures to aim at when no goal is set. */
	private static final long[] MARKS = {
		1_000_000L, 5_000_000L, 10_000_000L, 25_000_000L, 50_000_000L, 100_000_000L, 250_000_000L, 500_000_000L,
		750_000_000L, 1_000_000_000L, 1_500_000_000L, 2_000_000_000L
	};

	private final long worth;
	private final long target;
	private final boolean goalSet;
	private final int days;
	private final double perDay;
	private final LocalDate eta;

	private Forecast(long worth, long target, boolean goalSet, int days, double perDay, LocalDate eta)
	{
		this.worth = worth;
		this.target = target;
		this.goalSet = goalSet;
		this.days = days;
		this.perDay = perDay;
		this.eta = eta;
	}

	/**
	 * @param goal the worth aimed at, or 0 or less for the next round figure
	 */
	public static Forecast of(Ledger ledger, LocalDate today, long goal)
	{
		long worth = ledger.getTotal();
		boolean goalSet = goal > 0;
		long target = goalSet ? goal : nextMark(worth);
		Report report = Report.of(ledger, WINDOW, today, 0);
		int days = report.getDays() == 0 ? 0 : (int) ChronoUnit.DAYS.between(report.getFrom(), today) + 1;
		if (days < MIN_DAYS)
		{
			return new Forecast(worth, target, goalSet, days, 0, null);
		}
		double perDay = report.change() / (double) days;
		LocalDate eta = null;
		if (worth < target && perDay > 0)
		{
			long ahead = (long) Math.ceil((target - worth) / perDay);
			eta = ahead <= HORIZON_DAYS ? today.plusDays(ahead) : null;
		}
		return new Forecast(worth, target, goalSet, days, perDay, eta);
	}

	/** The next round figure above a worth. */
	static long nextMark(long worth)
	{
		for (long mark : MARKS)
		{
			if (worth < mark)
			{
				return mark;
			}
		}
		long billion = 1_000_000_000L;
		return (worth / billion + 1) * billion;
	}

	public long getTarget()
	{
		return target;
	}

	/** True when the target is the player's own goal rather than the next round figure. */
	public boolean isGoalSet()
	{
		return goalSet;
	}

	/** Calendar days the pace was taken over, or fewer than needed when it is too early to say. */
	public int getDays()
	{
		return days;
	}

	public boolean hasPace()
	{
		return days >= MIN_DAYS;
	}

	/** Worth gained a day on average over the window, or 0 when too early to say. */
	public double getPerDay()
	{
		return perDay;
	}

	public boolean isReached()
	{
		return worth >= target;
	}

	/** How far along the way to the target the worth is, 0 to 1. */
	public double progress()
	{
		return target <= 0 ? 1 : Math.max(0, Math.min(1, worth / (double) target));
	}

	public long remaining()
	{
		return Math.max(0, target - worth);
	}

	/** The day the target falls at this pace, or null when it is reached, falling away or years off. */
	public LocalDate getEta()
	{
		return eta;
	}
}

package com.codex.ledger.core;

import java.util.ArrayList;
import java.util.List;

/**
 * Keeps the worth history small without losing its shape: fine detail for the last two days,
 * a point every few hours for the last six weeks, and one a day beyond that.
 */
public final class History
{
	static final long MINUTE = 60_000L;
	static final long HOUR = 60 * MINUTE;
	static final long DAY = 24 * HOUR;
	/** Points kept at most, whatever their age. */
	static final int MAX_POINTS = 1_200;

	private History()
	{
	}

	/** The width of the time bucket a point of this age shares with its neighbours. */
	static long bucket(long age)
	{
		if (age < 2 * DAY)
		{
			return 15 * MINUTE;
		}
		if (age < 45 * DAY)
		{
			return 3 * HOUR;
		}
		return DAY;
	}

	/** Keeps the last point in every bucket, oldest first. The newest point is always kept. */
	public static List<Ledger.Point> compact(List<Ledger.Point> points, long now)
	{
		List<Ledger.Point> kept = new ArrayList<>();
		for (int i = 0; i < points.size(); i++)
		{
			Ledger.Point p = points.get(i);
			if (i == points.size() - 1)
			{
				kept.add(p);
				break;
			}
			Ledger.Point next = points.get(i + 1);
			long size = bucket(now - p.getTime());
			long nextSize = bucket(now - next.getTime());
			if (size != nextSize || p.getTime() / size != next.getTime() / size)
			{
				kept.add(p);
			}
		}
		if (kept.size() > MAX_POINTS)
		{
			kept.subList(0, kept.size() - MAX_POINTS).clear();
		}
		return kept;
	}
}

package com.codex.ledger.core;

/**
 * What a held item is, so the worth can be told apart by kind: coins to spend, gear worn into
 * fights, supplies that get used up, and the materials and everything else waiting to be used or sold.
 */
public enum Kind
{
	/** Coins and platinum tokens. */
	CASH("Coins"),
	/** Anything worn, bar ammunition and thrown weapons. */
	GEAR("Gear"),
	/** Food, potions, runes, ammunition and teleports: what fights and trips use up. */
	SUPPLIES("Supplies"),
	/** Logs, ores, bones, herbs, seeds and the rest. */
	MATERIALS("Materials");

	private final String label;

	Kind(String label)
	{
		this.label = label;
	}

	public String getLabel()
	{
		return label;
	}
}

package com.codex.ledger.core;

import java.util.Locale;

/** Tells what a held item is from what the game says about it: its name, its menu and whether it is worn. */
public final class Kinds
{
	static final int PLATINUM = 13204;
	/** The equipment slot ammunition goes in. */
	static final int AMMO_SLOT = 13;

	private Kinds()
	{
	}

	/**
	 * @param actions the item's inventory menu, any entry of which may be null
	 * @param slot the equipment slot it is worn in, when equipable
	 * @param stackable whether it stacks in the inventory, as darts, knives and chinchompas do
	 */
	public static Kind of(int itemId, String name, String[] actions, boolean equipable, int slot, boolean stackable)
	{
		if (itemId == Ledger.COINS || itemId == PLATINUM)
		{
			return Kind.CASH;
		}
		if (equipable)
		{
			// Ammunition and thrown weapons are used up like supplies; everything else worn is gear.
			return slot == AMMO_SLOT || stackable ? Kind.SUPPLIES : Kind.GEAR;
		}
		if (actions != null)
		{
			for (String action : actions)
			{
				if ("Eat".equals(action) || "Drink".equals(action) || "Break".equals(action))
				{
					return Kind.SUPPLIES;
				}
			}
		}
		String n = name == null ? "" : name.toLowerCase(Locale.ROOT);
		if (n.endsWith(" rune") || n.endsWith(" teleport") || n.contains("teleport scroll"))
		{
			return Kind.SUPPLIES;
		}
		return Kind.MATERIALS;
	}
}

package com.codex.ledger.core;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntFunction;
import java.util.function.Function;

/**
 * An account's ledger: what it holds in each place, what each item was last worth, the worth
 * over time and a day book of where it came from and went.
 *
 * <p>Places are seen one at a time (the bank only while it is open), so the ledger remembers each
 * as last seen. Changes are gathered and settled together once a tick, so an item moving from the
 * bank to the inventory is a move, not a loss and a gain. Every settle splits the change in worth
 * into play (items gained or spent, at today's price) and market (prices moving on what was held).
 *
 * <p>The ledger begins when the bank is first seen; until then the total is only part of the story.
 */
public final class Ledger
{
	/** Pages kept in the day book. */
	public static final int DAYS = 120;
	static final int COINS = 995;
	static final int BOND = 13190;
	static final int LOOTING_BAG = 11941;
	static final int LOOTING_BAG_OPEN = 22586;
	/** Items whose trades are remembered at most; those no longer held and traded longest ago go first. */
	static final int BOOK = 300;
	/**
	 * How long after dying items leaving the account are lost to the death rather than used. The
	 * game takes them when the player is sent home, a few ticks after the death itself.
	 */
	static final long DYING_MS = 15_000;
	/** Pages whose deals by item are kept: the Trades page reaches back 30 days, older pages keep their day's totals. */
	static final int DEAL_DAYS = 30;
	/** How long after dying getting the same items back counts against that death. */
	static final long REGAIN_MS = 3_600_000L;

	private Map<Store, Holding> stores = new LinkedHashMap<>();
	private Map<Integer, Long> prices = new HashMap<>();
	private List<Point> history = new ArrayList<>();
	private List<Day> days = new ArrayList<>();
	private long total;
	private long since;
	/** Each Grand Exchange slot as last seen; missing from ledgers saved before slots were kept. */
	private Map<Integer, Offer> exchange = new HashMap<>();
	/** Each item's standing on the exchange since the ledger began watching trades. */
	private Map<Integer, Position> book = new HashMap<>();
	/**
	 * True once the slots have been seen whole while the ledger was open, so an offer seen for the
	 * first time after that was placed since and its progress is trading done since.
	 */
	private boolean slotsKnown;
	/** What the last death took, by item, while getting it back still counts against it. */
	private Map<Integer, Long> lost = new HashMap<>();
	private long lostUntil;

	private transient Map<Store, Map<Integer, Long>> pending;
	/** Slots seen since the last settle; a null offer is an empty slot. */
	private transient Map<Integer, Offer> pendingOffers;
	private transient boolean atExchange;
	private transient long dyingUntil;
	/** Set when the death took something at this settle; the death is then over and what goes after is used, not lost. */
	private transient boolean tookByDeath;
	/** Trades seen at the last settle of the exchange. */
	private transient List<Fill> fills;
	/** Tells what each item is, so the worth can be split by kind; null leaves days without it. */
	private transient IntFunction<Kind> kinds;
	/** When play time was last counted, or 0 after a gap. */
	private transient long lastPlayed;
	/** True when reading the save had to leave part of it out; see {@link #isMended()}. */
	private transient boolean mended;
	/** The longest damaged save set aside; one past it is only logged, so the profile never doubles in size for it. */
	public static final int MAX_ASIDE = 1_000_000;

	/** Part of an offer that traded between two sightings of its slot. */
	private static final class Fill
	{
		final int item;
		final boolean buy;
		final long quantity;
		/** Coins paid for a buy, or received before tax for a sale. */
		final long coins;
		final long tax;

		Fill(int item, boolean buy, long quantity, long coins, long tax)
		{
			this.item = item;
			this.buy = buy;
			this.quantity = quantity;
			this.coins = coins;
			this.tax = tax;
		}
	}

	/** One place as last seen. */
	public static final class Holding
	{
		private long seen;
		private Map<Integer, Long> items;

		public Holding()
		{
		}

		Holding(long seen, Map<Integer, Long> items)
		{
			this.seen = seen;
			this.items = items;
		}

		public long getSeen()
		{
			return seen;
		}

		public Map<Integer, Long> getItems()
		{
			return items == null ? Collections.emptyMap() : items;
		}
	}

	/** The worth at a moment. */
	public static final class Point
	{
		private long t;
		private long v;

		public Point()
		{
		}

		public Point(long time, long value)
		{
			this.t = time;
			this.v = value;
		}

		public long getTime()
		{
			return t;
		}

		public long getValue()
		{
			return v;
		}
	}

	/** Records what a place holds now; it counts at the next settle. Quantities of zero or less are dropped. */
	public void observe(Store store, Map<Integer, Long> items)
	{
		Map<Integer, Long> copy = new HashMap<>();
		for (Map.Entry<Integer, Long> e : items.entrySet())
		{
			if (e.getValue() != null && e.getValue() > 0)
			{
				copy.merge(e.getKey(), e.getValue(), Long::sum);
			}
		}
		if (pending == null)
		{
			pending = new EnumMap<>(Store.class);
		}
		pending.put(store, copy);
	}

	/** Records what a Grand Exchange slot holds now, or null when it is empty; it counts at the next settle. */
	public void offer(int slot, Offer offer)
	{
		if (pendingOffers == null)
		{
			pendingOffers = new HashMap<>();
		}
		pendingOffers.put(slot, offer);
	}

	/**
	 * Whether the player has the Grand Exchange or a collection box open, where items arriving in
	 * the inventory may be collected from an offer that is still trading.
	 */
	public void setAtExchange(boolean atExchange)
	{
		this.atExchange = atExchange;
	}

	/**
	 * The player died: what leaves the account in the next moments is lost to the death, and what
	 * comes back from the gravestone or Death in the hour after is set against it.
	 */
	public void died(long now)
	{
		dyingUntil = now + DYING_MS;
		lost = new HashMap<>();
		lostUntil = now + REGAIN_MS;
	}

	/** Sets how items are told apart by kind; it is asked once per item held at each settle. */
	public void setKinds(IntFunction<Kind> kinds)
	{
		this.kinds = kinds;
	}

	/** A gap between two calls longer than this is time away, not play. */
	static final long PLAY_GAP_MS = 5_000;

	/**
	 * Counts logged-in time toward today's page. Called every game tick while logged in; the time
	 * between two calls counts unless it is a gap (a login, a loading screen, a stall).
	 *
	 * @return true when the time counted
	 */
	public boolean played(long now, ZoneId zone)
	{
		long last = lastPlayed;
		lastPlayed = now;
		if (!isReady() || last <= 0 || now <= last || now - last > PLAY_GAP_MS)
		{
			return false;
		}
		today(now, zone).played(now - last);
		return true;
	}

	/** Play time stops counting until the next call; for a logout or a hop. */
	public void pause()
	{
		lastPlayed = 0;
	}

	public boolean hasPending()
	{
		return pending != null && !pending.isEmpty() || pendingOffers != null && !pendingOffers.isEmpty();
	}

	/**
	 * Counts everything observed since the last settle and revalues what is held at today's prices.
	 *
	 * @return true when the worth or the day book changed
	 */
	public boolean settle(long now, Prices market, ZoneId zone)
	{
		Map<Integer, Long> before = aggregate();
		Map<Integer, Long> found = new HashMap<>();
		boolean wasReady = isReady();
		if (pending == null)
		{
			pending = new EnumMap<>(Store.class);
		}
		Map<Integer, Long> collected = settleExchange(wasReady);
		emptyLostLootingBag();
		if (!pending.isEmpty())
		{
			collectToBank(collected);
			for (Map.Entry<Store, Map<Integer, Long>> e : pending.entrySet())
			{
				if (!stores.containsKey(e.getKey()))
				{
					for (Map.Entry<Integer, Long> item : e.getValue().entrySet())
					{
						found.merge(item.getKey(), item.getValue(), Long::sum);
					}
				}
				stores.put(e.getKey(), new Holding(now, e.getValue()));
			}
			pending.clear();
		}
		for (Map.Entry<Integer, Long> e : found.entrySet())
		{
			before.merge(e.getKey(), e.getValue(), Long::sum);
		}
		Map<Integer, Long> after = aggregate();

		Set<Integer> ids = new HashSet<>(before.keySet());
		ids.addAll(after.keySet());
		boolean ready = isReady();
		boolean opening = ready && !wasReady;
		Day day = ready && !opening ? today(now, zone) : null;
		// What trading moved, by item, so it can be told apart from everything else that came and went.
		Map<Integer, Long> traded = new HashMap<>();
		if (day != null)
		{
			for (Fill f : fills)
			{
				traded.merge(f.item, f.buy ? f.quantity : -f.quantity, Long::sum);
				traded.merge(COINS, f.buy ? -f.coins : f.coins - f.tax, Long::sum);
			}
			ids.addAll(traded.keySet());
		}
		long play = 0;
		long drift = 0;
		long foundValue = 0;
		long worth = 0;
		long[] byKind = kinds == null ? null : new long[Kind.values().length];
		long[] movedKind = kinds == null ? null : new long[Kind.values().length];
		for (int id : ids)
		{
			long oldQ = before.getOrDefault(id, 0L);
			long newQ = after.getOrDefault(id, 0L);
			Long known = prices.get(id);
			long price = market.price(id);
			if (price <= 0)
			{
				price = known != null ? known : 0;
			}
			long oldPrice = known != null ? known : price;
			long value = (newQ - oldQ) * price;
			long moved = oldQ * (price - oldPrice);
			worth += newQ * price;
			if (byKind != null && (newQ > 0 || value != 0))
			{
				Kind kind = id == COINS ? Kind.CASH : kinds.apply(id);
				int k = (kind == null ? Kind.MATERIALS : kind).ordinal();
				byKind[k] += newQ * price;
				// Items coming and going at today's price; a price moving is not a kind changing hands.
				movedKind[k] += value;
			}
			foundValue += found.getOrDefault(id, 0L) * oldPrice;
			play += value;
			drift += moved;
			if (day != null)
			{
				long tq = traded.getOrDefault(id, 0L);
				day.flow(id, newQ - oldQ, value, moved, tq, tq * price);
				day.channel(Channel.EXCHANGE, tq * price);
				channel(day, id, newQ - oldQ - tq, price, now);
			}
			if (newQ > 0)
			{
				prices.put(id, price);
			}
			else
			{
				prices.remove(id);
			}
		}

		if (opening)
		{
			since = now;
			history.clear();
			days.clear();
			total = worth;
			today(now, zone).kinds(byKind);
			history.add(new Point(now, worth));
			return true;
		}
		boolean changed = worth != total || play != 0 || drift != 0;
		total = worth;
		if (day != null)
		{
			changed |= book(day, after, now);
			if (foundValue != 0)
			{
				day.found(foundValue);
				// The worth history takes it as opening balance too, so the chart, the week's change and the
				// milestones do not read a place opened for the first time as worth gained.
				List<Point> shifted = new ArrayList<>(history.size());
				for (Point p : history)
				{
					shifted.add(new Point(p.getTime(), p.getValue() + foundValue));
				}
				history = shifted;
			}
			day.totals(play, drift, worth);
			if (byKind != null)
			{
				day.kinds(byKind);
				day.moved(movedKind);
			}
			if (changed || history.isEmpty())
			{
				record(now, worth);
			}
		}
		return changed;
	}

	/**
	 * Works out what the exchange holds from its slots, and what left it. An offer that is
	 * collected leaves its slot empty, and what was in it went to the inventory or the bank; one
	 * still trading may have part of it collected while the exchange is open. Progress on an
	 * offer (coins turning into items, items into coins) is not a collection.
	 *
	 * @return what was collected and did not reach the inventory
	 */
	private Map<Integer, Long> settleExchange(boolean ready)
	{
		boolean changed = false;
		Map<Integer, Long> collected = new HashMap<>();
		fills = new ArrayList<>();
		if (pendingOffers != null && !pendingOffers.isEmpty())
		{
			for (Map.Entry<Integer, Offer> e : pendingOffers.entrySet())
			{
				Offer old = exchange.get(e.getKey());
				Offer next = e.getValue();
				if (next != null && next.same(old))
				{
					fill(next, old);
					next.carry(old);
				}
				else
				{
					if (old != null)
					{
						// Collected, or collected elsewhere and the slot used again since.
						addAll(collected, old.contents());
					}
					if (next != null && slotsKnown)
					{
						// Placed since the slots were last seen; whatever it has done was traded since.
						fill(next, null);
					}
				}
				if (next == null)
				{
					exchange.remove(e.getKey());
				}
				else
				{
					exchange.put(e.getKey(), next);
				}
				changed = true;
			}
			pendingOffers.clear();
			slotsKnown |= ready;
		}

		Map<Integer, Long> gains = inventoryGains();
		for (Map.Entry<Integer, Long> e : collected.entrySet())
		{
			long found = Math.min(e.getValue(), gains.getOrDefault(e.getKey(), 0L));
			if (found > 0)
			{
				e.setValue(e.getValue() - found);
				gains.put(e.getKey(), gains.get(e.getKey()) - found);
			}
		}
		collected.values().removeIf(q -> q <= 0);
		if (atExchange && !gains.isEmpty())
		{
			for (Offer offer : exchange.values())
			{
				changed |= offer.collect(gains);
			}
		}
		if (changed)
		{
			Map<Integer, Long> held = new HashMap<>();
			for (Offer offer : exchange.values())
			{
				addAll(held, offer.contents());
			}
			pending.put(Store.GRAND_EXCHANGE, held);
		}
		return collected;
	}

	/** Notes what an offer traded since it was last seen, if anything. */
	private void fill(Offer next, Offer old)
	{
		long quantity = next.getDone() - (old == null ? 0 : old.getDone());
		if (quantity <= 0)
		{
			return;
		}
		long coins = next.getSpent() - (old == null ? 0 : old.getSpent());
		long tax = next.isBuy() ? 0 : next.tax() - (old == null ? 0 : old.tax());
		fills.add(new Fill(next.getItem(), next.isBuy(), quantity, Math.max(0, coins), Math.max(0, tax)));
	}

	/**
	 * Books what an item did to the day, other than by trading, to where it came from: loot or
	 * supplies, coins in or out, or a death.
	 *
	 * @param own the quantity gained or lost other than by trading
	 */
	private void channel(Day day, int id, long own, long price, long now)
	{
		if (own == 0 || price <= 0)
		{
			return;
		}
		if (own < 0 && now <= dyingUntil)
		{
			day.channel(Channel.DEATHS, own * price);
			lost.merge(id, -own, Long::sum);
			tookByDeath = true;
			return;
		}
		if (own > 0 && now <= lostUntil && lost.containsKey(id))
		{
			long back = Math.min(own, lost.get(id));
			day.channel(Channel.DEATHS, back * price);
			lost.put(id, lost.get(id) - back);
			lost.values().removeIf(q -> q <= 0);
			own -= back;
			if (own == 0)
			{
				return;
			}
		}
		if (id == COINS)
		{
			day.channel(own > 0 ? Channel.COINS_IN : Channel.COINS_OUT, own * price);
		}
		else
		{
			day.channel(own > 0 ? Channel.LOOT : Channel.USED, own * price);
		}
	}

	/**
	 * Books the trades of the last settle: each item's position on the exchange and the day's
	 * deals. Items bought that have since left the account other than by a sale leave the position.
	 *
	 * @return true when anything was traded
	 */
	private boolean book(Day day, Map<Integer, Long> held, long now)
	{
		if (now > lostUntil && !lost.isEmpty())
		{
			lost.clear();
		}
		if (tookByDeath)
		{
			tookByDeath = false;
			dyingUntil = 0;
		}
		for (Fill f : fills)
		{
			Position position = book.computeIfAbsent(f.item, k -> new Position());
			Deal deal = day.deal(f.item);
			if (f.buy)
			{
				position.bought(f.quantity, f.coins, now);
				deal.bought(f.quantity, f.coins);
				day.getTrades().bought(f.quantity, f.coins);
			}
			else
			{
				position.sold(f.quantity, f.coins - f.tax, f.tax, now, deal, day.getTrades());
			}
		}
		for (Map.Entry<Integer, Position> e : book.entrySet())
		{
			e.getValue().holdAtMost(held.getOrDefault(e.getKey(), 0L));
		}
		trimBook(BOOK);
		boolean traded = !fills.isEmpty();
		fills.clear();
		return traded;
	}

	/** Items the inventory gained since it was last seen, when it is being seen now. */
	private Map<Integer, Long> inventoryGains()
	{
		Map<Integer, Long> gains = new HashMap<>();
		Map<Integer, Long> now = pending.get(Store.INVENTORY);
		Holding then = stores.get(Store.INVENTORY);
		if (now == null || then == null)
		{
			return gains;
		}
		for (Map.Entry<Integer, Long> e : now.entrySet())
		{
			long gain = e.getValue() - then.getItems().getOrDefault(e.getKey(), 0L);
			if (gain > 0)
			{
				gains.put(e.getKey(), gain);
			}
		}
		return gains;
	}

	/**
	 * What was collected from the exchange and did not reach the inventory went to the bank, so it
	 * is put there now rather than counted lost until the bank is next opened. Opening the bank
	 * replaces this guess with what is really there.
	 */
	private void collectToBank(Map<Integer, Long> collected)
	{
		Holding bank = stores.get(Store.BANK);
		if (collected == null || collected.isEmpty() || bank == null || pending.containsKey(Store.BANK))
		{
			return;
		}
		Map<Integer, Long> banked = new HashMap<>(bank.getItems());
		addAll(banked, collected);
		stores.put(Store.BANK, new Holding(bank.getSeen(), banked));
	}

	/**
	 * A looting bag that is in neither the inventory nor the bank was lost with what was in it
	 * (it is only ever opened in the wilderness, where a death keeps nothing), so its contents go.
	 */
	private void emptyLostLootingBag()
	{
		Map<Integer, Long> inv = pending.get(Store.INVENTORY);
		Holding bag = stores.get(Store.LOOTING_BAG);
		if (inv == null || bag == null || bag.getItems().isEmpty() || pending.containsKey(Store.LOOTING_BAG)
			|| inv.containsKey(LOOTING_BAG) || inv.containsKey(LOOTING_BAG_OPEN))
		{
			return;
		}
		Map<Integer, Long> bank = pending.containsKey(Store.BANK) ? pending.get(Store.BANK)
			: stores.containsKey(Store.BANK) ? stores.get(Store.BANK).getItems() : Collections.emptyMap();
		if (bank.containsKey(LOOTING_BAG) || bank.containsKey(LOOTING_BAG_OPEN))
		{
			return;
		}
		pending.put(Store.LOOTING_BAG, new HashMap<>());
	}

	private static void addAll(Map<Integer, Long> into, Map<Integer, Long> items)
	{
		for (Map.Entry<Integer, Long> e : items.entrySet())
		{
			into.merge(e.getKey(), e.getValue(), Long::sum);
		}
	}

	/** Today's page, opening a new one on the worth carried over when the date has turned. */
	private Day today(long now, ZoneId zone)
	{
		String date = Instant.ofEpochMilli(now).atZone(zone).toLocalDate().toString();
		Day last = days.isEmpty() ? null : days.get(days.size() - 1);
		if (last != null && date.equals(last.getDate()))
		{
			return last;
		}
		if (last != null)
		{
			last.trim(Day.KEPT_ITEMS);
			last.trimDeals(Day.KEPT_DEALS);
		}
		Day day = new Day(date, total);
		days.add(day);
		if (days.size() > DEAL_DAYS)
		{
			Day old = days.get(days.size() - 1 - DEAL_DAYS);
			old.trimDeals(0);
			old.trim(Day.OLD_ITEMS);
		}
		while (days.size() > DAYS)
		{
			days.remove(0);
		}
		return day;
	}

	private void record(long now, long worth)
	{
		history.add(new Point(now, worth));
		history = History.compact(history, now);
	}

	private Map<Integer, Long> aggregate()
	{
		Map<Integer, Long> all = new HashMap<>();
		for (Holding h : stores.values())
		{
			for (Map.Entry<Integer, Long> e : h.getItems().entrySet())
			{
				all.merge(e.getKey(), e.getValue(), Long::sum);
			}
		}
		return all;
	}

	/** True once the bank has been seen, which is when the ledger begins. */
	public boolean isReady()
	{
		return stores.containsKey(Store.BANK);
	}

	public long getTotal()
	{
		return total;
	}

	public long getSince()
	{
		return since;
	}

	public Map<Store, Holding> getStores()
	{
		return Collections.unmodifiableMap(stores);
	}

	/** What a place is worth at the last settle's prices. */
	public long value(Store store)
	{
		Holding h = stores.get(store);
		return h == null ? 0 : value(h.getItems());
	}

	/** The Grand Exchange slots that hold an offer, by slot. */
	public Map<Integer, Offer> getOffers()
	{
		return Collections.unmodifiableMap(new java.util.TreeMap<>(exchange));
	}

	/** Each item's standing on the exchange since the ledger began watching trades. */
	public Map<Integer, Position> getBook()
	{
		return Collections.unmodifiableMap(book);
	}

	/** What a set of items is worth at the last settle's prices. */
	public long value(Map<Integer, Long> items)
	{
		long sum = 0;
		for (Map.Entry<Integer, Long> e : items.entrySet())
		{
			sum += e.getValue() * prices.getOrDefault(e.getKey(), 0L);
		}
		return sum;
	}

	public long price(int itemId)
	{
		return prices.getOrDefault(itemId, 0L);
	}

	/** Every item held, across every place, with its quantity. */
	public Map<Integer, Long> holdings()
	{
		return aggregate();
	}

	public List<Point> getHistory()
	{
		return Collections.unmodifiableList(history);
	}

	/** Pages of the day book, oldest first. */
	public List<Day> getDays()
	{
		return Collections.unmodifiableList(days);
	}

	/** The day book's page for a date, or null. */
	public Day day(LocalDate date)
	{
		String key = date.toString();
		for (int i = days.size() - 1; i >= 0; i--)
		{
			if (key.equals(days.get(i).getDate()))
			{
				return days.get(i);
			}
		}
		return null;
	}

	/**
	 * Trims the ledger until its saved form fits the budget, giving up the least useful detail first:
	 * items on old pages, then deals on recent ones, then trades of items long gone, then the oldest
	 * worth history down to {@link #HISTORY_FLOOR} points. What is held, every day's totals and the worth
	 * curve's shape are never given up, so a ledger whose holdings alone pass the budget stays over it,
	 * and fitting it again on every save takes nothing more away.
	 *
	 * The ledger is measured by its saved form itself, so the last one measured is the one to save:
	 * it is written out once more only for each step that took something away.
	 *
	 * @param json writes the ledger out as it stands
	 * @param saved the ledger already written out as it stands, or null
	 * @return the ledger written out after trimming
	 */
	public String fit(int budget, Function<Ledger, String> json, String saved)
	{
		String now = saved != null ? saved : json.apply(this);
		for (int step = 0; now.length() > budget && step < SHRINK_STEPS; step++)
		{
			if (shrink(step))
			{
				now = json.apply(this);
			}
		}
		return now;
	}

	private static final int SHRINK_STEPS = 5;
	/** Worth points trimming always leaves: about a year of daily points beside the recent detail. */
	static final int HISTORY_FLOOR = 400;

	/** One step of trimming; true when it took anything away. */
	private boolean shrink(int step)
	{
		int before = detail();
		int closed = days.size() - 1;
		switch (step)
		{
			case 0:
				// Pages before the Trades page's reach keep their totals and nothing by item.
				for (int i = 0; i < closed - 7; i++)
				{
					days.get(i).trim(0);
					days.get(i).trimDeals(0);
				}
				break;
			case 1:
				for (int i = Math.max(0, closed - 7); i < closed; i++)
				{
					days.get(i).trim(Day.OLD_ITEMS);
					days.get(i).trimDeals(Day.KEPT_DEALS / 3);
				}
				break;
			case 2:
				trimBook(BOOK / 3);
				break;
			case 3:
				if (closed >= 0)
				{
					days.get(closed).trim(Day.KEPT_ITEMS * 2);
				}
				break;
			default:
				// Every other one of the oldest points of the worth history, never thinning it below a
				// floor: a save over budget on every pass must not wear the curve away pass by pass.
				int spare = history.size() - HISTORY_FLOOR;
				if (spare > 0)
				{
					List<Point> thinned = new ArrayList<>();
					for (int i = 0; i < history.size(); i++)
					{
						if (i == 0 || i == history.size() - 1 || i > 2 * spare || i % 2 == 0)
						{
							thinned.add(history.get(i));
						}
					}
					history = thinned;
				}
				break;
		}
		return detail() != before;
	}

	/** A rough count of the trimmable detail, to tell whether a step took anything or the ledger has grown. */
	int detail()
	{
		int n = history.size() + book.size() + days.size();
		for (Day d : days)
		{
			n += d.getItems().size() + d.getDeals().size();
		}
		return n;
	}

	/** Keeps the trades of at most so many items: those still held first, then the most recently traded. */
	private void trimBook(int keep)
	{
		if (book.size() <= keep)
		{
			return;
		}
		List<Map.Entry<Integer, Position>> old = new ArrayList<>(book.entrySet());
		old.sort(Comparator.comparing((Map.Entry<Integer, Position> e) -> e.getValue().getHeld() > 0)
			.thenComparingLong(e -> e.getValue().getTime()));
		for (int i = 0; i < old.size() - keep; i++)
		{
			book.remove(old.get(i).getKey());
		}
	}

	/**
	 * Reads a saved ledger, or null when there is none or nothing in it can be read. A save damaged in
	 * part (a field of the wrong type, a broken entry, a place a later version knows) gives up only
	 * the part that is broken: the rest, the worth over time above all, is kept.
	 */
	public static Ledger read(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		Ledger read = parse(gson, json);
		boolean partial = read == null;
		if (read == null)
		{
			JsonElement root;
			try
			{
				root = gson.fromJson(json, JsonElement.class);
			}
			catch (RuntimeException e)
			{
				// Cut short or not JSON at all: nothing can be told apart in it.
				return null;
			}
			if (root == null || !root.isJsonObject())
			{
				return null;
			}
			JsonObject mended = new JsonObject();
			for (Map.Entry<String, JsonElement> field : root.getAsJsonObject().entrySet())
			{
				JsonElement kept = salvage(gson, field.getKey(), field.getValue());
				if (kept != null)
				{
					mended.add(field.getKey(), kept);
				}
			}
			read = parse(gson, mended.toString());
		}
		if (read == null)
		{
			return null;
		}
		// Read without an error, a later version's fields (or a place only it knows, which reads as no place)
		// are passed over in silence and would be lost at the next save: compared with what was saved.
		read.mended = partial || read.stores != null && read.stores.containsKey(null) || !covers(tree(gson, json), toTree(gson, read));
		return read.repair();
	}

	private static JsonElement tree(Gson gson, String json)
	{
		try
		{
			return gson.fromJson(json, JsonElement.class);
		}
		catch (RuntimeException | StackOverflowError e)
		{
			return null;
		}
	}

	private static JsonElement toTree(Gson gson, Object value)
	{
		try
		{
			return gson.toJsonTree(value);
		}
		catch (RuntimeException | StackOverflowError e)
		{
			return null;
		}
	}

	/**
	 * True when every field and list entry in {@code saved} is still there in {@code reread}, the value
	 * read from it written out again: nothing was passed over. Only the shape is compared, not the
	 * figures, which reading may bring back to sense; a field saved as null was nothing to lose.
	 */
	static boolean covers(JsonElement saved, JsonElement reread)
	{
		if (saved == null || saved.isJsonNull())
		{
			return true;
		}
		if (reread == null || reread.isJsonNull())
		{
			return false;
		}
		if (saved.isJsonObject())
		{
			if (!reread.isJsonObject())
			{
				return false;
			}
			JsonObject now = reread.getAsJsonObject();
			for (Map.Entry<String, JsonElement> field : saved.getAsJsonObject().entrySet())
			{
				if (!covers(field.getValue(), now.get(field.getKey())))
				{
					return false;
				}
			}
			return true;
		}
		if (saved.isJsonArray())
		{
			if (!reread.isJsonArray() || reread.getAsJsonArray().size() < saved.getAsJsonArray().size())
			{
				return false;
			}
			JsonArray then = saved.getAsJsonArray();
			JsonArray now = reread.getAsJsonArray();
			for (int i = 0; i < then.size(); i++)
			{
				if (!covers(then.get(i), now.get(i)))
				{
					return false;
				}
			}
			return true;
		}
		return true;
	}

	/**
	 * True when this ledger was read from a save that could not be read whole: part of it was left
	 * out, and the next save writes over it, so the save is set aside first.
	 */
	public boolean isMended()
	{
		return mended;
	}

	/**
	 * Whether a save that could not be read whole should be set aside in place of the copy already
	 * there, which is kept to just one: yes when there is none, and otherwise only for a save at least
	 * as long, so a later stub (a ledger begun again, then damaged) never replaces a fuller copy.
	 */
	public static boolean setAside(String kept, String damaged)
	{
		if (damaged == null || damaged.trim().isEmpty() || damaged.length() > MAX_ASIDE)
		{
			return false;
		}
		return kept == null || kept.isEmpty() || !kept.equals(damaged) && damaged.length() >= kept.length();
	}

	private static Ledger parse(Gson gson, String json)
	{
		try
		{
			return gson.fromJson(json, Ledger.class);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** True when a ledger holding just this one field reads. */
	private static boolean reads(Gson gson, String key, JsonElement value)
	{
		JsonObject one = new JsonObject();
		one.add(key, value);
		return parse(gson, one.toString()) != null;
	}

	/**
	 * What of one saved field can be read: all of it, or for a list or a map the entries that read on
	 * their own (a place this version does not know is left out), or null for none.
	 */
	private static JsonElement salvage(Gson gson, String key, JsonElement value)
	{
		if (reads(gson, key, value))
		{
			return value;
		}
		if (value.isJsonArray())
		{
			JsonArray kept = new JsonArray();
			for (JsonElement entry : value.getAsJsonArray())
			{
				JsonArray one = new JsonArray();
				one.add(entry);
				if (reads(gson, key, one))
				{
					kept.add(entry);
				}
			}
			return reads(gson, key, kept) ? kept : null;
		}
		if (value.isJsonObject())
		{
			JsonObject kept = new JsonObject();
			for (Map.Entry<String, JsonElement> entry : value.getAsJsonObject().entrySet())
			{
				if (key.equals("stores") && !isStore(entry.getKey()))
				{
					continue;
				}
				JsonObject one = new JsonObject();
				one.add(entry.getKey(), entry.getValue());
				if (reads(gson, key, one))
				{
					kept.add(entry.getKey(), entry.getValue());
				}
			}
			return reads(gson, key, kept) ? kept : null;
		}
		return null;
	}

	private static boolean isStore(String name)
	{
		for (Store store : Store.values())
		{
			if (store.name().equals(name))
			{
				return true;
			}
		}
		return false;
	}

	/** Mends a ledger read back from storage, where any part may be missing. */
	public Ledger repair()
	{
		if (stores == null)
		{
			stores = new LinkedHashMap<>();
		}
		stores.values().removeIf(h -> h == null);
		stores.keySet().removeIf(s -> s == null);
		if (prices == null)
		{
			prices = new HashMap<>();
		}
		if (history == null)
		{
			history = new ArrayList<>();
		}
		// No account is worth less than nothing, nor was before 1970: such a point is damage, not history.
		history.removeIf(p -> p == null || p.t <= 0 || p.v < 0);
		history.sort(Comparator.comparingLong(Point::getTime));
		if (history.size() > History.MAX_POINTS)
		{
			// More than this version ever keeps (an old or damaged save): thinned as it would have been, so
			// every copy and save after does not carry it all.
			history = History.compact(history, history.get(history.size() - 1).t);
		}
		if (days == null)
		{
			days = new ArrayList<>();
		}
		Set<LocalDate> dated = new HashSet<>();
		days.removeIf(d -> d == null || !dated.add(dateOf(d)));
		days.removeIf(d -> dateOf(d) == null);
		days.sort(Comparator.comparing(Ledger::dateOf));
		for (Day day : days)
		{
			day.repair();
		}
		total = Math.max(0, total);
		since = Math.max(0, since);
		if (exchange == null)
		{
			exchange = new HashMap<>();
		}
		exchange.values().removeIf(o -> o == null);
		if (book == null)
		{
			book = new HashMap<>();
		}
		book.values().removeIf(p -> p == null);
		if (lost == null)
		{
			lost = new HashMap<>();
		}
		lost.keySet().removeIf(id -> id == null);
		lost.values().removeIf(q -> q == null);
		return this;
	}

	/** A page's date, or null when what was saved is not one. */
	private static LocalDate dateOf(Day day)
	{
		try
		{
			return day.getDate() == null ? null : LocalDate.parse(day.getDate());
		}
		catch (java.time.DateTimeException e)
		{
			return null;
		}
	}
}

package com.codex.ledger.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * The round figures the worth has passed while the ledger watched: 10M, 25M, 50M, 100M and on
 * through 1B and each billion after, each with when it was first passed, and the next one ahead. A figure the worth
 * already stood above when the ledger began is no milestone of its own. Times come from the
 * worth history, which keeps a point every few hours for the last six weeks and one a day
 * before that, so a date is exact and an hour is near.
 */
public final class Milestones
{
	/** Milestones kept, the newest. */
	public static final int KEPT = 3;
	private static final long BILLION = 1_000_000_000L;

	/** One figure passed. */
	public static final class Mark
	{
		private final long amount;
		private final long at;
		private final long after;
		private final long previous;

		Mark(long amount, long at, long after, long previous)
		{
			this.amount = amount;
			this.at = at;
			this.after = after;
			this.previous = previous;
		}

		/** The milestone before it, or 0 for the first one the ledger saw. */
		public long getPrevious()
		{
			return previous;
		}

		/** The round figure. */
		public long getAmount()
		{
			return amount;
		}

		/** When the worth first stood at or above it. */
		public long getAt()
		{
			return at;
		}

		/** How long after the milestone before it, or -1 for the first one the ledger saw. */
		public long getAfter()
		{
			return after;
		}
	}

	private final List<Mark> passed;
	private final long next;
	private final long toGo;
	private final boolean regain;

	private Milestones(List<Mark> passed, long next, long toGo, boolean regain)
	{
		this.passed = passed;
		this.next = next;
		this.toGo = toGo;
		this.regain = regain;
	}

	/** The round figure above a worth, on the same ladder the Worth page's "Heading for" aims at. */
	static long above(long worth)
	{
		return worth >= Long.MAX_VALUE - 1_000_000_000L ? Long.MAX_VALUE : Forecast.nextMark(worth);
	}

	/**
	 * @param history the worth over time, oldest first
	 * @param total the worth now
	 */
	public static Milestones of(List<Ledger.Point> history, long total, long now)
	{
		List<Ledger.Point> points = new ArrayList<>();
		if (history != null)
		{
			for (Ledger.Point p : history)
			{
				if (p != null && p.getTime() <= now)
				{
					points.add(p);
				}
			}
		}
		points.add(new Ledger.Point(now, total));
		long start = points.get(0).getValue();
		long peak = start;
		List<Mark> marks = new ArrayList<>();
		long target = above(start);
		for (Ledger.Point p : points)
		{
			peak = Math.max(peak, p.getValue());
			if (p.getValue() >= target && p.getValue() / BILLION - target / BILLION > KEPT)
			{
				// Past a billion the figures come every billion; a leap over thousands of them (only ever
				// a damaged save) marks just the last few, which are all that is kept.
				target = Math.max(target, (p.getValue() / BILLION - KEPT + 1) * BILLION);
			}
			// One point can pass several figures at once, a big drop or a sale, say: each is marked then.
			while (p.getValue() >= target && target != Long.MAX_VALUE)
			{
				Mark last = marks.isEmpty() ? null : marks.get(marks.size() - 1);
				marks.add(new Mark(target, p.getTime(), last == null ? -1 : p.getTime() - last.getAt(), last == null ? 0 : last.getAmount()));
				target = above(target);
			}
		}
		Collections.reverse(marks);
		List<Mark> kept = new ArrayList<>(marks.subList(0, Math.min(KEPT, marks.size())));
		long next = above(Math.max(0, total));
		return new Milestones(kept, next, next - Math.max(0, total), next <= peak);
	}

	/** The newest figures passed, newest first; at most {@link #KEPT}. */
	public List<Mark> getPassed()
	{
		return passed;
	}

	/** The next round figure above the worth now. */
	public long getNext()
	{
		return next;
	}

	/** How far the worth now is from it. */
	public long getToGo()
	{
		return toGo;
	}

	/** True when the worth has stood above the next figure before and fallen back under it. */
	public boolean isRegain()
	{
		return regain;
	}
}

package com.codex.ledger.core;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.TreeMap;

/**
 * The day book gathered by calendar month, a statement for each: what the month made, split into
 * play and market the way each page is, the worth it closed on, how many days it has pages for and
 * its best day. Read from the pages alone, so it reaches as far back as the day book does.
 */
public final class Months
{
	/** One calendar month of pages. */
	public static final class Month
	{
		private final YearMonth month;
		private final boolean current;
		private long play;
		private long market;
		private long close;
		private int pages;
		private long playedMs;
		private LocalDate best;
		private LocalDate first;
		private LocalDate last;
		private LocalDate from;
		private long bestChange;

		Month(YearMonth month, boolean current)
		{
			this.month = month;
			this.current = current;
		}

		public YearMonth getMonth()
		{
			return month;
		}

		/** True for the month still running, whose figures are so far. */
		public boolean isCurrent()
		{
			return current;
		}

		/** What the month made: play and market together, as the day book counts a day's change. */
		public long change()
		{
			return play + market;
		}

		public long getPlay()
		{
			return play;
		}

		public long getMarket()
		{
			return market;
		}

		/** The worth the month's last page closed on. */
		public long getClose()
		{
			return close;
		}

		/** Days in the month with a page in the day book. */
		public int getPages()
		{
			return pages;
		}

		public long getPlayedMs()
		{
			return playedMs;
		}

		/** The day that gained the most, or null when no day gained. */
		public LocalDate getBest()
		{
			return best;
		}

		public long getBestChange()
		{
			return bestChange;
		}

		/**
		 * The first page, when the day book itself begins (or was trimmed) partway through this month,
		 * so its figures cover only part of it; null for a month the day book holds from its start.
		 */
		public LocalDate getFrom()
		{
			return from;
		}
	}

	private Months()
	{
	}

	/**
	 * @param days the day book's pages, oldest first
	 * @param today the player's date, to know which month is still running
	 * @param max the most months to give
	 * @return the newest months first
	 */
	public static List<Month> of(List<Day> days, LocalDate today, int max)
	{
		List<Month> out = new ArrayList<>();
		if (days == null || today == null || max <= 0)
		{
			return out;
		}
		YearMonth now = YearMonth.from(today);
		// Keyed by month, so pages out of order still land in one statement each.
		TreeMap<YearMonth, Month> months = new TreeMap<>();
		for (Day d : days)
		{
			LocalDate date;
			try
			{
				date = LocalDate.parse(d.getDate());
			}
			catch (RuntimeException e)
			{
				continue;
			}
			YearMonth ym = YearMonth.from(date);
			Month month = months.computeIfAbsent(ym, k -> new Month(k, k.equals(now)));
			month.play += d.getPlay();
			month.market += d.getMarket();
			if (month.last == null || !date.isBefore(month.last))
			{
				month.last = date;
				month.close = d.getClose();
			}
			if (month.first == null || date.isBefore(month.first))
			{
				month.first = date;
			}
			month.pages++;
			month.playedMs += d.getPlayedMs();
			long change = d.change();
			if (change > 0 && (month.best == null || change > month.bestChange))
			{
				month.best = date;
				month.bestChange = change;
			}
		}
		// Only the day book's oldest month can be cut short: the book began, or its oldest pages were
		// let go, partway through it. Any later month was watched from its first day.
		if (!months.isEmpty())
		{
			Month oldest = months.firstEntry().getValue();
			oldest.from = oldest.first.getDayOfMonth() == 1 ? null : oldest.first;
		}
		out.addAll(months.values());
		Collections.reverse(out);
		return out.size() > max ? new ArrayList<>(out.subList(0, max)) : out;
	}
}

package com.codex.ledger.core;

import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * One Grand Exchange slot as last seen, and what is sitting in it for the player to collect.
 *
 * <p>The game reports an offer's progress as running totals (bought so far, coins spent so far)
 * that do not drop when part of it is collected, so the ledger keeps what it has watched being
 * collected from a slot that is still trading and takes that off.
 */
public final class Offer
{
	/** Grand Exchange tax: 2% of each item's price, rounded down, at most 5M an item. */
	static final long TAX_PERCENT = 2;
	static final long TAX_CAP = 5_000_000L;
	/** Items sold for less than this pay no tax. */
	static final long TAX_FREE_BELOW = 50;
	/**
	 * Items the exchange never taxes, whatever their price: bonds, and the everyday supplies, teleports
	 * and tools Jagex exempted to help newer players.
	 */
	static final Set<Integer> TAX_FREE = new HashSet<>(Arrays.asList(
		Ledger.BOND,
		// Energy potions (4) to (1).
		3008, 3010, 3012, 3014,
		// Bronze, iron and steel arrows and darts; mind runes.
		882, 884, 886, 806, 807, 808, 558,
		// Bass, bread, cake, cooked chicken, cooked meat, herring, lobster, mackerel, meat pie, pike,
		// salmon, shrimps, tuna.
		365, 2309, 1891, 2140, 2142, 347, 379, 355, 2327, 351, 329, 315, 361,
		// Ardougne, Camelot, Civitas illa fortis, Falador, Kourend castle, Lumbridge and Varrock
		// teleports, teleport to house, games necklace (8), ring of dueling (8).
		8011, 8010, 28824, 8009, 28790, 8008, 8007, 8013, 3853, 2552,
		// Chisel, gardening trowel, glassblowing pipe, hammer, needle, pestle and mortar, rake, saw,
		// secateurs, seed dibber, shears, spade, watering can.
		1755, 5325, 1785, 2347, 1733, 233, 5341, 8794, 5329, 5343, 1735, 952, 5331));

	private int item;
	private boolean buy;
	private int total;
	private long price;
	private int done;
	private long spent;
	private boolean active;
	/** Items already collected from the slot while it still holds the offer. */
	private long taken;
	/** Coins already collected from the slot while it still holds the offer. */
	private long takenCoins;

	public Offer()
	{
	}

	/**
	 * @param done items bought or sold so far
	 * @param spent coins paid so far for a buy, or received before tax for a sale
	 * @param active still trading, as opposed to finished or cancelled and waiting to be collected
	 */
	public Offer(int item, boolean buy, int total, long price, int done, long spent, boolean active)
	{
		this.item = item;
		this.buy = buy;
		this.total = total;
		this.price = price;
		this.done = done;
		this.spent = spent;
		this.active = active;
	}

	/** True when both are the same offer, perhaps at different points in its progress. */
	boolean same(Offer other)
	{
		return other != null && item == other.item && buy == other.buy && total == other.total && price == other.price;
	}

	/** Carries over what was already collected from the earlier sighting of the same offer. */
	void carry(Offer earlier)
	{
		taken = Math.min(earlier.taken, buy ? done : (long) total - done);
		takenCoins = earlier.takenCoins;
	}

	/** The tax the exchange keeps from a sale of so many items for so many coins. */
	static long tax(int itemId, long sold, long gross)
	{
		if (sold <= 0 || gross <= 0 || TAX_FREE.contains(itemId))
		{
			return 0;
		}
		long each = gross / sold;
		if (each < TAX_FREE_BELOW)
		{
			return 0;
		}
		return sold * Math.min(each * TAX_PERCENT / 100, TAX_CAP);
	}

	/** What is in the slot now: the items bought or still for sale, and the coins left over or received. */
	public Map<Integer, Long> contents()
	{
		Map<Integer, Long> items = new HashMap<>();
		long held;
		long coins;
		if (buy)
		{
			held = done - taken;
			coins = price * total - spent - takenCoins;
		}
		else
		{
			held = (long) total - done - taken;
			coins = spent - tax(item, done, spent) - takenCoins;
		}
		if (held > 0)
		{
			items.put(item, held);
		}
		if (coins > 0)
		{
			items.merge(Ledger.COINS, coins, Long::sum);
		}
		return items;
	}

	/**
	 * Takes what was just collected into the inventory from a slot that still holds its offer:
	 * bought items and the change from a buy (and, once it has stopped, the coins it never spent),
	 * coins from a sale (and, once it has stopped, the items it never sold). The quantities taken
	 * are removed from {@code gains}.
	 *
	 * @return true when anything was taken
	 */
	boolean collect(Map<Integer, Long> gains)
	{
		long items;
		long coins;
		if (buy)
		{
			items = done - taken;
			// While it is still bidding only the change on what was bought can be collected.
			coins = (active ? price * done : price * total) - spent - takenCoins;
		}
		else
		{
			items = active ? 0 : (long) total - done - taken;
			coins = spent - tax(item, done, spent) - takenCoins;
		}
		long tookItems = take(gains, item, items);
		taken += tookItems;
		long tookCoins = take(gains, Ledger.COINS, coins);
		takenCoins += tookCoins;
		return tookItems > 0 || tookCoins > 0;
	}

	private static long take(Map<Integer, Long> gains, int id, long available)
	{
		long gain = gains.getOrDefault(id, 0L);
		long take = Math.min(gain, available);
		if (take <= 0)
		{
			return 0;
		}
		gains.put(id, gain - take);
		return take;
	}

	/** Coins paid so far for a buy, or received before tax for a sale. */
	public long getSpent()
	{
		return spent;
	}

	/** The tax kept so far from a sale; nothing for a buy. */
	long tax()
	{
		return buy ? 0 : tax(item, done, spent);
	}

	public int getItem()
	{
		return item;
	}

	public boolean isBuy()
	{
		return buy;
	}

	public boolean isActive()
	{
		return active;
	}

	public int getDone()
	{
		return done;
	}

	public int getTotal()
	{
		return total;
	}

	public long getPrice()
	{
		return price;
	}
}

package com.codex.ledger.core;

/**
 * One item's standing on the Grand Exchange since the ledger began watching: the items bought
 * and not yet sold with what they cost, and every trade in it added up.
 */
public final class Position
{
	/** Items bought and not yet sold, used or lost. */
	private long q;
	/** What those items cost, in coins. */
	private long c;
	/** When the item was last traded. */
	private long t;
	private Deal life = new Deal();

	public Position()
	{
	}

	void bought(long quantity, long coins, long now)
	{
		q += quantity;
		c += coins;
		t = now;
		life().bought(quantity, coins);
	}

	/**
	 * Sells against the average cost of what is held.
	 *
	 * @param coins what the sale brought in after tax
	 * @param into the day's deals, which take the same sale
	 */
	void sold(long quantity, long coins, long tax, long now, Deal... into)
	{
		long matched = Math.min(quantity, q);
		long cost = share(c, matched, q);
		long matchedCoins = share(coins, matched, quantity);
		long profit = matchedCoins - cost;
		q -= matched;
		c -= cost;
		t = now;
		life().sold(quantity, coins, tax, profit, quantity - matched, coins - matchedCoins);
		for (Deal deal : into)
		{
			deal.sold(quantity, coins, tax, profit, quantity - matched, coins - matchedCoins);
		}
	}

	/**
	 * Items bought that have since left the account other than by a sale (eaten, used up, lost)
	 * are no longer held, so their cost goes with them.
	 */
	void holdAtMost(long held)
	{
		if (q > held)
		{
			long keep = Math.max(0, held);
			c = share(c, keep, q);
			q = keep;
		}
	}

	/** A part of an amount, rounded, without overflowing on large stacks. */
	static long share(long amount, long part, long whole)
	{
		if (whole <= 0 || part <= 0)
		{
			return 0;
		}
		if (part >= whole)
		{
			return amount;
		}
		return Math.round((double) amount * part / whole);
	}

	public long getHeld()
	{
		return q;
	}

	public long getCost()
	{
		return c;
	}

	/** What each held item cost on average, or 0. */
	public long averageCost()
	{
		return q <= 0 ? 0 : Math.round(c / (double) q);
	}

	public long getTime()
	{
		return t;
	}

	public Deal life()
	{
		if (life == null)
		{
			life = new Deal();
		}
		return life;
	}
}

package com.codex.ledger.core;

/** Where the Ledger learns what an item is worth today. */
public interface Prices
{
	/** @return the item's price in coins, or 0 or less when it is not known */
	long price(int itemId);
}

package com.codex.ledger.core;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Where the gold went over a stretch of days: the change in worth split into play and market,
 * the items that brought the most in, the ones that took the most out, and the prices that moved.
 */
public final class Report
{
	/** One item's part in a report, or in the holdings. */
	public static final class Line
	{
		private final int itemId;
		private final long quantity;
		private final long value;
		private final long drift;

		public Line(int itemId, long quantity, long value, long drift)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.value = value;
			this.drift = drift;
		}

		public int getItemId()
		{
			return itemId;
		}

		public long getQuantity()
		{
			return quantity;
		}

		public long getValue()
		{
			return value;
		}

		public long getDrift()
		{
			return drift;
		}
	}

	private final LocalDate from;
	private final int days;
	private final long start;
	private final long end;
	private final long play;
	private final long market;
	private final List<Line> gains;
	private final List<Line> losses;
	private final List<Line> movers;
	private final long[] channels;
	private long playedMs;
	private long timedPlay;
	private long[] kindsNow;
	private long[] kindsBefore;
	private long[] kindsMoved;

	private Report(LocalDate from, int days, long start, long end, long play, long market, List<Line> gains, List<Line> losses, List<Line> movers,
		long[] channels)
	{
		this.channels = channels;
		this.from = from;
		this.days = days;
		this.start = start;
		this.end = end;
		this.play = play;
		this.market = market;
		this.gains = gains;
		this.losses = losses;
		this.movers = movers;
	}

	/**
	 * @param span days to cover, today included; 0 or less covers the whole day book
	 * @param limit lines kept in each list
	 */
	public static Report of(Ledger ledger, int span, LocalDate today, int limit)
	{
		LocalDate from = span <= 0 ? null : today.minusDays(span - 1);
		long play = 0;
		long market = 0;
		int covered = 0;
		LocalDate first = null;
		Map<Integer, Flow> merged = new HashMap<>();
		long[] channels = new long[Channel.values().length];
		long playedMs = 0;
		long timedPlay = 0;
		long[] kindsBefore = null;
		long[] kindsNow = null;
		long[] kindsMoved = null;
		for (Day day : ledger.getDays())
		{
			LocalDate date = LocalDate.parse(day.getDate());
			if (from != null && date.isBefore(from))
			{
				kindsBefore = day.getKinds() != null ? day.getKinds() : kindsBefore;
				continue;
			}
			if (day.getKinds() != null)
			{
				kindsNow = day.getKinds();
			}
			kindsMoved = add(kindsMoved, day.getMoved());
			if (day.getPlayedMs() > 0)
			{
				playedMs += day.getPlayedMs();
				timedPlay += day.getPlay();
			}
			if (first == null)
			{
				first = date;
			}
			covered++;
			play += day.getPlay();
			market += day.getMarket();
			for (Channel c : Channel.values())
			{
				channels[c.ordinal()] += day.channel(c);
			}
			for (Map.Entry<Integer, Flow> e : day.getItems().entrySet())
			{
				merged.computeIfAbsent(e.getKey(), k -> new Flow()).add(e.getValue());
			}
		}
		Report report = build(first != null ? first : today, covered, ledger.getTotal(), play, market, merged, limit, channels);
		report.playedMs = playedMs;
		report.timedPlay = timedPlay;
		report.kindsNow = kindsNow;
		report.kindsBefore = kindsBefore;
		report.kindsMoved = kindsMoved;
		return report;
	}

	/** One page of the day book on its own, from the worth it opened on to the worth it closed on. */
	public static Report page(Day day, int limit)
	{
		long[] channels = new long[Channel.values().length];
		for (Channel c : Channel.values())
		{
			channels[c.ordinal()] = day.channel(c);
		}
		Report report = build(LocalDate.parse(day.getDate()), 1, day.getClose(), day.getPlay(), day.getMarket(), day.getItems(), limit, channels);
		report.playedMs = day.getPlayedMs();
		report.timedPlay = day.getPlayedMs() > 0 ? day.getPlay() : 0;
		report.kindsNow = day.getKinds();
		report.kindsMoved = day.getMoved();
		return report;
	}

	/** Below this much logged-in time an hourly figure is mostly noise and is not given. */
	public static final long MIN_TIMED_MS = 10 * 60_000L;

	/** Time logged in over the pages covered; pages written before it was kept add nothing. */
	public long getPlayedMs()
	{
		return playedMs;
	}

	/** Whether there is enough logged-in time for an hourly figure. */
	public boolean hasHourly()
	{
		return playedMs >= MIN_TIMED_MS;
	}

	/**
	 * Play an hour logged in: the gold made or spent by playing, over the pages that kept their time,
	 * so a page from before time was kept never dilutes it. Market moves are not play and stay out.
	 */
	public long perHour()
	{
		return hasHourly() ? Math.round(timedPlay * 3_600_000.0 / playedMs) : 0;
	}

	/** Worth by kind as the span ends, by {@link Kind} ordinal, or null when kinds were not kept. */
	public long[] getKinds()
	{
		return kindsNow == null ? null : kindsNow.clone();
	}

	/**
	 * How each kind's worth changed over the span, by {@link Kind} ordinal: from the last page before the
	 * span to the end. Null when there is no earlier page with kinds to measure from.
	 */
	public long[] kindChange()
	{
		if (kindsNow == null || kindsBefore == null)
		{
			return null;
		}
		long[] change = new long[kindsNow.length];
		for (int i = 0; i < change.length; i++)
		{
			change[i] = kindsNow[i] - kindsBefore[i];
		}
		return change;
	}

	/**
	 * What each kind gained or lost over the span from its items coming and going, by {@link Kind} ordinal,
	 * leaving price moves out: coins that turned into gear show here, a price rise does not. Null when no
	 * page in the span told kinds apart.
	 */
	public long[] kindFlow()
	{
		return kindsMoved == null ? null : kindsMoved.clone();
	}

	private static long[] add(long[] sum, long[] more)
	{
		if (more == null)
		{
			return sum;
		}
		long[] next = sum == null ? new long[more.length] : sum;
		for (int i = 0; i < more.length; i++)
		{
			next[i] += more[i];
		}
		return next;
	}

	private static Report build(LocalDate from, int covered, long end, long play, long market, Map<Integer, Flow> merged, int limit,
		long[] channels)
	{
		List<Line> gains = new ArrayList<>();
		List<Line> losses = new ArrayList<>();
		List<Line> movers = new ArrayList<>();
		for (Map.Entry<Integer, Flow> e : merged.entrySet())
		{
			// What was bought and sold on the exchange is told on its own; these lists are the rest.
			Flow f = e.getValue();
			Line line = new Line(e.getKey(), f.getOwnQuantity(), f.getOwnValue(), f.getDrift());
			if (f.getOwnValue() > 0)
			{
				gains.add(line);
			}
			else if (f.getOwnValue() < 0)
			{
				losses.add(line);
			}
			if (f.getDrift() != 0)
			{
				movers.add(line);
			}
		}
		gains.sort(Comparator.comparingLong(Line::getValue).reversed());
		losses.sort(Comparator.comparingLong(Line::getValue));
		movers.sort(Comparator.comparingLong((Line l) -> Math.abs(l.getDrift())).reversed());
		return new Report(from, covered, end - play - market, end, play, market,
			head(gains, limit), head(losses, limit), head(movers, limit), channels);
	}

	/** Every item held, most valuable first. */
	public static List<Line> holdings(Ledger ledger, int limit)
	{
		List<Line> lines = new ArrayList<>();
		for (Map.Entry<Integer, Long> e : ledger.holdings().entrySet())
		{
			long value = e.getValue() * ledger.price(e.getKey());
			if (value > 0)
			{
				lines.add(new Line(e.getKey(), e.getValue(), value, 0));
			}
		}
		lines.sort(Comparator.comparingLong(Line::getValue).reversed());
		return head(lines, limit);
	}

	private static List<Line> head(List<Line> list, int limit)
	{
		return Collections.unmodifiableList(new ArrayList<>(list.subList(0, Math.min(limit, list.size()))));
	}

	public LocalDate getFrom()
	{
		return from;
	}

	/** Pages of the day book the report covers. */
	public int getDays()
	{
		return days;
	}

	public long getStart()
	{
		return start;
	}

	public long getEnd()
	{
		return end;
	}

	public long change()
	{
		return end - start;
	}

	public long getPlay()
	{
		return play;
	}

	public long getMarket()
	{
		return market;
	}

	public List<Line> getGains()
	{
		return gains;
	}

	public List<Line> getLosses()
	{
		return losses;
	}

	/** Part of the play by where it came from; pages written before this was kept count as nothing. */
	public long channel(Channel channel)
	{
		return channels[channel.ordinal()];
	}

	/** Play the pages do not say where it came from, as on pages written before that was kept. */
	public long unexplained()
	{
		long sum = 0;
		for (long c : channels)
		{
			sum += c;
		}
		return play - sum;
	}

	public List<Line> getMovers()
	{
		return movers;
	}
}

package com.codex.ledger.core;

import java.util.Arrays;
