package com.codex.ledger.core;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The account's trading on the Grand Exchange over a stretch of days: what each item made after
 * tax, the tax paid, and what is still held from buys and what it would fetch if sold now.
 */
public final class Trades
{
	/** One item's trading over the stretch. */
	public static final class Item
	{
		private final int itemId;
		private final Deal deal;

		Item(int itemId, Deal deal)
		{
			this.itemId = itemId;
			this.deal = deal;
		}

		public int getItemId()
		{
			return itemId;
		}

		public Deal getDeal()
		{
			return deal;
		}
	}

	/** Items bought and still held, with what they cost and what they would fetch now after tax. */
	public static final class Open
	{
		private final int itemId;
		private final long quantity;
		private final long cost;
		private final long worth;

		Open(int itemId, long quantity, long cost, long worth)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.cost = cost;
			this.worth = worth;
		}

		public int getItemId()
		{
			return itemId;
		}

		public long getQuantity()
		{
			return quantity;
		}

		public long getCost()
		{
			return cost;
		}

		/** What they would fetch at today's price, after tax. */
		public long getWorth()
		{
			return worth;
		}

		public long gain()
		{
			return worth - cost;
		}
	}

	private final Deal total;
	private final List<Item> items;
	private final List<Open> open;
	private final LocalDate from;

	private Trades(Deal total, List<Item> items, List<Open> open, LocalDate from)
	{
		this.total = total;
		this.items = items;
		this.open = open;
		this.from = from;
	}

	/**
	 * @param span days to cover, today included; 0 or less covers everything traded since the
	 *             ledger began watching trades
	 */
	public static Trades of(Ledger ledger, int span, LocalDate today)
	{
		Deal total = new Deal();
		Map<Integer, Deal> byItem = new HashMap<>();
		LocalDate first = null;
		if (span <= 0)
		{
			for (Map.Entry<Integer, Position> e : ledger.getBook().entrySet())
			{
				Deal life = e.getValue().life();
				if (life.volume() > 0)
				{
					byItem.computeIfAbsent(e.getKey(), k -> new Deal()).add(life);
					total.add(life);
				}
			}
		}
		else
		{
			LocalDate start = today.minusDays(span - 1);
			for (Day day : ledger.getDays())
			{
				LocalDate date = LocalDate.parse(day.getDate());
				if (date.isBefore(start))
				{
					continue;
				}
				first = first == null ? date : first;
				total.add(day.getTrades());
				for (Map.Entry<Integer, Deal> e : day.getDeals().entrySet())
				{
					byItem.computeIfAbsent(e.getKey(), k -> new Deal()).add(e.getValue());
				}
			}
		}
		List<Item> items = new ArrayList<>();
		for (Map.Entry<Integer, Deal> e : byItem.entrySet())
		{
			items.add(new Item(e.getKey(), e.getValue()));
		}
		// The biggest winners first, the biggest losers last; items only bought sit between, by what was spent.
		items.sort(Comparator.comparingLong((Item i) -> i.deal.getProfit()).reversed()
			.thenComparing(Comparator.comparingLong((Item i) -> i.deal.volume()).reversed()));

		List<Open> open = new ArrayList<>();
		Map<Integer, Long> held = ledger.holdings();
		for (Map.Entry<Integer, Position> e : ledger.getBook().entrySet())
		{
			Position p = e.getValue();
			long quantity = Math.min(p.getHeld(), held.getOrDefault(e.getKey(), 0L));
			long price = ledger.price(e.getKey());
			if (quantity <= 0 || price <= 0)
			{
				continue;
			}
			long cost = Position.share(p.getCost(), quantity, p.getHeld());
			long worth = quantity * price - Offer.tax(e.getKey(), quantity, quantity * price);
			open.add(new Open(e.getKey(), quantity, cost, worth));
		}
		open.sort(Comparator.comparingLong((Open o) -> Math.abs(o.gain())).reversed());
		return new Trades(total, Collections.unmodifiableList(items), Collections.unmodifiableList(open), first);
	}

	/** Every item traded together. */
	public Deal getTotal()
	{
		return total;
	}

	/** Each item traded, the biggest winner first. */
	public List<Item> getItems()
	{
		return items;
	}

	/** Items bought and still held, the biggest gain or loss if sold now first. */
	public List<Open> getOpen()
	{
		return open;
	}

	/** The first day book page the stretch covers, or null for everything since trades were watched. */
	public LocalDate getFrom()
	{
		return from;
	}

	/** What everything still held from buys would make or lose if sold now, after tax. */
	public long openGain()
	{
		long sum = 0;
		for (Open o : open)
		{
			sum += o.gain();
		}
		return sum;
	}
}

package com.codex.ledger.overlay;

import com.codex.ledger.ui.Format;
import com.codex.ledger.ui.Sigil;
import com.codex.ledger.ui.Theme;
import com.codex.ledger.ui.Ui;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/** A slim gilt plaque in the game view with the account's worth and today's change. It draws what the plugin hands it. */
public class WorthPlaque extends Overlay
{
	private static final int PAD = 7;

	private volatile long[] view;
	private volatile boolean enabled;

	public WorthPlaque()
	{
		setPosition(OverlayPosition.TOP_LEFT);
	}

	/** @param worth the worth, or null to hide the plaque */
	public void show(Long worth, long today)
	{
		view = worth == null ? null : new long[]{worth, today};
	}

	public void setEnabled(boolean enabled)
	{
		this.enabled = enabled;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		long[] v = view;
		if (!enabled || v == null)
		{
			return null;
		}
		Theme.smooth(g);
		String worth = Format.coins(v[0]);
		String today = Format.signed(v[1]) + " today";

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		int icon = 14;
		int width = PAD + icon + 6 + bold.stringWidth(worth) + 10 + small.stringWidth(today) + PAD;
		int height = Math.max(icon, bold.getHeight()) + PAD;

		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, width - 1, height - 1, 10, 10);
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.CARD_TOP, 230), 0, height, Theme.alpha(Theme.INK_DEEP, 230)));
		g.fill(shape);
		g.setColor(Theme.alpha(Theme.GOLD, 170));
		g.draw(shape);

		int x = PAD;
		Sigil.paint(g, x, (height - icon) / 2f, icon);
		x += icon + 6;
		int base = (height + bold.getAscent()) / 2 - 2;
		g.setFont(Theme.title());
		Ui.shadowed(g, worth, x, base, Theme.GOLD_BRIGHT);
		x += bold.stringWidth(worth) + 10;
		g.setFont(Theme.small());
		Ui.shadowed(g, today, x, base, Theme.signed(v[1]));
		return new Dimension(width, height);
	}
}

package com.codex.ledger.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.codex.ledger.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.ledger.ui;

import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import java.util.function.Function;
import javax.swing.SwingUtilities;
import javax.swing.Timer;

/**
 * Item pictures for one card, held until the card is drawn with all of them in.
 *
 * <p>A card is drawn once, when its button is pressed, so a picture still loading would be saved as
 * an empty well. The card is drawn a first time to learn which pictures it needs; if any has not
 * arrived, it is drawn again as soon as the last one does (or after a short wait, so a picture that
 * never comes cannot hold the card back). The second drawing is handed the very same pictures, so
 * one evicted from RuneLite's small picture cache in between cannot come back blank.
 */
public final class CardPictures implements ItemIcons
{
	/** The longest a card waits for its pictures before it is drawn with what has come. */
	static final int WAIT_MS = 2_500;

	private final ItemIcons source;
	private final Map<Integer, BufferedImage> taken = new HashMap<>();
	private final Set<Integer> waiting = new HashSet<>();
	private final Set<Integer> arrived = new HashSet<>();
	private Runnable whenAllArrived;

	CardPictures(ItemIcons source)
	{
		this.source = source;
	}

	@Override
	public BufferedImage icon(int itemId, Runnable ignored)
	{
		synchronized (this)
		{
			if (taken.containsKey(itemId))
			{
				return taken.get(itemId);
			}
		}
		BufferedImage image = source.icon(itemId, () -> arrived(itemId));
		synchronized (this)
		{
			taken.put(itemId, image);
			if (image != null && !source.hasArrived(image) && !arrived.contains(itemId))
			{
				waiting.add(itemId);
			}
		}
		return image;
	}

	@Override
	public boolean hasArrived(BufferedImage image)
	{
		return source.hasArrived(image);
	}

	private void arrived(int itemId)
	{
		Runnable done = null;
		synchronized (this)
		{
			arrived.add(itemId);
			if (waiting.remove(itemId) && waiting.isEmpty())
			{
				done = whenAllArrived;
			}
		}
		if (done != null)
		{
			done.run();
		}
	}

	/** True when no picture the card asked for is still on its way. */
	synchronized boolean allArrived()
	{
		return waiting.isEmpty();
	}

	/** Runs once the last picture still on its way arrives; at once if none is. */
	void whenAllArrived(Runnable run)
	{
		boolean now;
		synchronized (this)
		{
			whenAllArrived = run;
			now = waiting.isEmpty();
		}
		if (now)
		{
			run.run();
		}
	}

	/**
	 * Draws a card with all its pictures in and hands it over on the Swing thread, as Save and Copy need.
	 *
	 * @param icons where pictures come from, or null to draw without them
	 * @param render draws the card with the pictures given
	 * @param deliver takes the finished card
	 */
	public static void draw(ItemIcons icons, Function<ItemIcons, BufferedImage> render, Consumer<BufferedImage> deliver)
	{
		// A second press while the first card still waits for its pictures is let go, so one press
		// never becomes two save dialogs.
		if (!BUSY.compareAndSet(false, true))
		{
			return;
		}
		int generation = GENERATION.get();
		Timer[] wait = new Timer[1];
		draw(icons, pictures -> GENERATION.get() == generation ? render.apply(pictures) : null, card ->
		{
			// A card still waiting when the plugin stopped is dropped, not saved by a plugin that is gone.
			if (GENERATION.get() == generation)
			{
				deliver.accept(card);
			}
		}, SwingUtilities::invokeLater, run ->
		{
			Timer timer = new Timer(WAIT_MS, e -> run.run());
			timer.setRepeats(false);
			wait[0] = timer;
			waitTimer = timer;
			timer.start();
		}, () ->
		{
			// The wait is over either way; a card drawn early lets go of its timer.
			if (wait[0] != null)
			{
				wait[0].stop();
			}
			if (waitTimer == wait[0])
			{
				waitTimer = null;
			}
			if (GENERATION.get() == generation)
			{
				BUSY.set(false);
			}
		});
	}

	/**
	 * Lets go of a card still waiting for its pictures, for the plugin's shutdown: it is never handed
	 * over, and the next card (after a restart) is not held back by it.
	 */
	public static void cancel()
	{
		GENERATION.incrementAndGet();
		BUSY.set(false);
		Runnable stop = () ->
		{
			if (waitTimer != null)
			{
				waitTimer.stop();
				waitTimer = null;
			}
		};
		// Plugins stop on the Swing thread; there it is done before any new card can begin.
		if (SwingUtilities.isEventDispatchThread())
		{
			stop.run();
		}
		else
		{
			SwingUtilities.invokeLater(stop);
		}
	}

	/** True while a card waits for its pictures. */
	private static final AtomicBoolean BUSY = new AtomicBoolean();
	/** Moved on by {@link #cancel}, so a card begun before it is dropped. */
	private static final AtomicInteger GENERATION = new AtomicInteger();
	/** The wait of the card waiting now; used on the Swing thread only. */
	private static Timer waitTimer;

	/**
	 * As {@link #draw(ItemIcons, Function, Consumer)}, with how to get back on the Swing thread and how
	 * to wait, for tests.
	 *
	 * @param after runs once the card has been handed over, or failed to draw
	 */
	static void draw(ItemIcons icons, Function<ItemIcons, BufferedImage> render, Consumer<BufferedImage> deliver,
		Consumer<Runnable> onSwing, Consumer<Runnable> afterWait, Runnable after)
	{
		boolean waiting = false;
		try
		{
			if (icons == null)
			{
				deliver.accept(render.apply(null));
				return;
			}
			CardPictures pictures = new CardPictures(icons);
			BufferedImage first = render.apply(pictures);
			if (pictures.allArrived())
			{
				deliver.accept(first);
				return;
			}
			AtomicBoolean done = new AtomicBoolean();
			Runnable finish = () -> onSwing.accept(() ->
			{
				if (done.compareAndSet(false, true))
				{
					try
					{
						deliver.accept(render.apply(pictures));
					}
					finally
					{
						after.run();
					}
				}
			});
			pictures.whenAllArrived(finish);
			afterWait.accept(finish);
			waiting = true;
		}
		finally
		{
			if (!waiting)
			{
				after.run();
			}
		}
	}
}

package com.codex.ledger.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JComponent;

/**
 * Where the gold came from and went, one row a channel: its name, a bar growing right for gold
 * gained and left for gold lost from a gilt centre line, all on one scale, and the amount.
 */
class ChannelRows extends JComponent
{
	private static final int ROW = 18;
	private static final int LABEL = 58;
	private static final int VALUE = 44;

	/** One row: a channel's name, its amount and the colours it is drawn in either way. */
	static final class Row
	{
		final String label;
		final long value;
		final Color up;
		final Color down;

		Row(String label, long value, Color up, Color down)
		{
			this.label = label;
			this.value = value;
			this.up = up;
			this.down = down;
		}
	}

	private final List<Row> rows;

	ChannelRows(List<Row> rows, String tip)
	{
		this.rows = new ArrayList<>(rows);
		setOpaque(false);
		setPreferredSize(new Dimension(10, ROW * Math.max(1, rows.size())));
		setToolTipText(tip);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		long scale = 1;
		for (Row r : rows)
		{
			scale = Math.max(scale, Math.abs(r.value));
		}
		for (int i = 0; i < rows.size(); i++)
		{
			row(g, i * ROW, rows.get(i), scale);
		}
		g.dispose();
	}

	private void row(Graphics2D g, int y, Row r, long scale)
	{
		int w = getWidth();
		Color color = r.value >= 0 ? r.up : r.down;
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		int mid = y + ROW / 2;
		int base = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(Ui.clip(r.label, fm, LABEL - 4), 0, base);
		String text = Format.signedCompact(r.value);
		Ui.shadowed(g, text, w - fm.stringWidth(text), base, r.value == 0 ? Theme.TEXT_FAINT : Theme.mix(color, Theme.TEXT, 0.2));

		int left = LABEL;
		int right = w - VALUE;
		int centre = (left + right) / 2;
		int half = (right - left) / 2;
		g.setColor(Theme.INK_DEEP);
		g.fill(new RoundRectangle2D.Float(left, mid - 2.5f, right - left, 5, 5, 5));
		if (r.value != 0)
		{
			float len = Math.max(2, (float) (half * Math.min(1, Math.abs(r.value) / (double) scale)));
			float x = r.value > 0 ? centre : centre - len;
			g.setPaint(new GradientPaint(centre, 0, Theme.mix(color, Theme.INK, 0.35), r.value > 0 ? centre + half : centre - half, 0, color));
			g.fill(new RoundRectangle2D.Float(x, mid - 2.5f, len, 5, 5, 5));
		}
		g.setColor(Theme.GOLD);
		g.fillRect(centre, mid - 4, 1, 8);
	}
}

package com.codex.ledger.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A gilt-edged button; the primary style is filled, the quiet style is just an outline. */
public class CodexButton extends JComponent
{
	private final String text;
	private final boolean primary;
	private boolean hover;
	private boolean pressed;

	public CodexButton(String text, boolean primary, Runnable action)
	{
		this.text = text;
		this.primary = primary;
		setFont(Theme.small());
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 20, 22);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				pressed = false;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed = true;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				boolean fire = pressed && contains(e.getPoint());
				pressed = false;
				repaint();
				if (fire)
				{
					action.run();
				}
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int dy = pressed ? 1 : 0;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f + dy, w - 1, h - 2, 8, 8);
		Color text;
		if (primary)
		{
			Color top = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
			g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.GOLD_DIM));
			g.fill(shape);
			text = Theme.INK_DEEP;
		}
		else
		{
			g.setColor(hover ? Theme.alpha(Theme.GOLD, 40) : Theme.alpha(Theme.GOLD, 14));
			g.fill(shape);
			text = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
		}
		g.setColor(Theme.alpha(Theme.GOLD, primary ? 220 : 140));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(text);
		g.drawString(this.text, (w - fm.stringWidth(this.text)) / 2, (h + fm.getAscent()) / 2 - 2 + dy);
		g.dispose();
	}
}

package com.codex.ledger.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/**
 * The crest at the top of the panel: the Ledger's medallion, the account's worth in large gilt
 * figures, and what it did today, this week and this month.
 */
public class Crest extends JComponent
{
	private static final int HEIGHT = 104;

	private final Animator count = new Animator(this);
	private String player;
	private String status = "Log in to open the ledger";
	private long total;
	private boolean known;
	private final long[] changes = new long[3];
	private final boolean[] hasChange = new boolean[3];
	private static final String[] PERIODS = {"Today", "Week", "Month"};

	// The large figure is drawn small then doubled; while the count runs this would be a new image
	// every frame, so the last one is kept and reused until its text changes.
	private String largeText;
	private BufferedImage largeImage;
	private int largeAscent;

	public Crest()
	{
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setMinimumSize(new Dimension(10, HEIGHT));
	}

	/**
	 * @param status a line in place of the changes, or null to show them
	 * @param changes today, the week and the month; null for any not yet known
	 */
	public void update(String player, Long total, String status, Long[] changes)
	{
		this.player = player;
		this.status = status;
		this.known = total != null;
		if (total != null)
		{
			boolean animate = this.total != 0 && Math.abs(total - this.total) < Math.max(1, this.total);
			this.total = total;
			count.set(total, animate);
		}
		else
		{
			// The next figure shown, perhaps another account's, appears at once rather than counting from this one.
			this.total = 0;
		}
		for (int i = 0; i < 3; i++)
		{
			hasChange[i] = changes != null && changes[i] != null;
			this.changes[i] = hasChange[i] ? changes[i] : 0;
		}
		repaint();
	}

	/**
	 * Draws text at twice the size of the game's bold font by doubling every pixel, the way the
	 * game itself draws large numbers, so the figures stay crisp instead of being re-rasterised.
	 *
	 * @return the width drawn
	 */
	private int paintLarge(Graphics2D g, String text, int x, int y)
	{
		if (!text.equals(largeText) || largeImage == null)
		{
			Font font = Theme.title();
			FontMetrics fm = g.getFontMetrics(font);
			largeImage = renderSmall(text, font, fm);
			largeAscent = fm.getAscent();
			largeText = text;
		}
		int w = largeImage.getWidth();
		int h = largeImage.getHeight();
		Graphics2D lg = (Graphics2D) g.create();
		lg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		lg.drawImage(largeImage, x, y - 2 * largeAscent + 22, w * 2, h * 2, null);
		lg.dispose();
		return w * 2;
	}

	private static BufferedImage renderSmall(String text, Font font, FontMetrics fm)
	{
		int w = Math.max(1, fm.stringWidth(text) + 1);
		int h = fm.getHeight() + 1;
		BufferedImage small = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D sg = small.createGraphics();
		sg.setFont(font);
		sg.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		int base = fm.getAscent();
		sg.setColor(Color.BLACK);
		sg.drawString(text, 1, base + 1);
		sg.setPaint(new GradientPaint(0, base - fm.getAscent() + 3, Theme.GOLD_BRIGHT, 0, base, Theme.GOLD));
		sg.drawString(text, 0, base);
		sg.dispose();
		return small;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.GOLD_DIM, 0.22), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);

		// The medallion: a gilt ring with the mark inside, lit from above.
		int mx = 10;
		int my = 14;
		int md = 54;
		g.setPaint(new RadialGradientPaint(mx + md / 2f, my + md / 3f, md * 0.7f, new float[]{0, 1},
			new Color[]{Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35), Theme.INK_DEEP}));
		g.fill(new Ellipse2D.Float(mx, my, md, md));
		g.setStroke(new BasicStroke(2f));
		g.setPaint(new GradientPaint(mx, my, Theme.GOLD_BRIGHT, mx, my + md, Theme.GOLD_DIM));
		g.draw(new Ellipse2D.Float(mx + 1, my + 1, md - 2, md - 2));
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD, 70));
		g.draw(new Ellipse2D.Float(mx + 5, my + 5, md - 10, md - 10));
		Sigil.paint(g, mx + 11, my + 11, md - 22);

		int tx = mx + md + 12;
		int room = w - tx - 8;
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		String heading = (player != null ? player + "  \u00b7  " : "") + "NET WORTH";
		if (player != null && small.stringWidth(heading) > room)
		{
			// A long name keeps its room rather than ending in a clipped "NET W...".
			heading = player;
		}
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(Ui.clip(heading, small, room), tx, 22);

		String figure = known ? Format.coins(Math.round(count.get())) : "-";
		int top = 27;
		int figureW = paintLarge(g, figure, tx, top);
		if (known)
		{
			g.setFont(Theme.small());
			g.setColor(Theme.GOLD_DIM);
			g.drawString("gp", tx + figureW + 3, top + 18);
		}
		int fy = top + 26;
		int cy = fy + 24;
		g.setFont(Theme.small());
		if (status != null)
		{
			g.setColor(Theme.mix(Theme.TEXT_MUTED, Theme.GOLD, 0.3));
			g.drawString(Ui.clip(status, small, room), tx, cy);
		}
		else
		{
			int cw = room / 3;
			for (int i = 0; i < 3; i++)
			{
				int x = tx + i * cw;
				g.setColor(Theme.TEXT_FAINT);
				g.drawString(PERIODS[i], x, cy - 11);
				String value = hasChange[i] ? Format.signedCompact(changes[i]) : "-";
				Ui.shadowed(g, Ui.clip(value, small, cw - 4), x, cy + 1, hasChange[i] ? Theme.signed(changes[i]) : Theme.TEXT_FAINT);
			}
		}

		// The gilt rule under the crest, with a diamond at its middle.
		int y = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
	}
}

package com.codex.ledger.ui;

import com.codex.ledger.core.Day;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.time.LocalDate;
import javax.swing.JComponent;

/**
 * One page of the day book in the list: the date and the worth it closed on, the change, and a
 * slim two-part bar for how much of it was play and how much was market.
 */
class DayRow extends JComponent
{
	private final Day day;
	private final long scale;
	private final boolean selected;
	private boolean hover;

	DayRow(Day day, long scale, boolean selected, Runnable onClick)
	{
		this.day = day;
		this.scale = Math.max(1, scale);
		this.selected = selected;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 40));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		setToolTipText("Play " + Format.signed(day.getPlay()) + ", market " + Format.signed(day.getMarket())
			+ ". High " + Format.coins(day.getHigh()) + ", low " + Format.coins(day.getLow()) + ".");
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (contains(e.getPoint()))
				{
					onClick.run();
				}
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, hover ? Theme.CARD_HOVER : Theme.CARD_TOP, 0, h, Theme.CARD));
		g.fill(shape);
		long change = day.change();
		g.setClip(shape);
		g.setColor(Theme.signed(change));
		g.fillRect(0, 0, 3, h);
		g.setClip(null);
		g.setColor(selected ? Theme.alpha(Theme.GOLD, 160) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT);
		g.draw(shape);

		g.setFont(Theme.body());
		FontMetrics fm = g.getFontMetrics();
		String date = Format.day(LocalDate.parse(day.getDate()));
		Ui.shadowed(g, date, 10, 4 + fm.getAscent(), selected ? Theme.GOLD_BRIGHT : Theme.TEXT);
		String text = Format.signed(change);
		Ui.shadowed(g, text, w - 9 - fm.stringWidth(text), 4 + fm.getAscent(), Theme.signed(change));

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_FAINT);
		g.drawString("closed " + Format.coins(day.getClose()), 10, h - 13);
		if (day.getPlayedMs() >= 60_000)
		{
			// Time logged in sits after the date, when it fits before the change.
			String played = Format.duration(day.getPlayedMs());
			int px = 10 + fm.stringWidth(date) + 6;
			if (px + small.stringWidth(played) < w - 9 - fm.stringWidth(text) - 6)
			{
				g.drawString(played, px, 4 + fm.getAscent());
			}
		}

		// Play and market side by side, scaled against the busiest day in the list.
		int bx = w - 9 - 70;
		int by = h - 17;
		int bw = 70;
		g.setColor(Theme.INK_DEEP);
		g.fill(new RoundRectangle2D.Float(bx, by, bw, 4, 4, 4));
		g.fill(new RoundRectangle2D.Float(bx, by + 6, bw, 4, 4, 4));
		bar(g, bx, by, bw, day.getPlay(), day.getPlay() >= 0 ? Theme.GAIN : Theme.LOSS);
		bar(g, bx, by + 6, bw, day.getMarket(), day.getMarket() >= 0 ? Theme.MARKET : Theme.EMBER);
		g.dispose();
	}

	private void bar(Graphics2D g, int x, int y, int w, long value, java.awt.Color color)
	{
		if (value == 0)
		{
			return;
		}
		float len = Math.max(2, w * (float) Math.min(1, Math.abs(value) / (double) scale));
		g.setColor(color);
		g.fill(new RoundRectangle2D.Float(x, y, len, 4, 4, 4));
	}
}

package com.codex.ledger.ui;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

/** Coins, changes, durations and dates in the short forms the panel uses. */
public final class Format
{
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEE d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("EEEE d MMMM yyyy", Locale.ENGLISH);
	private static final DateTimeFormatter SHORT = DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter LONG_DAY = DateTimeFormatter.ofPattern("EEE d MMM yyyy", Locale.ENGLISH);
	private static final DateTimeFormatter MONTH = DateTimeFormatter.ofPattern("MMM yy", Locale.ENGLISH);

	private Format()
	{
	}

	/**
	 * Coins at one precision per unit, the same across the Codex plugins, so figures side by side read
	 * alike: "8,240", "41k", "412k", "4.9M", "26.0M", "835.5M", "1.50B". Thousands are whole, millions
	 * keep one decimal and billions two, zero or not ("26.0M", never "26M").
	 */
	public static String amount(long n)
	{
		if (n < 10_000)
		{
			return String.format(Locale.ENGLISH, "%,d", n);
		}
		// A figure that rounds up to a thousand of one unit is written in the next ("1.0M", not "1000k").
		if (n < 999_500)
		{
			return Math.round(n / 1_000.0) + "k";
		}
		if (n < 999_950_000)
		{
			return fixed(n / 1_000_000.0, 1) + "M";
		}
		return fixed(n / 1_000_000_000.0, 2) + "B";
	}

	/**
	 * A round figure, a milestone or a target, by its name: "1M", "750M", "1B", "1.5B". Only these
	 * drop the zeros after the point; any other figure is written by {@link #amount}.
	 */
	public static String mark(long n)
	{
		if (n < 10_000)
		{
			return String.format(Locale.ENGLISH, "%,d", n);
		}
		if (n < 999_500)
		{
			return Math.round(n / 1_000.0) + "k";
		}
		if (n < 999_995_000)
		{
			return trim(n / 1_000_000.0, 2) + "M";
		}
		return trim(n / 1_000_000_000.0, 2) + "B";
	}

	/**
	 * For tight columns; the same as {@link #amount}, which is never wider than "999.9M", so a column
	 * reads with the same places as the rest of the panel ("+4.9M", not "+4.90M" beside it).
	 */
	public static String compact(long n)
	{
		return amount(n);
	}

	/** A change with its sign, for tight columns: "+628.1M". */
	public static String signedCompact(long gp)
	{
		return gp > 0 ? "+" + compact(gp) : gp < 0 ? "-" + compact(-gp) : "0";
	}

	/** Coins in the short form, negative amounts with a minus: "812.4M", "-45.2k". */
	public static String coins(long gp)
	{
		return gp < 0 ? "-" + amount(-gp) : amount(gp);
	}

	/** A change with its sign: "+3.2M", "-412k", "0". */
	public static String signed(long gp)
	{
		return gp > 0 ? "+" + amount(gp) : gp < 0 ? "-" + amount(-gp) : "0";
	}

	/** A whole number written in full with thousands commas, whatever the computer's language: "1,240". */
	public static String whole(long n)
	{
		return String.format(Locale.ENGLISH, "%,d", n);
	}

	/** Hours to one decimal place, with a full stop whatever the computer's language: "1.5 hours". */
	public static String hours(double hours)
	{
		return String.format(Locale.ENGLISH, "%.1f", hours) + " hours";
	}

	/** A quantity change with its sign, written in full: "+1,240", "-6". */
	public static String count(long n)
	{
		return (n > 0 ? "+" : n < 0 ? "-" : "") + String.format(Locale.ENGLISH, "%,d", Math.abs(n));
	}

	/** A share as a whole percent, "<1%" for a sliver, and ">99%" when nearly all but not quite. */
	public static String percent(double share)
	{
		if (share > 0 && share < 0.01)
		{
			return "<1%";
		}
		if (share >= 0.995 && share < 1)
		{
			// Rounded it reads 100%, which says "all of it" when some is still missing.
			return ">99%";
		}
		return Math.round(share * 100) + "%";
	}

	/**
	 * Each value's share of a whole as whole percents that add up as the values do: to 100% when the
	 * values make the whole, never past it. Rounding each share on its own can give 101%; here the
	 * points left over go to the shares that lost the most in rounding down. A share too small for a
	 * point of its own reads "<1%", and a share beside one reads ">99%" rather than 100%, since the
	 * two together cannot be more than all of it.
	 *
	 * @param whole what the shares are of; when the values add up to more, their sum is used instead
	 */
	public static String[] shares(long[] values, long whole)
	{
		int[] points = sharePoints(values, whole);
		long sum = 0;
		for (long v : values)
		{
			sum += Math.max(0, v);
		}
		long all = Math.max(whole, sum);
		String[] out = new String[values.length];
		for (int i = 0; i < values.length; i++)
		{
			// A share rounded up to 100% that is short of the whole (a sliver beside it, or the rest not
			// listed) reads ">99%": only all of it is 100%.
			out[i] = points[i] == 0 && values[i] > 0 ? "<1%" : points[i] >= 100 && values[i] < all ? ">99%" : points[i] + "%";
		}
		return out;
	}

	/** The whole percents {@link #shares} writes, as numbers. */
	public static int[] sharePoints(long[] values, long whole)
	{
		long sum = 0;
		for (long v : values)
		{
			sum += Math.max(0, v);
		}
		double denom = Math.max(whole, sum);
		int[] points = new int[values.length];
		if (denom <= 0)
		{
			return points;
		}
		double[] lost = new double[values.length];
		int given = 0;
		for (int i = 0; i < values.length; i++)
		{
			double exact = Math.max(0, values[i]) * 100 / denom;
			points[i] = (int) Math.floor(exact);
			lost[i] = exact - points[i];
			given += points[i];
		}
		int target = (int) Math.round(sum * 100 / denom);
		while (given < target)
		{
			int best = -1;
			for (int i = 0; i < values.length; i++)
			{
				if (values[i] > 0 && (best < 0 || lost[i] > lost[best]))
				{
					best = i;
				}
			}
			if (best < 0)
			{
				break;
			}
			points[best]++;
			lost[best] = -1;
			given++;
		}
		return points;
	}

	/** A return as a signed percent: "+26%", "-3.4%", "+0.8%". */
	public static String signedPercent(double share)
	{
		double pct = share * 100;
		String text = Math.abs(pct) < 10 ? trim(Math.abs(pct), 1) : String.valueOf(Math.round(Math.abs(pct)));
		return (pct < 0 ? "-" : "+") + text + "%";
	}

	/** "1 item", "1,240 items". */
	public static String plural(long n, String word)
	{
		return String.format(Locale.ENGLISH, "%,d", n) + " " + word + (n == 1 ? "" : "s");
	}

	/** "Sat 14 Feb 2027", for a day further off than the panel's own dates. */
	public static String longDay(java.time.LocalDate date)
	{
		return LONG_DAY.format(date);
	}

	/** How long between two milestones: "the same day", "5 hours", "16 days", "3 months". */
	public static String gap(long ms)
	{
		long hours = Math.max(0, ms) / 3_600_000L;
		if (hours < 1)
		{
			return "under an hour";
		}
		if (hours < 24)
		{
			return plural(hours, "hour");
		}
		long days = hours / 24;
		if (days < 90)
		{
			return plural(days, "day");
		}
		return plural(days / 30, "month");
	}

	/** "just now", "12m ago", "3h ago", "2d ago". */
	public static String ago(long ms)
	{
		long minutes = Math.max(0, ms) / 60_000;
		if (minutes < 1)
		{
			return "just now";
		}
		if (minutes < 60)
		{
			return minutes + "m ago";
		}
		if (minutes < 48 * 60)
		{
			return minutes / 60 + "h ago";
		}
		return minutes / (24 * 60) + "d ago";
	}

	/** A figure to exactly that many places, with a full stop whatever the computer's language. */
	private static String fixed(double value, int places)
	{
		return String.format(Locale.ENGLISH, "%." + places + "f", value);
	}

	private static String trim(double value, int places)
	{
		String text = String.format(Locale.ENGLISH, "%." + places + "f", value);
		while (text.contains(".") && (text.endsWith("0") || text.endsWith(".")))
		{
			text = text.substring(0, text.length() - 1);
		}
		return text;
	}

	/** "2h 14m", "38m", "under a minute". */
	public static String duration(long ms)
	{
		long minutes = ms / 60_000;
		if (minutes < 1)
		{
			return "under a minute";
		}
		if (minutes < 60)
		{
			return minutes + "m";
		}
		return minutes / 60 + "h " + minutes % 60 + "m";
	}

	/** "14:02" in the player's own time. */
	public static String time(long epochMs)
	{
		return CLOCK.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "Thu 16 Oct". */
	public static String day(long epochMs)
	{
		return DAY.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "16 Oct". */
	public static String shortDay(long epochMs)
	{
		return SHORT.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "Oct 26". */
	public static String month(long epochMs)
	{
		return MONTH.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "Thu 16 Oct" for a day book date. */
	public static String day(java.time.LocalDate date)
	{
		return DAY.format(date);
	}

	/** "Thursday 16 October 2026". */
	public static String date(long epochMs)
	{
		return DATE.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** An item stack, shortened where the game shortens it, with the suite's lowercase k: "950", "45k", "12M". */
	public static String stack(long n)
	{
		if (n < 100_000)
		{
			return String.valueOf(n);
		}
		if (n < 10_000_000)
		{
			return n / 1_000 + "k";
		}
		return n / 1_000_000 + "M";
	}

	/** The colour the game writes a stack of that size in. */
	public static java.awt.Color stackColor(long n)
	{
		return n < 100_000 ? Theme.QTY_YELLOW : n < 10_000_000 ? Theme.QTY_WHITE : Theme.QTY_GREEN;
	}
}

