/** A gilt progress bar in an ink groove, with a notch every quarter of the way. */
class GoalBar extends JComponent
{
	private static final int H = 8;
	private final double progress;

	GoalBar(double progress)
	{
		this.progress = Math.max(0, Math.min(1, progress));
		setOpaque(false);
		setPreferredSize(new Dimension(10, H + 2));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		RoundRectangle2D groove = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, H, H, H);
		g.setColor(Theme.INK_DEEP);
		g.fill(groove);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(groove);
		if (progress > 0)
		{
			float fill = (float) Math.max(H, (w - 3) * progress);
			g.setPaint(new GradientPaint(0, 0, Theme.GOLD_DIM, w, 0, progress >= 1 ? Theme.GREEN : Theme.GOLD_BRIGHT));
			g.fill(new RoundRectangle2D.Float(1.5f, 1.5f, fill, H - 2, H - 2, H - 2));
		}
		g.setColor(Theme.alpha(Theme.INK, 160));
		for (int i = 1; i < 4; i++)
		{
			g.fillRect(w * i / 4, 2, 1, H - 3);
		}
		g.dispose();
	}
}

package com.codex.ledger.ui;

import java.util.Collections;
import java.util.Set;
import java.util.WeakHashMap;
import java.util.function.Consumer;

/**
 * Hands a picture's "loaded" callback over only until the picture has arrived.
 *
 * <p>RuneLite runs a callback given after an item picture has loaded straight away (later, on the
 * client thread). A component that asks for its picture while painting and repaints when told it
 * loaded would then repaint forever. Once a picture is known to have arrived, no more callbacks
 * are passed on for it.
 */
public final class IconWatch
{
	private final Set<Object> arrived = Collections.synchronizedSet(Collections.newSetFromMap(new WeakHashMap<Object, Boolean>()));

	/**
	 * @param image the picture, compared by identity
	 * @param onLoaded run when it arrives; may be null
	 * @param register passes a callback to the picture, the way AsyncBufferedImage.onLoaded does
	 */
	public void watch(Object image, Runnable onLoaded, Consumer<Runnable> register)
	{
		if (image == null || arrived.contains(image))
		{
			return;
		}
		register.accept(() ->
		{
			arrived.add(image);
			if (onLoaded != null)
			{
				onLoaded.run();
			}
		});
	}

	/** True once the picture has said it arrived. */
	public boolean hasArrived(Object image)
	{
		return image != null && arrived.contains(image);
	}

	/** For tests: how many arrived pictures are remembered. */
	int size()
	{
		synchronized (arrived)
		{
			return arrived.size();
		}
	}
}

package com.codex.ledger.ui;

import java.awt.image.BufferedImage;

/** Where the panel gets item pictures; the plugin answers from RuneLite's item manager. */
public interface ItemIcons
{
	/**
	 * @param onLoaded run once if the picture arrives later than this call
	 * @return the picture, possibly still blank, or null
	 */
	BufferedImage icon(int itemId, Runnable onLoaded);

	/**
	 * True when a picture this gave out is known to have arrived; a card waits for one that has not.
	 * Pictures that are never late (previews, tests) have always arrived.
	 */
	default boolean hasArrived(BufferedImage image)
	{
		return true;
	}
}

