package com.codex.ledger.ui;

import java.awt.BasicStroke;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

/** The Ledger's mark: a stack of gilt coins with a teal line climbing past it to a bright point. */
public final class Sigil
{
	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the mark in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;
		float stroke = Math.max(0.6f, 0.55f * s);

		// Three coins, the top one face up.
		float cx = x + 6.2f * s;
		float rw = 5.4f * s;
		float rh = 2.1f * s;
		for (int i = 0; i < 3; i++)
		{
			float cy = y + (13.4f - i * 2.6f) * s;
			Path2D edge = new Path2D.Float();
			edge.append(new Ellipse2D.Float(cx - rw, cy - rh + 1.2f * s, rw * 2, rh * 2), false);
			g.setPaint(new GradientPaint(cx - rw, 0, Theme.GOLD_DIM, cx + rw, 0, Theme.mix(Theme.GOLD_DIM, Theme.INK_DEEP, 0.4)));
			g.fill(edge);
			Ellipse2D face = new Ellipse2D.Float(cx - rw, cy - rh, rw * 2, rh * 2);
			g.setPaint(new GradientPaint(cx - rw, cy - rh, Theme.GOLD_BRIGHT, cx + rw, cy + rh, Theme.GOLD));
			g.fill(face);
			g.setColor(Theme.INK_DEEP);
			g.setStroke(new BasicStroke(stroke));
			g.draw(face);
		}
		g.setColor(Theme.alpha(Theme.INK_DEEP, 150));
		g.draw(new Ellipse2D.Float(cx - rw * 0.55f, y + 8.2f * s - rh * 0.55f, rw * 1.1f, rh * 1.1f));

		// The line, rising from the left past the coins.
		Path2D line = new Path2D.Float();
		line.moveTo(x + 1.2f * s, y + 6.6f * s);
		line.lineTo(x + 5.2f * s, y + 4.4f * s);
		line.lineTo(x + 8.4f * s, y + 5.6f * s);
		line.lineTo(x + 13.6f * s, y + 1.8f * s);
		g.setStroke(new BasicStroke(Math.max(2.2f, 2.4f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.INK_DEEP);
		g.draw(line);
		g.setStroke(new BasicStroke(Math.max(1.1f, 1.3f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.TEAL);
		g.draw(line);

		// A bright point where it ends.
		float r = 1.7f * s;
		g.setColor(Theme.alpha(Theme.TEAL, 90));
		g.fill(new Ellipse2D.Float(x + 13.6f * s - r * 1.7f, y + 1.8f * s - r * 1.7f, r * 3.4f, r * 3.4f));
		g.setColor(Theme.mix(Theme.TEAL, Theme.TEXT, 0.5));
		g.fill(new Ellipse2D.Float(x + 13.6f * s - r, y + 1.8f * s - r, r * 2, r * 2));
	}
}

package com.codex.ledger.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/**
 * The change in worth taken apart: play (what was gained or spent) and market (what prices did),
 * each a bar growing right for gold gained and left for gold lost from a gilt centre line.
 */
class SplitRows extends JComponent
{
	private static final int ROW = 20;
	private static final int LABEL = 46;
	private static final int VALUE = 46;

	private final long play;
	private final long market;

	SplitRows(long play, long market)
	{
		this.play = play;
		this.market = market;
		setOpaque(false);
		setPreferredSize(new Dimension(10, ROW * 2));
		setToolTipText("Play is items gained or spent at the day's prices. Market is prices moving on what you held.");
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		long scale = Math.max(1, Math.max(Math.abs(play), Math.abs(market)));
		row(g, 0, "Play", play, scale, play >= 0 ? Theme.GAIN : Theme.LOSS);
		row(g, ROW, "Market", market, scale, market >= 0 ? Theme.MARKET : Theme.EMBER);
		g.dispose();
	}

	private void row(Graphics2D g, int y, String label, long value, long scale, Color color)
	{
		int w = getWidth();
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		int mid = y + ROW / 2;
		int base = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label, 0, base);
		String text = Format.signed(value);
		Ui.shadowed(g, text, w - fm.stringWidth(text), base, Theme.mix(color, Theme.TEXT, 0.2));

		int left = LABEL;
		int right = w - VALUE;
		int centre = (left + right) / 2;
		int half = (right - left) / 2;
		g.setColor(Theme.INK_DEEP);
		g.fill(new RoundRectangle2D.Float(left, mid - 3, right - left, 6, 6, 6));
		float len = (float) (half * Math.min(1, Math.abs(value) / (double) scale));
		if (value != 0)
		{
			len = Math.max(2, len);
			float x = value > 0 ? centre : centre - len;
			g.setPaint(new GradientPaint(centre, 0, Theme.mix(color, Theme.INK, 0.35), value > 0 ? centre + half : centre - half, 0, color));
			g.fill(new RoundRectangle2D.Float(x, mid - 3, len, 6, 6, 6));
		}
		g.setColor(Theme.GOLD);
		g.fillRect(centre, mid - 5, 1, 10);
	}
}

package com.codex.ledger.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

