	StatTile(String value, String label, String note, Color color)
	{
		this.value = value;
		this.label = label;
		this.note = note;
		this.color = color;
		setPreferredSize(new Dimension(10, 54));
		setOpaque(false);
		setToolTipText(note == null || note.isEmpty() ? label : label + ": " + note);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, value, label, note, color, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a tablet in a box; the card uses the same drawing. */
	static void paint(Graphics2D g, String value, String label, String note, Color color, int x, int y, int w, int h)
	{
		RoundRectangle2D shape = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(x, y, Theme.CARD_TOP, x, y + h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		g.setColor(Theme.alpha(color, 160));
		g.fillRect(x + Theme.RADIUS, y + 1, w - Theme.RADIUS * 2, 1);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label.toUpperCase(Locale.ROOT), x + 8, y + 6 + small.getAscent());

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(value, bold, w - 16), x + 8, y + 8 + small.getHeight() + bold.getAscent(), color);
		if (note != null && !note.isEmpty())
		{
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(note, small, w - 16), x + 8, y + h - 6);
		}
	}
}

package com.codex.ledger.ui;

import com.codex.ledger.core.Store;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import java.util.List;
import javax.swing.JComponent;

/** Where the worth is kept: one bar split by place, then a line for each with when it was last seen. */
class StoreBreakdown extends JComponent
{
	private static final int BAR = 10;
	private static final int ROW = 19;
	/** A place's age when it has never been seen. */
	static final long NEVER = -2;

	/** One place's share. */
	static final class Part
	{
		final Store store;
		final long value;
		final long seenAgo;

		Part(Store store, long value, long seenAgo)
		{
			this.store = store;
			this.value = value;
			this.seenAgo = seenAgo;
		}
	}

	private final List<Part> parts;
	private final long total;
	/** Each place's share, rounded together to make 100%. */
	private final String[] shares;

	StoreBreakdown(List<Part> parts)
	{
		this.parts = parts;
		long sum = 0;
		for (Part p : parts)
		{
			sum += Math.max(0, p.value);
		}
		this.total = Math.max(1, sum);
		long[] values = new long[parts.size()];
		for (int i = 0; i < values.length; i++)
		{
			values[i] = parts.get(i).value;
		}
		shares = Format.shares(values, total);
		setOpaque(false);
		setPreferredSize(new Dimension(10, BAR + 8 + parts.size() * ROW));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		RoundRectangle2D track = new RoundRectangle2D.Float(0, 0, w, BAR, BAR, BAR);
		g.setColor(Theme.INK_DEEP);
		g.fill(track);
		g.setClip(track);
		float x = 0;
		for (Part p : parts)
		{
			float pw = w * Math.max(0, p.value) / (float) total;
			if (pw <= 0)
			{
				continue;
			}
			Color c = Theme.store(p.store);
			g.setPaint(new GradientPaint(0, 0, Theme.mix(c, Theme.GOLD_BRIGHT, 0.2), 0, BAR, Theme.mix(c, Theme.INK, 0.35)));
			g.fill(new java.awt.geom.Rectangle2D.Float(x, 0, pw + 0.5f, BAR));
			g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
			g.drawLine(Math.round(x + pw), 0, Math.round(x + pw), BAR);
			x += pw;
		}
		g.setClip(null);
		g.setColor(Theme.alpha(Theme.GOLD, 90));
		g.draw(new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, BAR - 1, BAR, BAR));

		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		int y = BAR + 8;
		for (int i = 0; i < parts.size(); i++)
		{
			Part p = parts.get(i);
			// An empty place steps back so the eye goes to where the worth actually is.
			boolean empty = p.value == 0;
			Color c = empty ? Theme.alpha(Theme.store(p.store), 90) : Theme.store(p.store);
			int mid = y + ROW / 2 - 1;
			g.setColor(c);
			g.fill(new Ellipse2D.Float(1, mid - 3.5f, 7, 7));
			int base = mid + fm.getAscent() / 2 - 1;
			Ui.shadowed(g, p.store.getLabel(), 14, base, empty ? Theme.TEXT_MUTED : Theme.TEXT);
			String value = p.seenAgo == NEVER ? "-" : Format.coins(p.value);
			String pct = p.seenAgo == NEVER ? "" : shares[i];
			int vw = fm.stringWidth(value);
			int pw = 30;
			Ui.shadowed(g, value, w - pw - vw - 4, base, empty ? Theme.TEXT_FAINT : Theme.mix(c, Theme.TEXT, 0.35));
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(pct, w - fm.stringWidth(pct), base);
			String seen = p.seenAgo == NEVER ? "not seen yet" : p.seenAgo < 0 ? "" : "seen " + Format.ago(p.seenAgo);
			int sx = 14 + fm.stringWidth(p.store.getLabel()) + 6;
			if (sx + fm.stringWidth(seen) < w - pw - vw - 10)
			{
				g.drawString(seen, sx, base);
			}
			y += ROW;
		}
		g.dispose();
	}
}

package com.codex.ledger.ui;

import com.codex.ledger.core.Store;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * The Ledger writes gains in green and losses in blood, keeps gold for worth itself and gives
 * price moves the arcane teal, so a number's colour says what it is before it is read.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** Item quantities in the game's own colours: yellow, white from 100K, green from 10M. */
	public static final Color QTY_YELLOW = new Color(255, 255, 0);
	public static final Color QTY_WHITE = new Color(255, 255, 255);
	public static final Color QTY_GREEN = new Color(0, 255, 128);

	public static final Color GAIN = GREEN;
	public static final Color LOSS = new Color(214, 92, 78);
	public static final Color MARKET = TEAL;
	public static final Color WORTH = GOLD;

	/** A signed amount's colour: green up, blood down, muted at nothing. */
	public static Color signed(long n)
	{
		return n > 0 ? GAIN : n < 0 ? LOSS : TEXT_MUTED;
	}

	/** Each place has its own colour on the worth bar and its legend. */
	public static Color store(Store store)
	{
		switch (store)
		{
			case BANK:
				return GOLD;
			case INVENTORY:
				return TEAL;
			case EQUIPMENT:
				return new Color(150, 170, 230);
			case GRAND_EXCHANGE:
				return GREEN;
			case SEED_VAULT:
				return new Color(196, 168, 92).darker();
			case RUNE_POUCH:
				return new Color(214, 120, 150);
			default:
				return VIOLET;
		}
	}

	public static Color kind(com.codex.ledger.core.Kind kind)
	{
		switch (kind)
		{
			case CASH:
				return GOLD_BRIGHT;
			case GEAR:
				return new Color(150, 170, 230);
			case SUPPLIES:
				return EMBER;
			default:
				return TEAL;
		}
	}

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

package com.codex.ledger.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import javax.swing.JLabel;

/** Small helpers shared by the panel's components. */
public final class Ui
{
	private Ui()
	{
	}

	public static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * A label that wraps inside the side panel's narrow width. Swing's HTML renderer
	 * treats CSS pixels as points, so the width is converted to keep it in screen pixels.
	 */
	public static JLabel wrapped(String text, Font font, Color color, int width)
	{
		int css = Math.round(width * 0.75f);
		return label("<html><div style='width:" + css + "px'>" + escape(text) + "</div></html>", font, color);
	}

	public static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lets a clickable card keep its hover and click while the pointer is over its children. */
	static void forwardMouse(Container root, MouseAdapter adapter)
	{
		for (Component child : root.getComponents())
		{
			child.addMouseListener(adapter);
			if (child instanceof Container)
			{
				forwardMouse((Container) child, adapter);
			}
		}
	}

	/** Text with the one pixel black shadow the game puts under its own lettering. */
	public static void shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	/** Cuts text to fit a width, ending it with an ellipsis. */
	public static String clip(String text, java.awt.FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + "...") > width)
		{
			end--;
		}
		return text.substring(0, end) + "...";
	}
}

package com.codex.ledger.ui;

import com.codex.ledger.core.Ledger;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.util.List;
import javax.swing.JComponent;

/**
 * Worth over time as a gilt line over a fading wash of gold, with a dashed line where the range
 * began, the high and low marked, and a crosshair that reads out any moment under the pointer.
 */
class WorthChart extends JComponent
{
	private static final int TOP = 20;
	private static final int BOTTOM = 16;

	private final List<Ledger.Point> points;
	private final long from;
	private final long to;
	private final boolean intraday;
	private int hover = -1;
	/** Where the pointer was, carried from the chart this one replaced so a refresh keeps the crosshair. */
	private final int[] pointer;

	/**
	 * @param points oldest first, already cut to the range
	 * @param intraday label the axis with times rather than dates
	 */
	WorthChart(List<Ledger.Point> points, long from, long to, boolean intraday, int[] pointer)
	{
		this.pointer = pointer;
		this.points = points;
		this.from = from;
		this.to = Math.max(from + 1, to);
		this.intraday = intraday;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 132));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				pointer[0] = e.getX();
				int index = nearest(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				pointer[0] = -1;
				hover = -1;
				repaint();
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	private float xOf(long t)
	{
		return 2 + (getWidth() - 4) * (float) ((t - from) / (double) (to - from));
	}

	private int nearest(int x)
	{
		int best = -1;
		float bestDistance = Float.MAX_VALUE;
		for (int i = 0; i < points.size(); i++)
		{
			float d = Math.abs(xOf(points.get(i).getTime()) - x);
			if (d < bestDistance)
			{
				bestDistance = d;
				best = i;
			}
		}
		return best;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int plotBottom = h - BOTTOM;
		if (hover < 0 && pointer[0] >= 0)
		{
			hover = nearest(pointer[0]);
		}
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();

		// Guide lines.
		g.setColor(Theme.alpha(Theme.STROKE_SOFT, 150));
		for (int i = 0; i <= 2; i++)
		{
			int gy = TOP + (plotBottom - TOP) * i / 2;
			g.drawLine(0, gy, w, gy);
		}

		if (points.size() < 2)
		{
			String text = "The line fills in as you play";
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(text, (w - fm.stringWidth(text)) / 2, (TOP + plotBottom) / 2 + fm.getAscent() / 2);
			g.dispose();
			return;
		}

		long min = Long.MAX_VALUE;
		long max = Long.MIN_VALUE;
		int hi = 0;
		int lo = 0;
		for (int i = 0; i < points.size(); i++)
		{
			long v = points.get(i).getValue();
			if (v > max)
			{
				max = v;
				hi = i;
			}
			if (v < min)
			{
				min = v;
				lo = i;
			}
		}
		long span = Math.max(1, max - min);
		double pad = span * 0.12;
		double low = min - pad;
		double high = max + pad;
		java.util.function.LongFunction<Float> yOf = v -> (float) (plotBottom - (plotBottom - TOP) * ((v - low) / (high - low)));

		Path2D line = new Path2D.Float();
		Path2D area = new Path2D.Float();
		for (int i = 0; i < points.size(); i++)
		{
			float px = xOf(points.get(i).getTime());
			float py = yOf.apply(points.get(i).getValue());
			if (i == 0)
			{
				line.moveTo(px, py);
				area.moveTo(px, plotBottom);
				area.lineTo(px, py);
			}
			else
			{
				line.lineTo(px, py);
				area.lineTo(px, py);
			}
		}
		area.lineTo(xOf(points.get(points.size() - 1).getTime()), plotBottom);
		area.closePath();

		long first = points.get(0).getValue();
		long last = points.get(points.size() - 1).getValue();
		Color tone = last >= first ? Theme.GOLD : Theme.mix(Theme.GOLD, Theme.LOSS, 0.45);
		g.setPaint(new GradientPaint(0, TOP, Theme.alpha(tone, 90), 0, plotBottom, Theme.alpha(tone, 0)));
		g.fill(area);

		// Where the range began.
		float base = yOf.apply(first);
		g.setStroke(new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 1, new float[]{3, 3}, 0));
		g.setColor(Theme.alpha(Theme.TEXT_MUTED, 110));
		g.drawLine(0, Math.round(base), w, Math.round(base));

		g.setStroke(new BasicStroke(3.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
		g.draw(line);
		g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setPaint(new GradientPaint(0, 0, Theme.mix(tone, Theme.INK, 0.25), w, 0, Theme.mix(tone, Theme.GOLD_BRIGHT, 0.6)));
		g.draw(line);
		g.setStroke(new BasicStroke(1));

		// High and low.
		marker(g, fm, xOf(points.get(hi).getTime()), yOf.apply(max), "High " + Format.coins(max), true, w, TOP, plotBottom);
		if (lo != hi)
		{
			marker(g, fm, xOf(points.get(lo).getTime()), yOf.apply(min), "Low " + Format.coins(min), false, w, TOP, plotBottom);
		}

		// The present, glowing.
		float ex = xOf(points.get(points.size() - 1).getTime());
		float ey = yOf.apply(last);
		g.setColor(Theme.alpha(Theme.GOLD_BRIGHT, 70));
		g.fill(new Ellipse2D.Float(ex - 5, ey - 5, 10, 10));
		g.setColor(Theme.GOLD_BRIGHT);
		g.fill(new Ellipse2D.Float(ex - 2.5f, ey - 2.5f, 5, 5));

		// Axis labels at the start, middle and end.
		g.setColor(Theme.TEXT_FAINT);
		for (int i = 0; i <= 2; i++)
		{
			long t = from + (to - from) * i / 2;
			String label = intraday ? Format.time(t) : to - from > 300L * 86_400_000L ? Format.month(t) : Format.shortDay(t);
			int lx = i == 0 ? 0 : i == 1 ? (w - fm.stringWidth(label)) / 2 : w - fm.stringWidth(label);
			g.drawString(label, lx, h - 3);
		}

		if (hover >= 0)
		{
			Ledger.Point p = points.get(hover);
			float hx = xOf(p.getTime());
			float hy = yOf.apply(p.getValue());
			g.setColor(Theme.alpha(Theme.GOLD, 120));
			g.drawLine(Math.round(hx), TOP, Math.round(hx), plotBottom);
			g.setColor(Theme.INK_DEEP);
			g.fill(new Ellipse2D.Float(hx - 4, hy - 4, 8, 8));
			g.setColor(Theme.GOLD_BRIGHT);
			g.fill(new Ellipse2D.Float(hx - 2.5f, hy - 2.5f, 5, 5));
			String when = intraday ? Format.time(p.getTime()) : Format.day(p.getTime()) + " " + Format.time(p.getTime());
			String worth = Format.coins(p.getValue());
			long delta = p.getValue() - first;
			String change = Format.signed(delta);
			int boxW = fm.stringWidth(when) + fm.stringWidth(worth) + fm.stringWidth(change) + 26;
			int bx = Math.max(0, Math.min(w - boxW, Math.round(hx - boxW / 2f)));
			RoundRectangle2D box = new RoundRectangle2D.Float(bx + 0.5f, 0.5f, boxW - 1, 16, 6, 6);
			g.setColor(Theme.alpha(Theme.INK_DEEP, 235));
			g.fill(box);
			g.setColor(Theme.alpha(Theme.GOLD, 140));
			g.draw(box);
			int tx = bx + 6;
			int ty = 12;
			Ui.shadowed(g, when, tx, ty, Theme.TEXT_MUTED);
			tx += fm.stringWidth(when) + 7;
			Ui.shadowed(g, worth, tx, ty, Theme.GOLD_BRIGHT);
			tx += fm.stringWidth(worth) + 7;
			Ui.shadowed(g, change, tx, ty, Theme.signed(delta));
		}
		g.dispose();
	}

	private static void marker(Graphics2D g, FontMetrics fm, float x, float y, String label, boolean above, int w, int top, int bottom)
	{
		Path2D tri = new Path2D.Float();
		if (above)
		{
			tri.moveTo(x, y - 3);
			tri.lineTo(x + 3, y - 7);
			tri.lineTo(x - 3, y - 7);
		}
		else
		{
			tri.moveTo(x, y + 3);
			tri.lineTo(x + 3, y + 7);
			tri.lineTo(x - 3, y + 7);
		}
		tri.closePath();
		Color c = above ? Theme.GAIN : Theme.LOSS;
		g.setColor(c);
		g.fill(tri);
		int lw = fm.stringWidth(label);
		int lx = Math.round(x + 6);
		if (lx + lw > w)
		{
			lx = Math.round(x - 6 - lw);
		}
		int ly = Math.round(above ? y - 3 : y + fm.getAscent() + 3);
		ly = Math.max(top + fm.getAscent() - 4, Math.min(bottom - 2, ly));
		Ui.shadowed(g, label, Math.max(0, lx), ly, Theme.mix(c, Theme.TEXT, 0.3));
	}
}

package com.codex.ledger;

import java.lang.reflect.Method;
import java.util.HashSet;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** Settings keep the keys their values are saved under. */
public class SavedSettingsTest
{
	/** Every key the released plugin (main) saves settings under. */
	private static final String[] ON_MAIN = {"loginSummary", "showPlaque"};
	/** Keys added since, which players will have saved by the time this ships. */
	private static final String[] ADDED = {"goal", "goalName", "nameOnCard"};

	@Test
	public void savedSettingsKeepTheirKeys()
	{
		// A setting's key is where its value is saved: renaming one quietly resets it for every player who
		// changed it. A display name may change freely; a key may not.
		Set<String> keys = new HashSet<>();
		for (Method m : CodexLedgerConfig.class.getMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item != null)
			{
				keys.add(item.keyName());
			}
		}
		for (String key : ON_MAIN)
		{
			assertTrue(key, keys.contains(key));
		}
		for (String key : ADDED)
		{
			assertTrue(key, keys.contains(key));
		}
	}
}

package com.codex.ledger.core;

import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class AlchemyTest
{
	private static final int PLATEBODY = 1127;
	private static final int ARROW_SHAFTS = 52;
	private static final int WHIP = 4151;
	private static final int UNTRADEABLE = 6570;
	private static final int TRINKET = 1704;

	@Test
	public void weighsAlchingAfterTheRuneAgainstSellingAfterTax()
	{
		Map<Integer, Long> held = new HashMap<>();
		held.put(Alchemy.COINS, 5_000_000L);
		held.put(Alchemy.NATURE_RUNE, 2_000L);
		held.put(PLATEBODY, 10L);
		held.put(ARROW_SHAFTS, 1_000L);
		held.put(WHIP, 1L);
		held.put(UNTRADEABLE, 1L);
		held.put(TRINKET, 2L);
		Map<Integer, Long> price = new HashMap<>();
		price.put(Alchemy.NATURE_RUNE, 100L);
		price.put(PLATEBODY, 38_000L);
		price.put(ARROW_SHAFTS, 40L);
		price.put(WHIP, 1_300_000L);
		price.put(TRINKET, 10_000L);
		Map<Integer, Long> alch = new HashMap<>();
		alch.put(PLATEBODY, 39_000L);
		alch.put(ARROW_SHAFTS, 200L);
		alch.put(WHIP, 72_000L);
		alch.put(UNTRADEABLE, 50_000L);
		alch.put(TRINKET, 12_000L);
		Alchemy a = Alchemy.of(held, id -> price.getOrDefault(id, 0L), id -> alch.getOrDefault(id, 0L), 100);

		assertEquals(2, a.getLines().size());
		// Under 50 coins there is no tax: 100 a cast against 40 sold.
		Alchemy.Line shafts = a.getLines().get(0);
		assertEquals(ARROW_SHAFTS, shafts.getItemId());
		assertEquals(100, shafts.getAlch());
		assertEquals(40, shafts.getSale());
		assertEquals(60_000, shafts.gain());
		// 38,900 a cast against 38,000 less 2% tax.
		Alchemy.Line body = a.getLines().get(1);
		assertEquals(38_900, body.getAlch());
		assertEquals(37_240, body.getSale());
		assertEquals(16_600, body.gain());
		assertEquals(76_600, a.getGain());
		assertEquals(1_010, a.getCasts());
		// The whip sells for far more; the untradeable cannot be sold to compare; two trinkets make too
		// little (4,200) to be worth the casts; coins and the runes themselves are never weighed.
		assertTrue(a.getLines().stream().noneMatch(l -> l.getItemId() == WHIP || l.getItemId() == UNTRADEABLE
			|| l.getItemId() == TRINKET || l.getItemId() == Alchemy.COINS));
	}

	@Test
	public void nothingBetterAlchedIsEmpty()
	{
		Map<Integer, Long> held = new HashMap<>();
		held.put(WHIP, 1L);
		Alchemy a = Alchemy.of(held, id -> 1_300_000L, id -> 72_000L, 100);
		assertTrue(a.isEmpty());
		assertEquals(0, a.getGain());
	}

	@Test
	public void withoutANatureRunePriceNothingIsCalledBetterAlched()
	{
		// The ledger keeps prices only for what is held: an account with no nature runes has none for
		// them, and alching looked a nature rune cheaper than it is (free), so 1,000 platebodies that
		// alch for 38,050 against 37,240 sold were called better alched though each cast loses 50.
		Map<Integer, Long> held = new HashMap<>();
		held.put(PLATEBODY, 1_000L);
		Alchemy blind = Alchemy.of(held, id -> id == PLATEBODY ? 38_000L : 0L, id -> 37_290L, 0);
		assertTrue(blind.isEmpty());
		Alchemy priced = Alchemy.of(held, id -> id == PLATEBODY ? 38_000L : 0L, id -> 37_290L, 100);
		assertTrue("37,190 a cast against 37,240 sold", priced.isEmpty());
		Alchemy cheaper = Alchemy.of(held, id -> id == PLATEBODY ? 38_000L : 0L, id -> 39_000L, 100);
		assertEquals(1_660_000, cheaper.getGain());
	}
}

package com.codex.ledger.core;

import com.google.gson.Gson;
import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Codex Bank Steward's copy of the bank, read for the estimate shown before the ledger sees the bank.
 * {@code bank-steward-bankV1.json} is a byte-for-byte copy of the fixture Bank Steward's own
 * BankSnapshotTest proves its writer produces.
 */
public class BankCopyTest
{
	private static final Gson GSON = new Gson();

	private static String fixture() throws Exception
	{
		try (java.io.InputStream in = BankCopyTest.class.getResourceAsStream("bank-steward-bankV1.json"))
		{
			return new String(in.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8);
		}
	}

	@Test
	public void readsTheBankStewardsOwnCodeWrites() throws Exception
	{
		BankCopy copy = BankCopy.read(GSON, fixture());
		assertEquals(1_760_000_000_000L, copy.getSavedAt());
		assertFalse(copy.isTruncated());
		assertEquals(6, copy.getItems().size());
		assertEquals(1_234_567L, (long) copy.getItems().get(995));
		assertEquals(240L, (long) copy.getItems().get(385));
	}

	@Test
	public void pricesItAsTheLedgerWouldWithUnpricedItemsAsNothing() throws Exception
	{
		Map<Integer, Long> prices = new HashMap<>();
		prices.put(995, 1L);
		prices.put(385, 300L);
		prices.put(2434, 9_000L);
		prices.put(26950, 1_000_000L);
		BankCopy.Estimate e = BankCopy.read(GSON, fixture()).estimate(id -> prices.getOrDefault(id, 0L));
		assertEquals(1_234_567 + 240 * 300 + 30 * 9_000 + 1_000_000, e.getBank());
		assertEquals(6, e.getKinds());
		assertEquals(1_760_000_000_000L, e.getSavedAt());
	}

	@Test
	public void aShortCopySaysSo()
	{
		BankCopy copy = BankCopy.read(GSON, "{\"version\":1,\"savedAt\":5,\"items\":{\"995\":10},\"truncated\":true}");
		assertTrue(copy.isTruncated());
	}

	@Test
	public void anythingElseIsNoCopy()
	{
		assertNull(BankCopy.read(GSON, null));
		assertNull(BankCopy.read(GSON, ""));
		assertNull(BankCopy.read(GSON, "[1,2]"));
		assertNull(BankCopy.read(GSON, "{\"items\":[1]}"));
		assertNull(BankCopy.read(GSON, "{\"items\":{}}"));
		assertNull(BankCopy.read(GSON, "not json at all {"));
		// Odd entries are skipped, the rest still read.
		BankCopy copy = BankCopy.read(GSON, "{\"items\":{\"x\":3,\"-4\":2,\"995\":\"many\",\"4151\":1,\"11802\":0}}");
		assertEquals(1, copy.getItems().size());
		assertEquals(0, copy.getSavedAt());
	}
}

package com.codex.ledger.core;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.Arrays;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class EarningsTest
{
	private static final long HOUR = 3_600_000L;
	private static final long DAY = 24 * HOUR;
	private static final long NOW = 1_790_000_000_000L;

	@Test
	public void readsChroniclesJournalAsItSavesIt()
	{
		// Codex Session Chronicle's journal as its own code writes it (pinned by its ActivitiesTest): a list
		// of filed sessions with "startedAt", "playedMs", "activity", and the net worth this ledger had
		// as each began ("worthStart") and ended ("worthNow"), among much else that is ignored here.
		String journal = "[{\"startedAt\":" + (NOW - DAY) + ",\"lastSeenAt\":" + (NOW - DAY + HOUR) + ",\"endedAt\":" + (NOW - DAY + HOUR)
			+ ",\"playedMs\":" + HOUR + ",\"player\":\"Zezima\",\"skills\":{\"Ranged\":{\"skill\":\"Ranged\",\"startXp\":0,\"xp\":140000}},"
			+ "\"loot\":{},\"kills\":{\"vorkath\":{\"name\":\"Vorkath\",\"looted\":20,\"firstKc\":0,\"lastKc\":0,\"event\":false,"
			+ "\"tasks\":{\"\":20}}},\"moments\":[],\"deaths\":0,\"otherLoot\":0,\"otherDrops\":0,\"activity\":\"Vorkath\","
			+ "\"worthStart\":1000000000,\"worthNow\":1002500000,\"tripCount\":0,\"tripMs\":0,\"bestTripMs\":0},"
			+ "{\"startedAt\":" + (NOW - 2 * DAY) + ",\"playedMs\":" + 2 * HOUR + ",\"activity\":\"Mining\",\"worthStart\":900000000,"
			+ "\"worthNow\":900300000},"
			+ "{\"startedAt\":" + (NOW - 3 * DAY) + ",\"playedMs\":" + HOUR + ",\"activity\":\"vorkath\",\"worthStart\":1000000000,"
			+ "\"worthNow\":1001500000},"
			+ "{\"startedAt\":" + (NOW - 4 * DAY) + ",\"playedMs\":" + HOUR + ",\"activity\":\"Fishing\"},"
			+ "{\"startedAt\":" + (NOW - 5 * DAY) + ",\"playedMs\":600000,\"activity\":\"Agility\",\"worthStart\":1,\"worthNow\":2},"
			+ "{\"startedAt\":" + (NOW - 40 * DAY) + ",\"playedMs\":" + HOUR + ",\"activity\":\"Zulrah\",\"worthStart\":1,\"worthNow\":9}]";
		List<Earnings.Logged> sessions = new Gson().fromJson(journal, new TypeToken<List<Earnings.Logged>>()
		{
		}.getType());
		Earnings e = Earnings.of(sessions, NOW);
		assertEquals(2, e.getLines().size());
		Earnings.Line vork = e.getLines().get(0);
		assertEquals("Vorkath", vork.getName());
		assertEquals("names are matched whatever their case", 2, vork.getSessions());
		assertEquals(4_000_000, vork.getChange());
		assertEquals(2_000_000, vork.perHour());
		Earnings.Line mining = e.getLines().get(1);
		assertEquals(150_000, mining.perHour());
		// Fishing had no worth from the ledger, Agility was too short, Zulrah too long ago.
		assertEquals(3, e.getDays());
	}

	@Test
	public void aSessionInTheJournalTwiceCountsOnce()
	{
		Earnings.Logged one = new Earnings.Logged(NOW - DAY, HOUR, 0L, 1_000_000L, "Vorkath");
