package com.codex.ledger.core;

import java.util.ArrayList;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class HistoryTest
{
	@Test
	public void keepsDetailRecentlyAndDailyPointsLongAgo()
	{
		long now = 400L * History.DAY;
		List<Ledger.Point> points = new ArrayList<>();
		for (long t = now - 90 * History.DAY; t <= now; t += 5 * History.MINUTE)
		{
			points.add(new Ledger.Point(t, t));
		}
		List<Ledger.Point> kept = History.compact(points, now);
		assertEquals(now, kept.get(kept.size() - 1).getTime());
		assertTrue(kept.size() < 1_000);
		// Two days at 15 minutes is 192 points; forty-three more at 3 hours is 344; the rest daily.
		assertTrue(kept.size() > 192 + 344);
		for (int i = 1; i < kept.size(); i++)
		{
			assertTrue(kept.get(i).getTime() > kept.get(i - 1).getTime());
		}
	}
}

package com.codex.ledger.core;

import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class HoursAndKindsTest
{
	private static final long T0 = 1_790_000_000_000L - 1_790_000_000_000L % 86_400_000L + 8 * 3_600_000L;
	private static final int WHIP = 4151;
	private static final int SHARK = 385;
	private static final int LOGS = 1513;
	private static final Map<Integer, Long> PRICE = new HashMap<>();

	static
	{
		PRICE.put(995, 1L);
		PRICE.put(WHIP, 1_500_000L);
		PRICE.put(SHARK, 700L);
		PRICE.put(LOGS, 300L);
	}

	private static final Prices PRICES = id -> PRICE.getOrDefault(id, 0L);

	private static Kind kind(int id)
	{
		return id == WHIP ? Kind.GEAR : id == SHARK ? Kind.SUPPLIES : Kind.MATERIALS;
	}

	@Test
	public void timeLoggedInCountsTicksAndSkipsGaps()
	{
		Ledger ledger = opened();
		long t = T0;
		assertFalse("the first tick only starts the clock", ledger.played(t, ZoneOffset.UTC));
		for (int i = 0; i < 100; i++)
		{
			t += 600;
			assertTrue(ledger.played(t, ZoneOffset.UTC));
		}
		// A loading screen or a logout of a minute is not play.
		t += 60_000;
		assertFalse(ledger.played(t, ZoneOffset.UTC));
		t += 600;
		ledger.played(t, ZoneOffset.UTC);
		ledger.pause();
		t += 600;
		assertFalse("after a pause the clock starts again", ledger.played(t, ZoneOffset.UTC));
		assertEquals(101 * 600, ledger.day(date(T0)).getPlayedMs());
	}

	@Test
	public void hourlyPlayLeavesMarketAndUntimedPagesOut()
	{
		Ledger ledger = opened();
		long t = T0;
		ledger.played(t, ZoneOffset.UTC);
		// Half an hour of play that brings in 600 logs (+180k), while the whip's price rises 100k.
		for (int i = 1; i <= 3_000; i++)
		{
			t += 600;
			ledger.played(t, ZoneOffset.UTC);
		}
		PRICE.put(WHIP, 1_600_000L);
		try
		{
			ledger.observe(Store.INVENTORY, items(LOGS, 600L));
			ledger.settle(t, PRICES, ZoneOffset.UTC);
			Report today = Report.of(ledger, 1, date(T0), 5);
			assertEquals(30 * 60_000L, today.getPlayedMs());
			assertTrue(today.hasHourly());
			assertEquals(180_000, today.getPlay());
			assertEquals(360_000, today.perHour());
			Report page = Report.page(ledger.day(date(T0)), 5);
			assertEquals(360_000, page.perHour());

			// A page with no time kept (written before the time was) never dilutes the hourly figure.
			Report week = Report.of(ledger, 7, date(T0), 5);
			assertEquals(360_000, week.perHour());
			Ledger brief = opened();
			brief.played(T0, ZoneOffset.UTC);
			brief.played(T0 + 600, ZoneOffset.UTC);
			assertFalse("a few seconds give no hourly figure", Report.of(brief, 1, date(T0), 5).hasHourly());
			assertEquals(0, Report.of(brief, 1, date(T0), 5).perHour());
		}
		finally
		{
			PRICE.put(WHIP, 1_500_000L);
		}
	}

	@Test
	public void worthIsToldApartByKindAndItsChangeOverTheSpan()
	{
		Ledger ledger = new Ledger();
		ledger.setKinds(HoursAndKindsTest::kind);
		ledger.observe(Store.BANK, items(995, 2_000_000L, SHARK, 100L, LOGS, 1_000L));
		ledger.settle(T0, PRICES, ZoneOffset.UTC);
		assertArrayEquals(new long[]{2_000_000, 0, 70_000, 300_000}, ledger.getDays().get(0).getKinds());

		// Next day the coins buy a whip: cash turns into gear.
		long t1 = T0 + 86_400_000L;
		ledger.observe(Store.BANK, items(995, 500_000L, WHIP, 1L, SHARK, 100L, LOGS, 1_000L));
		ledger.settle(t1, PRICES, ZoneOffset.UTC);
		Report today = Report.of(ledger, 1, date(t1), 5);
		assertArrayEquals(new long[]{500_000, 1_500_000, 70_000, 300_000}, today.getKinds());
		assertArrayEquals(new long[]{-1_500_000, 1_500_000, 0, 0}, today.kindChange());
		assertNull("nothing before the ledger began to measure from", Report.of(ledger, 0, date(t1), 5).kindChange());

		// Without a way to tell kinds apart, pages carry none, and nothing breaks.
		Ledger plain = opened();
		assertNull(plain.getDays().get(0).getKinds());
		assertNull(Report.of(plain, 1, date(T0), 5).getKinds());
	}

	private static Ledger opened()
	{
		Ledger ledger = new Ledger();
		ledger.observe(Store.BANK, items(995, 1_000_000L, WHIP, 1L));
		ledger.observe(Store.INVENTORY, items());
		ledger.settle(T0, PRICES, ZoneOffset.UTC);
		return ledger;
	}

	private static LocalDate date(long t)
	{
		return java.time.Instant.ofEpochMilli(t).atZone(ZoneOffset.UTC).toLocalDate();
	}

	private static Map<Integer, Long> items(Object... pairs)
	{
		Map<Integer, Long> m = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put(((Number) pairs[i]).intValue(), ((Number) pairs[i + 1]).longValue());
		}
		return m;
	}

	@Test
	public void itemsAreToldApartFromWhatTheGameSays()
	{
		assertEquals(Kind.CASH, Kinds.of(995, "Coins", null, false, -1, true));
		assertEquals(Kind.CASH, Kinds.of(13204, "Platinum token", null, false, -1, true));
		assertEquals(Kind.GEAR, Kinds.of(WHIP, "Abyssal whip", new String[]{null, "Wield", null, null, "Drop"}, true, 3, false));
		assertEquals(Kind.SUPPLIES, Kinds.of(11212, "Dragon arrow", new String[]{null, "Wield"}, true, 13, true));
		assertEquals(Kind.SUPPLIES, Kinds.of(11230, "Dragon dart", new String[]{null, "Wield"}, true, 3, true));
		assertEquals(Kind.SUPPLIES, Kinds.of(SHARK, "Shark", new String[]{"Eat", null, null, null, "Drop"}, false, -1, false));
		assertEquals(Kind.SUPPLIES, Kinds.of(2434, "Prayer potion(4)", new String[]{"Drink"}, false, -1, false));
		assertEquals(Kind.SUPPLIES, Kinds.of(8013, "Teleport to house", new String[]{"Break"}, false, -1, false));
		assertEquals(Kind.SUPPLIES, Kinds.of(560, "Death rune", null, false, -1, true));
		assertEquals(Kind.MATERIALS, Kinds.of(LOGS, "Magic logs", null, false, -1, false));
		assertEquals(Kind.MATERIALS, Kinds.of(536, "Dragon bones", new String[]{"Bury"}, false, -1, false));
	}
}

package com.codex.ledger.core;

import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class LedgerTest
{
	private static final ZoneId UTC = ZoneOffset.UTC;
	private static final long DAY = 86_400_000L;
	/** Noon on 1 October 2026, UTC. */
	private static final long T0 = LocalDate.of(2026, 10, 1).atStartOfDay(UTC).toInstant().toEpochMilli() + DAY / 2;
	private static final int COINS = 995;
	private static final int SHARK = 385;
	private static final int WHIP = 4151;

	private final Map<Integer, Long> price = new HashMap<>();
	private final Prices prices = id -> price.getOrDefault(id, 0L);
	private Ledger ledger;

	@Before
	public void setUp()
	{
		price.put(COINS, 1L);
		price.put(SHARK, 800L);
		price.put(WHIP, 1_500_000L);
		ledger = new Ledger();
	}

	private static Map<Integer, Long> items(long... pairs)
	{
		Map<Integer, Long> m = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put((int) pairs[i], pairs[i + 1]);
		}
		return m;
	}

	private void open()
	{
		ledger.observe(Store.INVENTORY, items(SHARK, 10));
		ledger.observe(Store.BANK, items(COINS, 1_000_000, WHIP, 1));
		ledger.offer(7, null);
		ledger.settle(T0, prices, UTC);
	}

	@Test
	public void beginsWhenTheBankIsSeen()
	{
		ledger.observe(Store.INVENTORY, items(SHARK, 10));
		ledger.settle(T0, prices, UTC);
		assertFalse(ledger.isReady());
		assertTrue(ledger.getDays().isEmpty());
		assertEquals(8_000, ledger.getTotal());

		ledger.observe(Store.BANK, items(COINS, 1_000_000, WHIP, 1));
		ledger.settle(T0 + 1000, prices, UTC);
		assertTrue(ledger.isReady());
		assertEquals(2_508_000, ledger.getTotal());
		assertEquals(1, ledger.getDays().size());
		Day day = ledger.getDays().get(0);
		assertEquals(2_508_000, day.getOpen());
		assertEquals(0, day.change());
		assertEquals(1, ledger.getHistory().size());
	}

	@Test
	public void movingItemsBetweenPlacesIsNotAGain()
	{
		open();
		ledger.observe(Store.INVENTORY, items(SHARK, 10, WHIP, 1));
		ledger.observe(Store.BANK, items(COINS, 1_000_000));
		ledger.settle(T0 + 60_000, prices, UTC);
		Day day = ledger.getDays().get(0);
		assertEquals(0, day.getPlay());
		assertEquals(0, day.change());
		assertTrue(day.getItems().isEmpty());
	}

	@Test
	public void eatingSharksIsPlayAndPricesAreMarket()
	{
		open();
		ledger.observe(Store.INVENTORY, items(SHARK, 4));
		ledger.settle(T0 + 60_000, prices, UTC);
		price.put(WHIP, 1_600_000L);
		ledger.settle(T0 + 120_000, prices, UTC);

		Day day = ledger.getDays().get(0);
		assertEquals(-4_800, day.getPlay());
		assertEquals(100_000, day.getMarket());
		assertEquals(95_200, day.change());
		assertEquals(2_603_200, ledger.getTotal());
		assertEquals(-6, day.getItems().get(SHARK).getQuantity());
		assertEquals(100_000, day.getItems().get(WHIP).getDrift());
	}

	@Test
	public void aPlaceSeenForTheFirstTimeIsOpeningBalance()
	{
		open();
		ledger.observe(Store.SEED_VAULT, items(SHARK, 100));
		ledger.settle(T0 + 60_000, prices, UTC);
		Day day = ledger.getDays().get(0);
		assertEquals(0, day.getPlay());
		assertEquals(0, day.change());
		assertEquals(2_588_000, day.getOpen());
		assertEquals(2_588_000, ledger.getTotal());
	}

	@Test
	public void unknownPricesKeepTheLastOne()
	{
		open();
		price.remove(WHIP);
		ledger.settle(T0 + 60_000, prices, UTC);
		assertEquals(2_508_000, ledger.getTotal());
		assertEquals(0, ledger.getDays().get(0).getMarket());
	}

	@Test
	public void aNewDayOpensOnYesterdaysClose()
	{
		open();
		ledger.observe(Store.BANK, items(COINS, 2_000_000, WHIP, 1));
		ledger.settle(T0 + 60_000, prices, UTC);
		ledger.observe(Store.BANK, items(COINS, 1_500_000, WHIP, 1));
		ledger.settle(T0 + DAY, prices, UTC);

		assertEquals(2, ledger.getDays().size());
		Day second = ledger.getDays().get(1);
		assertEquals(3_508_000, second.getOpen());
		assertEquals(-500_000, second.change());

		Report week = Report.of(ledger, 7, LocalDate.of(2026, 10, 2), 5);
		assertEquals(2, week.getDays());
		assertEquals(500_000, week.change());
		assertEquals(2_508_000, week.getStart());
		assertEquals(COINS, week.getGains().get(0).getItemId());
		assertEquals(500_000, week.getGains().get(0).getValue());

		Report today = Report.of(ledger, 1, LocalDate.of(2026, 10, 2), 5);
		assertEquals(-500_000, today.change());
		assertEquals(COINS, today.getLosses().get(0).getItemId());
	}

	@Test
	public void nothingChangedIsQuiet()
	{
		open();
		assertFalse(ledger.settle(T0 + 60_000, prices, UTC));
		assertEquals(1, ledger.getHistory().size());
	}

	@Test
	public void holdingsRankByValue()
	{
		open();
		assertEquals(WHIP, Report.holdings(ledger, 10).get(0).getItemId());
		assertEquals(3, Report.holdings(ledger, 10).size());
		assertEquals(8_000, ledger.value(Store.INVENTORY));
	}

	private static Offer buy(int item, int total, long price, int done, long spent, boolean active)
	{
		return new Offer(item, true, total, price, done, spent, active);
	}

	private static Offer sell(int item, int total, long price, int done, long spent, boolean active)
	{
		return new Offer(item, false, total, price, done, spent, active);
	}

	private long bank(int item)
	{
		return ledger.getStores().get(Store.BANK).getItems().getOrDefault(item, 0L);
	}

	@Test
	public void collectingToTheBankIsNotALoss()
	{
		open();
		// A whip bought for 1M with coins from the bank, then collected while the bank is closed.
		ledger.observe(Store.BANK, items(WHIP, 1));
		ledger.offer(0, buy(WHIP, 1, 1_000_000, 0, 0, true));
		ledger.settle(T0 + 1000, prices, UTC);
		assertEquals(2_508_000, ledger.getTotal());
		ledger.offer(0, buy(WHIP, 1, 1_000_000, 1, 1_000_000, false));
		ledger.settle(T0 + 1500, prices, UTC);
		assertEquals(3_008_000, ledger.getTotal());
		ledger.offer(0, null);
		ledger.settle(T0 + 2000, prices, UTC);
		assertEquals(2, bank(WHIP));
		assertEquals(3_008_000, ledger.getTotal());

		// Collected to the inventory instead, it lands there and nowhere else.
		ledger.observe(Store.INVENTORY, items());
		ledger.offer(1, sell(SHARK, 10, 800, 0, 0, true));
		ledger.settle(T0 + 3000, prices, UTC);
		ledger.offer(1, sell(SHARK, 10, 800, 0, 0, false));
		ledger.settle(T0 + 3500, prices, UTC);
		ledger.offer(1, null);
		ledger.observe(Store.INVENTORY, items(SHARK, 10));
		ledger.settle(T0 + 4000, prices, UTC);
		assertEquals(0, bank(SHARK));
		assertEquals(3_008_000, ledger.getTotal());
		assertEquals(500_000, ledger.getDays().get(0).getPlay());
	}

	@Test
	public void anOfferFillingIsNotACollection()
	{
		open();
		// Bid 1,000 coins each for 1,000 sharks; they trade at 800.
		ledger.observe(Store.BANK, items(WHIP, 1));
		ledger.offer(0, buy(SHARK, 1_000, 1_000, 0, 0, true));
		ledger.settle(T0 + 1000, prices, UTC);
		assertEquals(2_508_000, ledger.getTotal());

		// Half fill at 900 each: 450k coins become 500 sharks worth 400k.
		ledger.offer(0, buy(SHARK, 1_000, 1_000, 500, 450_000, true));
		ledger.settle(T0 + 2000, prices, UTC);
		assertEquals(0, bank(COINS));
		assertEquals(0, bank(SHARK));
		assertEquals(550_000, (long) ledger.getStores().get(Store.GRAND_EXCHANGE).getItems().get(COINS));
		assertEquals(2_508_000 - 50_000, ledger.getTotal());
	}

	@Test
	public void aSaleCountsTheTaxAndCollectingTheCoinsIsNotAGain()
	{
		open();
		ledger.observe(Store.BANK, items(COINS, 1_000_000));
		ledger.offer(2, sell(WHIP, 1, 1_500_000, 0, 0, true));
		ledger.settle(T0 + 1000, prices, UTC);
		assertEquals(2_508_000, ledger.getTotal());

		ledger.offer(2, sell(WHIP, 1, 1_500_000, 1, 1_500_000, false));
		ledger.settle(T0 + 2000, prices, UTC);
		// 2% tax: 30k.
		assertEquals(2_478_000, ledger.getTotal());
		assertEquals(-30_000, ledger.getDays().get(0).getPlay());

		ledger.offer(2, null);
		ledger.observe(Store.INVENTORY, items(SHARK, 10, COINS, 1_470_000));
		ledger.settle(T0 + 3000, prices, UTC);
		assertEquals(2_478_000, ledger.getTotal());
		assertEquals(1_000_000, bank(COINS));
	}

	@Test
	public void taxIsCappedAndSkipsCheapItemsAndBonds()
	{
		assertEquals(5_000_000L, Offer.tax(WHIP, 1, 1_000_000_000L));
		assertEquals(0, Offer.tax(SHARK, 100, 4_900));
		assertEquals(0, Offer.tax(Ledger.BOND, 1, 10_000_000L));
		assertEquals(2 * 16, Offer.tax(SHARK, 2, 1_600));
	}

	@Test
	public void theItemsTheGameLeavesUntaxedPayNoTax()
	{
		// Lobsters at 150, rings of dueling (8) at 900 and house tabs at 500 would pay 3, 18 and 10 each.
		assertEquals(0, Offer.tax(379, 1_000, 150_000));
		assertEquals(0, Offer.tax(2552, 10, 9_000));
		assertEquals(0, Offer.tax(8013, 100, 50_000));
		// Energy potions, the Civitas tablet and the saw too.
		assertEquals(0, Offer.tax(3008, 50, 25_000));
		assertEquals(0, Offer.tax(28824, 20, 20_000));
		assertEquals(0, Offer.tax(8794, 5, 2_500));
		// Sharks are not on the list and pay.
		assertEquals(16 * 100, Offer.tax(SHARK, 100, 80_000));
	}

	@Test
	public void collectingPartOfAnOfferStillTradingIsNotCountedTwice()
	{
		open();
		ledger.observe(Store.BANK, items(WHIP, 1));
		ledger.offer(0, buy(SHARK, 1_000, 800, 400, 320_000, true));
		ledger.settle(T0 + 1000, prices, UTC);
		long worth = ledger.getTotal();

		// Collect the 400 bought so far into the inventory at the exchange.
		ledger.setAtExchange(true);
		ledger.observe(Store.INVENTORY, items(SHARK, 410));
		ledger.settle(T0 + 2000, prices, UTC);
		assertEquals(worth, ledger.getTotal());
		assertEquals(null, ledger.getStores().get(Store.GRAND_EXCHANGE).getItems().get(SHARK));

		// It finishes later and the rest is collected to the bank.
		ledger.setAtExchange(false);
		ledger.offer(0, buy(SHARK, 1_000, 800, 1_000, 800_000, false));
		ledger.settle(T0 + 3000, prices, UTC);
		assertEquals(worth, ledger.getTotal());
		ledger.offer(0, null);
		ledger.settle(T0 + 4000, prices, UTC);
		assertEquals(600, bank(SHARK));
		assertEquals(worth, ledger.getTotal());
	}

	@Test
	public void collectingOnlyTheItemsOfAFinishedOfferIsNotCountedTwice()
	{
		open();
		// Bid 1,000 each for 100 sharks; they all trade at 800, leaving 20k refund in the slot.
		ledger.observe(Store.BANK, items(WHIP, 1, COINS, 900_000));
		ledger.offer(0, buy(SHARK, 100, 1_000, 100, 80_000, false));
		ledger.settle(T0 + 1000, prices, UTC);
