		// Then the coins, which empties the slot.
		ledger.offer(0, null);
		ledger.observe(Store.INVENTORY, items(SHARK, 110, COINS, 20_000));
		ledger.settle(T0 + 3000, prices, UTC);
		assertEquals(worth, ledger.getTotal());
		assertEquals(0, bank(SHARK));
	}

	@Test
	public void collectingTheItemsBackFromACancelledSaleIsNotCountedTwice()
	{
		open();
		ledger.observe(Store.INVENTORY, items());
		ledger.offer(1, sell(SHARK, 10, 800, 4, 3_200, false));
		ledger.settle(T0 + 1000, prices, UTC);
		long worth = ledger.getTotal();

		ledger.setAtExchange(true);
		ledger.observe(Store.INVENTORY, items(SHARK, 6));
		ledger.settle(T0 + 2000, prices, UTC);
		assertEquals(worth, ledger.getTotal());
	}

	@Test
	public void collectingTheChangeFromABuyStillTradingIsNotCountedTwice()
	{
		open();
		// Bid 1,000 each for 1,000 sharks; 500 trade at 800, so 100k of change waits in the slot.
		ledger.observe(Store.BANK, items(WHIP, 1));
		ledger.offer(0, buy(SHARK, 1_000, 1_000, 500, 400_000, true));
		ledger.settle(T0 + 1000, prices, UTC);
		long worth = ledger.getTotal();

		ledger.setAtExchange(true);
		ledger.observe(Store.INVENTORY, items(SHARK, 10, COINS, 100_000));
		ledger.settle(T0 + 2000, prices, UTC);
		assertEquals(worth, ledger.getTotal());

		// It finishes at the same price and the rest is collected to the bank.
		ledger.setAtExchange(false);
		ledger.offer(0, buy(SHARK, 1_000, 1_000, 1_000, 800_000, false));
		ledger.settle(T0 + 3000, prices, UTC);
		assertEquals(worth, ledger.getTotal());
		ledger.offer(0, null);
		ledger.settle(T0 + 4000, prices, UTC);
		assertEquals(100_000, bank(COINS));
		assertEquals(worth, ledger.getTotal());
	}

	@Test
	public void hugeOffersDoNotOverflow()
	{
		Offer offer = buy(WHIP, 2_000, 2_000_000_000, 0, 0, true);
		assertEquals(4_000_000_000_000L, (long) offer.contents().get(COINS));
	}

	@Test
	public void aLostLootingBagTakesItsContents()
	{
		open();
		ledger.observe(Store.INVENTORY, items(SHARK, 10, Ledger.LOOTING_BAG, 1));
		ledger.observe(Store.LOOTING_BAG, items(WHIP, 1));
		ledger.settle(T0 + 1000, prices, UTC);
		ledger.observe(Store.BANK, items(COINS, 1_000_000));
		ledger.settle(T0 + 2000, prices, UTC);
		assertEquals(2_508_000, ledger.getTotal());

		// Died in the wilderness: the bag and the whip in it are gone.
		ledger.observe(Store.INVENTORY, items());
		ledger.settle(T0 + 3000, prices, UTC);
		assertTrue(ledger.getStores().get(Store.LOOTING_BAG).getItems().isEmpty());
		assertEquals(1_000_000, ledger.getTotal());
	}

	@Test
	public void aBankedLootingBagKeepsItsContents()
	{
		open();
		ledger.observe(Store.INVENTORY, items(Ledger.LOOTING_BAG, 1));
		ledger.observe(Store.LOOTING_BAG, items(SHARK, 5));
		ledger.settle(T0 + 1000, prices, UTC);
		ledger.observe(Store.INVENTORY, items());
		ledger.observe(Store.BANK, items(COINS, 1_000_000, WHIP, 1, Ledger.LOOTING_BAG, 1));
		ledger.settle(T0 + 2000, prices, UTC);
		assertEquals(5L, (long) ledger.getStores().get(Store.LOOTING_BAG).getItems().get(SHARK));
	}

	@Test
	public void aLedgerSavedBeforeSlotsWereKeptStillReads()
	{
		String old = "{\"stores\":{\"BANK\":{\"seen\":1,\"items\":{\"995\":1000}},"
			+ "\"GRAND_EXCHANGE\":{\"seen\":1,\"items\":{\"995\":500}}},\"prices\":{\"995\":1},"
			+ "\"history\":[{\"t\":1,\"v\":1500}],\"days\":[{\"date\":\"2026-10-01\",\"open\":1500,\"close\":1500,"
			+ "\"high\":1500,\"low\":1500,\"items\":{}}],\"total\":1500,\"since\":1}";
		Ledger read = new com.google.gson.GsonBuilder().create().fromJson(old, Ledger.class).repair();
		assertEquals(1500, read.getTotal());
		read.settle(T0, prices, UTC);
		assertEquals(1500, read.getTotal());
		assertEquals(500, read.value(Store.GRAND_EXCHANGE));
		// The first look at the slots replaces the old figure.
		read.offer(0, buy(SHARK, 1, 500, 0, 0, true));
		read.settle(T0 + 1000, prices, UTC);
		assertEquals(1500, read.getTotal());
	}

	@Test
	public void aPageReportsItsOwnDay()
	{
		open();
		ledger.observe(Store.INVENTORY, items(SHARK, 4));
		ledger.settle(T0 + 60_000, prices, UTC);
		Report page = Report.page(ledger.getDays().get(0), 5);
		assertEquals(2_508_000, page.getStart());
		assertEquals(-4_800, page.change());
		assertEquals(SHARK, page.getLosses().get(0).getItemId());
	}

	@Test
	public void survivesBeingSavedAndRead()
	{
		open();
		ledger.observe(Store.INVENTORY, items(SHARK, 4));
		ledger.settle(T0 + 60_000, prices, UTC);
		com.google.gson.Gson gson = new com.google.gson.GsonBuilder().create();
		Ledger read = gson.fromJson(gson.toJson(ledger), Ledger.class).repair();
		assertEquals(ledger.getTotal(), read.getTotal());
		assertEquals(4L, (long) read.getStores().get(Store.INVENTORY).getItems().get(SHARK));
		assertEquals(-4_800, read.getDays().get(0).getPlay());
		assertFalse(read.hasPending());
		read.observe(Store.INVENTORY, items(SHARK, 2));
		assertTrue(read.settle(T0 + 120_000, prices, UTC));
		assertEquals(-6_400, read.getDays().get(0).getPlay());
	}
}

package com.codex.ledger.core;

import java.util.Arrays;
import java.util.Collections;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** Round figures passed while the ledger watched, and the next one ahead. */
public class MilestonesTest
{
	private static final long DAY = 86_400_000L;

	private static Ledger.Point at(long day, long worth)
	{
		return new Ledger.Point(day * DAY, worth);
	}

	@Test
	public void theLadderIsTheOneHeadingForAimsAt()
	{
		assertEquals(1_000_000L, Milestones.above(0));
		assertEquals(100_000_000L, Milestones.above(73_000_000L));
		assertEquals(1_000_000_000L, Milestones.above(835_500_000L));
		assertEquals(Forecast.nextMark(1_000_000_000L), Milestones.above(1_000_000_000L));
		assertEquals(4_000_000_000L, Milestones.above(3_200_000_000L));
	}

	@Test
	public void marksEachFigureWhenFirstPassedNewestFirst()
	{
		Milestones m = Milestones.of(Arrays.asList(at(1, 180_000_000L), at(4, 260_000_000L), at(9, 240_000_000L), at(20, 510_000_000L)),
			700_000_000L, 30 * DAY);
		assertEquals(2, m.getPassed().size());
		assertEquals(500_000_000L, m.getPassed().get(0).getAmount());
		assertEquals(20 * DAY, m.getPassed().get(0).getAt());
		assertEquals(16 * DAY, m.getPassed().get(0).getAfter());
		assertEquals(250_000_000L, m.getPassed().get(1).getAmount());
		assertEquals(-1, m.getPassed().get(1).getAfter());
		assertEquals(750_000_000L, m.getNext());
		assertEquals(50_000_000L, m.getToGo());
		assertFalse(m.isRegain());
	}

	@Test
	public void aFigureHeldWhenTheLedgerBeganIsNoMilestone()
	{
		Milestones m = Milestones.of(Collections.singletonList(at(1, 600_000_000L)), 700_000_000L, 2 * DAY);
		assertTrue(m.getPassed().isEmpty());
		assertEquals(750_000_000L, m.getNext());
	}

	@Test
	public void oneBigDayCanPassSeveralFigures()
	{
		Milestones m = Milestones.of(Arrays.asList(at(1, 40_000_000L), at(2, 1_200_000_000L)), 1_200_000_000L, 3 * DAY);
		assertEquals(1_000_000_000L, m.getPassed().get(0).getAmount());
		assertEquals(0, m.getPassed().get(0).getAfter());
		assertEquals(Milestones.KEPT, m.getPassed().size());
	}

	@Test
	public void fallingBackUnderAFigureMakesItTheNextToRegain()
	{
		Milestones m = Milestones.of(Arrays.asList(at(1, 90_000_000L), at(2, 110_000_000L)), 95_000_000L, 3 * DAY);
		assertEquals(100_000_000L, m.getNext());
		assertTrue(m.isRegain());
		assertEquals(1, m.getPassed().size());
	}

	@Test
	public void anEmptyHistoryStillNamesTheNextFigure()
	{
		Milestones m = Milestones.of(Collections.emptyList(), 0, DAY);
		assertTrue(m.getPassed().isEmpty());
		assertEquals(1_000_000L, m.getNext());
		assertEquals(1_000_000L, m.getToGo());
	}

	@Test
	public void aPlaceSeenForTheFirstTimePassesNoFigure()
	{
		// 90M in the bank, then a seed vault opened for the first time holding 20M: opening balance, as the
		// day book counts it, so the worth did not pass 100M while the ledger watched.
		java.util.Map<Integer, Long> price = new java.util.HashMap<>();
		price.put(995, 1L);
		price.put(5295, 20_000L);
		Prices prices = id -> price.getOrDefault(id, 0L);
		java.time.ZoneId utc = java.time.ZoneOffset.UTC;
		Ledger ledger = new Ledger();
		ledger.observe(Store.BANK, Collections.singletonMap(995, 90_000_000L));
		ledger.settle(DAY + DAY / 2, prices, utc);
		ledger.observe(Store.SEED_VAULT, Collections.singletonMap(5295, 1_000L));
		ledger.settle(DAY + DAY / 2 + 3 * 3_600_000L, prices, utc);
		assertEquals(110_000_000L, ledger.getTotal());
		Milestones m = Milestones.of(ledger.getHistory(), ledger.getTotal(), DAY + DAY / 2 + 4 * 3_600_000L);
		assertTrue(m.getPassed().isEmpty());
		assertEquals(250_000_000L, m.getNext());
		assertFalse(m.isRegain());
	}
}

package com.codex.ledger.core;

import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class MonthsTest
{
	private static final ZoneId UTC = ZoneOffset.UTC;
	private static final long DAY = 86_400_000L;

	/** Coins in the bank each day from 28 September, one settle at noon. */
	private static Ledger ledger(long... coins)
	{
		long start = LocalDate.of(2026, 9, 28).atStartOfDay(UTC).toInstant().toEpochMilli() + DAY / 2;
		Ledger ledger = new Ledger();
		for (int d = 0; d < coins.length; d++)
		{
			Map<Integer, Long> bank = new HashMap<>();
			bank.put(995, coins[d]);
			ledger.observe(Store.BANK, bank);
			ledger.settle(start + d * DAY, id -> 1L, UTC);
		}
		return ledger;
	}

	@Test
	public void eachMonthIsItsOwnStatementNewestFirst()
	{
		// 28, 29, 30 September, then 1 to 4 October.
		Ledger ledger = ledger(100_000_000L, 110_000_000L, 105_000_000L, 125_000_000L, 125_000_000L, 120_000_000L, 160_000_000L);
		List<Months.Month> months = Months.of(ledger.getDays(), LocalDate.of(2026, 10, 4), 6);
		assertEquals(2, months.size());

		Months.Month october = months.get(0);
		assertEquals("2026-10", october.getMonth().toString());
		assertTrue(october.isCurrent());
		assertEquals(4, october.getPages());
		// From September's close of 105M to 160M now.
		assertEquals(55_000_000L, october.change());
		assertEquals(160_000_000L, october.getClose());
		assertEquals(LocalDate.of(2026, 10, 4), october.getBest());
		assertEquals(40_000_000L, october.getBestChange());

		Months.Month september = months.get(1);
		assertFalse(september.isCurrent());
		assertEquals(3, september.getPages());
		// The first page opens on the bank as first seen, so September made 5M.
		assertEquals(5_000_000L, september.change());
		assertEquals(105_000_000L, september.getClose());
		assertEquals(LocalDate.of(2026, 9, 29), september.getBest());
	}

	@Test
	public void theMonthsAddUpToTheDayBook()
	{
		Ledger ledger = ledger(100_000_000L, 90_000_000L, 95_000_000L, 70_000_000L);
		long sum = 0;
		for (Months.Month m : Months.of(ledger.getDays(), LocalDate.of(2026, 10, 1), 6))
		{
			sum += m.change();
		}
		long pages = 0;
		for (Day d : ledger.getDays())
		{
			pages += d.change();
		}
		assertEquals(pages, sum);
	}

	@Test
	public void aMonthWithNoGainHasNoBestDay()
	{
		Ledger ledger = ledger(100_000_000L, 90_000_000L, 80_000_000L);
		Months.Month september = Months.of(ledger.getDays(), LocalDate.of(2026, 9, 30), 6).get(0);
		assertNull(september.getBest());
		assertEquals(-20_000_000L, september.change());
	}

	@Test
	public void outOfOrderPagesAndOddDatesStillMakeOneMonthEach()
	{
		Ledger ledger = ledger(100_000_000L, 110_000_000L, 120_000_000L, 130_000_000L);
		List<Day> days = ledger.getDays();
		List<Day> shuffled = Arrays.asList(days.get(3), days.get(0), days.get(2), new Day("not a date", 5), days.get(1));
		List<Months.Month> months = Months.of(shuffled, LocalDate.of(2026, 10, 1), 6);
		assertEquals(2, months.size());
		assertEquals(130_000_000L, months.get(0).getClose());
		// The last page of September closes it, whatever order the pages came in.
		assertEquals(120_000_000L, months.get(1).getClose());
		assertEquals(1, Months.of(shuffled, LocalDate.of(2026, 10, 1), 1).size());
		assertTrue(Months.of(Collections.emptyList(), LocalDate.of(2026, 10, 1), 6).isEmpty());
		assertTrue(Months.of(null, LocalDate.of(2026, 10, 1), 6).isEmpty());
	}

	@Test
	public void onlyTheDayBooksOldestMonthSaysWhereItsPagesBegin()
	{
		// 28 September to 4 October: September is held from the 28th only, October whole.
		Ledger ledger = ledger(100_000_000L, 110_000_000L, 105_000_000L, 125_000_000L, 125_000_000L, 120_000_000L, 160_000_000L);
		List<Months.Month> months = Months.of(ledger.getDays(), LocalDate.of(2026, 10, 4), 6);
		assertNull(months.get(0).getFrom());
		assertEquals(LocalDate.of(2026, 9, 28), months.get(1).getFrom());
	}

	@Test
	public void aDayBookAcrossTheNewYearKeepsItsMonthsInOrder()
	{
		Day december = new Day("2025-12-31", 100);
		Day january = new Day("2026-01-01", 100);
		Day lastOctober = new Day("2025-10-01", 100);
		List<Months.Month> months = Months.of(Arrays.asList(january, lastOctober, december), LocalDate.of(2026, 1, 1), 6);
		assertEquals(3, months.size());
		assertEquals("2026-01", months.get(0).getMonth().toString());
		assertEquals("2025-12", months.get(1).getMonth().toString());
		assertEquals("2025-10", months.get(2).getMonth().toString());
		// The oldest begins on its 1st, so it is held whole; a month a year back is not today's.
		assertNull(months.get(2).getFrom());
		assertFalse(Months.of(Arrays.asList(lastOctober), LocalDate.of(2026, 10, 1), 6).get(0).isCurrent());
	}
}

