package com.codex.ledger.core;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.time.ZoneOffset;
import java.util.HashMap;
import java.util.Map;
import java.util.Random;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * The ledger is one value in the RuneLite profile, so a busy account must not let it grow without
 * end. This drives a heavy flipper and PvMer through 130 days: a 1,000-item bank, a churning
 * inventory and a trade every few minutes across thousands of different items.
 */
public class SaveSizeTest
{
	private static final Gson GSON = new Gson();
	private static String busyYear;

	@BeforeClass
	public static void drive()
	{
		busyYear = GSON.toJson(busy(130));
	}

	private static Ledger busyYear()
	{
		return GSON.fromJson(busyYear, Ledger.class).repair();
	}

	@Test
	public void aBusyYearStaysBounded()
	{
		Ledger ledger = busyYear();
		int natural = GSON.toJson(ledger).length();
		System.out.println("Busy ledger saves " + natural + " characters");
		assertTrue("saved " + natural, natural < 260_000);
		assertEquals(Ledger.DAYS, ledger.getDays().size());
		// Old pages keep their totals and only their biggest movers.
		assertTrue(ledger.getDays().get(0).getItems().size() <= Day.OLD_ITEMS);
		assertTrue(ledger.getDays().get(0).getDeals().isEmpty());
	}

	@Test
	public void fittingTrimsDetailButKeepsTheWorthOthersRead()
	{
		Ledger ledger = busyYear();
		long total = ledger.getTotal();
		int points = ledger.getHistory().size();
		int fitted = ledger.fit(120_000, GSON::toJson, null).length();
		assertTrue("fitted " + fitted, fitted <= 120_000);
		assertEquals(fitted, GSON.toJson(ledger).length());
		JsonObject saved = new JsonParser().parse(GSON.toJson(ledger)).getAsJsonObject();
		assertEquals(total, saved.get("total").getAsLong());
		assertTrue(saved.getAsJsonArray("history").size() > 0);
		assertTrue(ledger.getHistory().size() <= points);
		// Day totals survive trimming.
		Day oldest = ledger.getDays().get(0);
		assertTrue(oldest.getDate() != null);

		// A ledger already inside its budget is left alone.
		Ledger small = busy(3);
		String before = GSON.toJson(small);
		small.fit(1_000_000, GSON::toJson, null);
		assertEquals(before, GSON.toJson(small));
	}

	@Test
	public void aLedgerThatCannotFitIsNotWornAwaySaveAfterSave()
	{
		// Holdings alone over the budget: every save fits again, and each pass used to halve the worth
		// history and drop every page older than a month, until the curve was a handful of points.
		Ledger ledger = busyYear();
		int points = ledger.getHistory().size();
		long newest = ledger.getHistory().get(points - 1).getTime();
		for (int save = 0; save < 12; save++)
		{
			ledger.fit(1, GSON::toJson, null);
		}
		assertEquals("every day's totals are kept", Ledger.DAYS, ledger.getDays().size());
		assertEquals(Math.min(points, Ledger.HISTORY_FLOOR), ledger.getHistory().size());
		assertEquals("the newest point is kept", newest, ledger.getHistory().get(ledger.getHistory().size() - 1).getTime());
	}

	@Test
	public void savingAHugeLedgerWritesItOutOnceASave()
	{
		// A 9,000-kind bank on top of a busy year: the holdings alone pass the budget, so trimming can
		// never bring it under. Each save used to write it out three times (up to seven when a trim
		// step found anything), on the client thread, every save.
		Ledger ledger = busyYear();
		Map<Integer, Long> bank = new HashMap<>();
		for (int i = 0; i < 9_000; i++)
		{
			bank.put(30_000 + i, 1L + i);
		}
		ledger.observe(Store.BANK, bank);
		Prices prices = id -> 1_000L + id;
		long t = ledger.getHistory().get(ledger.getHistory().size() - 1).getTime() + 60_000L;
		ledger.settle(t, prices, ZoneOffset.UTC);
		Saver saver = new Saver(200_000);
		int saves = 40;
		long started = System.nanoTime();
		String last = null;
		for (int save = 0; save < saves; save++)
		{
			// A save every five minutes of play, with the worth moving between them.
			t += 5 * 60_000L;
			ledger.settle(t, id -> 1_000L + id + (id % 7), ZoneOffset.UTC);
			last = saver.save(ledger, GSON::toJson);
		}
		long ms = (System.nanoTime() - started) / 1_000_000;
		System.out.println("Huge ledger: " + saves + " saves wrote it out " + saver.getWrites() + " times in " + ms + " ms, "
			+ last.length() + " characters");
		assertTrue("writes " + saver.getWrites(), saver.getWrites() <= saves + 2 * 6);
		assertEquals(GSON.toJson(ledger), last);
		assertEquals("every day's totals are kept", Ledger.DAYS, ledger.getDays().size());
	}

	@Test
	public void aLedgerPastItsBudgetIsTrimmedWithRoomToGrow()
	{
		Ledger ledger = busyYear();
		int natural = GSON.toJson(ledger).length();
		Saver saver = new Saver(natural - 1_000);
		String saved = saver.save(ledger, GSON::toJson);
		assertTrue(saved.length() <= (natural - 1_000) * Saver.ROOM);
		assertEquals(GSON.toJson(ledger), saved);
		int writes = saver.getWrites();
		// The next save has room: it is written out once and not trimmed.
		saver.save(ledger, GSON::toJson);
		assertEquals(writes + 1, saver.getWrites());

		// A ledger inside its budget is written once and left alone.
		Ledger small = busy(3);
		String before = GSON.toJson(small);
		Saver roomy = new Saver(1_000_000);
		assertEquals(before, roomy.save(small, GSON::toJson));
		assertEquals(1, roomy.getWrites());
	}

	static Ledger busy(int days)
	{
		Random r = new Random(7);
		Prices prices = id -> 1_000L + id;
		Ledger ledger = new Ledger();
		long t = 1_790_000_000_000L;
		Map<Integer, Long> bank = new HashMap<>();
		for (int i = 0; i < 1_000; i++)
		{
			bank.put(2_000 + i * 3, 1L + r.nextInt(5_000));
		}
		ledger.observe(Store.BANK, bank);
		ledger.settle(t, prices, ZoneOffset.UTC);
		for (int day = 0; day < days; day++)
		{
			for (int tick = 0; tick < 48; tick++)
			{
				t += 20 * 60_000L;
				Map<Integer, Long> inventory = new HashMap<>();
				for (int k = 0; k < 28; k++)
				{
					inventory.put(10_000 + r.nextInt(2_000), 1L + r.nextInt(50));
				}
				ledger.observe(Store.INVENTORY, inventory);
				if (tick % 2 == 0)
				{
					int slot = r.nextInt(8);
					int item = 20_000 + r.nextInt(5_000);
					boolean buy = r.nextBoolean();
					long price = 1_000L + item;
					ledger.offer(slot, new Offer(item, buy, 100, price, 0, 0, true));
					ledger.settle(t, prices, ZoneOffset.UTC);
					t += 600;
					ledger.offer(slot, new Offer(item, buy, 100, price, 100, 100 * price, false));
					ledger.settle(t, prices, ZoneOffset.UTC);
					t += 600;
					ledger.offer(slot, null);
				}
				ledger.settle(t, prices, ZoneOffset.UTC);
			}
			// The bank is opened once a day, replacing the guess of what was collected to it.
			ledger.observe(Store.BANK, bank);
			ledger.settle(t, prices, ZoneOffset.UTC);
			t += 8 * 3_600_000L;
		}
		return ledger;
	}
}

package com.codex.ledger.core;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.time.ZoneOffset;
import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

/**
 * The saved {@code codexledger/ledger} byte for byte, written by the plugin's own Saver, for the
 * plugins that read it (Gear Roadmap, Annals, Session Chronicle, Guardian) to copy as their test
 * fixtures. {@code ledger-seen.json} is an account whose bank has been seen; {@code
 * ledger-unseen.json} one that has only shown its inventory, so "since" is still 0. If either test
 * fails the saved shape has changed: every reader's copy must be checked before the files are.
 */
public class SavedFixtureTest
{
	private static final Gson GSON = new GsonBuilder().create();
	private static final long T0 = 1_790_000_000_000L;

	@Test
	public void aSeenLedgerSavesExactlyAsPinned() throws Exception
	{
		Prices prices = prices(995, 1L, 4151, 1_500_000L);
		Ledger ledger = new Ledger();
		ledger.observe(Store.BANK, items(995, 1_000_000L, 4151, 1L));
		ledger.settle(T0, prices, ZoneOffset.UTC);
		ledger.observe(Store.BANK, items(995, 2_000_000L, 4151, 1L));
		ledger.settle(T0 + 3_600_000L, prices, ZoneOffset.UTC);
		assertEquals(fixture("ledger-seen.json"), new Saver(200_000).save(ledger, GSON::toJson));
	}

	@Test
	public void anUnseenLedgerSavesExactlyAsPinned() throws Exception
	{
		Ledger ledger = new Ledger();
		ledger.observe(Store.INVENTORY, items(995, 25_000L));
		ledger.settle(T0, prices(995, 1L), ZoneOffset.UTC);
		assertEquals(fixture("ledger-unseen.json"), new Saver(200_000).save(ledger, GSON::toJson));
	}

	private static String fixture(String name) throws Exception
	{
		try (InputStream in = SavedFixtureTest.class.getResourceAsStream(name))
		{
			return new String(in.readAllBytes(), StandardCharsets.UTF_8).trim();
		}
	}

	private static Prices prices(long... pairs)
	{
		Map<Integer, Long> m = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put((int) pairs[i], pairs[i + 1]);
		}
		return id -> m.getOrDefault(id, 0L);
	}

	private static Map<Integer, Long> items(long... pairs)
	{
		Map<Integer, Long> m = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put((int) pairs[i], pairs[i + 1]);
		}
		return m;
	}
}

package com.codex.ledger.core;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.time.ZoneOffset;
import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Other Codex plugins (Annals for its year's worth, Gear Roadmap for its savings pace, Session
 * Chronicle for a session's net worth) read the saved ledger, read only: the top level "total",
 * "since" (when the bank was first seen, 0 before) and "history" as a list of {"t": epoch ms, "v":
 * worth}, oldest first. Renaming or reshaping either breaks them without a compile error, so the
 * shape is pinned here.
 */
public class SavedShapeTest
{
	@Test
	public void theWorthOtherPluginsReadKeepsItsShape()
	{
		Map<Integer, Long> price = new HashMap<>();
		price.put(995, 1L);
		price.put(4151, 1_500_000L);
		Prices prices = id -> price.getOrDefault(id, 0L);
		Ledger ledger = new Ledger();
		long t0 = 1_790_000_000_000L;
		ledger.observe(Store.BANK, items(995, 1_000_000L, 4151, 1L));
		ledger.settle(t0, prices, ZoneOffset.UTC);
		ledger.observe(Store.BANK, items(995, 2_000_000L, 4151, 1L));
		ledger.settle(t0 + 3_600_000L, prices, ZoneOffset.UTC);

		Gson gson = new GsonBuilder().create();
		JsonObject saved = new JsonParser().parse(gson.toJson(ledger)).getAsJsonObject();
		assertEquals(3_500_000L, saved.get("total").getAsLong());
		// Session Chronicle takes a worth as whole only once "since" says the bank was seen.
		assertEquals(t0, saved.get("since").getAsLong());
		JsonArray history = saved.getAsJsonArray("history");
		assertTrue(history.size() >= 2);
		long last = Long.MIN_VALUE;
		for (int i = 0; i < history.size(); i++)
		{
			JsonObject p = history.get(i).getAsJsonObject();
			assertTrue(p.get("t").getAsLong() >= last);
			last = p.get("t").getAsLong();
		}
		JsonObject newest = history.get(history.size() - 1).getAsJsonObject();
		assertEquals(t0 + 3_600_000L, newest.get("t").getAsLong());
		assertEquals(3_500_000L, newest.get("v").getAsLong());
	}

	private static Map<Integer, Long> items(long... pairs)
	{
		Map<Integer, Long> m = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put((int) pairs[i], pairs[i + 1]);
		}
		return m;
	}
}

package com.codex.ledger.core;

import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class TradesTest
{
	private static final ZoneId UTC = ZoneOffset.UTC;
	private static final long DAY = 86_400_000L;
	/** Noon on 1 October 2026, UTC. */
	private static final long T0 = LocalDate.of(2026, 10, 1).atStartOfDay(UTC).toInstant().toEpochMilli() + DAY / 2;
	private static final LocalDate D0 = LocalDate.of(2026, 10, 1);
	private static final int COINS = 995;
	private static final int SHARK = 385;
	private static final int WHIP = 4151;

	private final Map<Integer, Long> price = new HashMap<>();
	private final Prices prices = id -> price.getOrDefault(id, 0L);
	private Ledger ledger;
	private long now = T0;

	@Before
	public void setUp()
	{
		price.put(COINS, 1L);
		price.put(SHARK, 800L);
		price.put(WHIP, 1_500_000L);
		ledger = new Ledger();
		ledger.observe(Store.INVENTORY, items(SHARK, 10));
		ledger.observe(Store.BANK, items(COINS, 1_000_000, WHIP, 1));
		ledger.offer(7, null);
		settle();
		// The slots seen whole once the ledger is open, as the plugin does after login.
		ledger.offer(7, null);
		settle();
	}

	private static Map<Integer, Long> items(long... pairs)
	{
		Map<Integer, Long> m = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put((int) pairs[i], pairs[i + 1]);
		}
		return m;
	}

	private void settle()
	{
		now += 1_000;
		ledger.settle(now, prices, UTC);
	}

	private Day today()
	{
		return ledger.getDays().get(ledger.getDays().size() - 1);
	}

	private long channels(Day day)
	{
		long sum = 0;
		for (Channel c : Channel.values())
		{
			sum += day.channel(c);
		}
		return sum;
	}

	/** Buys 1,000 sharks at 700 each with bank coins and collects them into the inventory. */
	private void buySharks()
	{
		ledger.observe(Store.BANK, items(COINS, 300_000, WHIP, 1));
		ledger.offer(0, new Offer(SHARK, true, 1_000, 700, 0, 0, true));
		settle();
		ledger.offer(0, new Offer(SHARK, true, 1_000, 700, 1_000, 700_000, false));
		settle();
		ledger.offer(0, null);
		ledger.observe(Store.INVENTORY, items(SHARK, 1_010));
		settle();
	}

	@Test
	public void aFlipBooksItsProfitAfterTax()
	{
		buySharks();
		Position held = ledger.getBook().get(SHARK);
		assertEquals(1_000, held.getHeld());
		assertEquals(700_000, held.getCost());

		// Sold for 900 each: 18 tax an item, so 882k for what cost 700k.
		ledger.observe(Store.INVENTORY, items(SHARK, 10));
		ledger.offer(1, new Offer(SHARK, false, 1_000, 900, 0, 0, true));
		settle();
		ledger.offer(1, new Offer(SHARK, false, 1_000, 900, 600, 540_000, true));
		settle();
		ledger.offer(1, new Offer(SHARK, false, 1_000, 900, 1_000, 900_000, false));
		settle();

		Deal day = today().getTrades();
		assertEquals(1_000, day.getBought());
		assertEquals(700_000, day.getBuyCoins());
		assertEquals(1_000, day.getSold());
		assertEquals(882_000, day.getSaleCoins());
		assertEquals(18_000, day.getTax());
		assertEquals(182_000, day.getProfit());
		assertEquals(0, day.getUnmatched());
		assertEquals(0, ledger.getBook().get(SHARK).getHeld());
		assertEquals(182_000, today().getDeals().get(SHARK).getProfit());
		assertEquals(0.26, day.roi(), 0.001);

		// The price never moved, so what trading made is all the play there was.
		assertEquals(182_000, today().channel(Channel.EXCHANGE));
		assertEquals(today().getPlay(), channels(today()));
		// And the day book's lists leave the trading to the exchange.
		Report report = Report.of(ledger, 1, D0, 10);
		assertTrue(report.getGains().isEmpty());
		assertTrue(report.getLosses().isEmpty());
		assertEquals(182_000, report.channel(Channel.EXCHANGE));
		assertEquals(0, report.unexplained());
	}

	@Test
	public void sellingWhatWasNeverBoughtMakesNoProfit()
	{
		ledger.observe(Store.BANK, items(COINS, 1_000_000));
		ledger.offer(2, new Offer(WHIP, false, 1, 1_500_000, 0, 0, true));
		settle();
		ledger.offer(2, new Offer(WHIP, false, 1, 1_500_000, 1, 1_500_000, false));
		settle();
		Deal day = today().getTrades();
		assertEquals(1, day.getSold());
		assertEquals(1, day.getUnmatched());
		assertEquals(1_470_000, day.getUnmatchedCoins());
		assertEquals(0, day.getProfit());
		assertEquals(0, day.roi(), 0);
		// Selling at the market price costs only the tax.
		assertEquals(-30_000, today().channel(Channel.EXCHANGE));
	}

	@Test
	public void boughtItemsUsedUpLeaveThePosition()
	{
		buySharks();
		ledger.observe(Store.INVENTORY, items(SHARK, 410));
		settle();
		Position p = ledger.getBook().get(SHARK);
		assertEquals(410, p.getHeld());
		assertEquals(287_000, p.getCost());
		assertEquals(-600 * 800, today().channel(Channel.USED));
	}

	@Test
	public void anOfferPlacedWhileAwayCountsWhatItTraded()
	{
		// Placed on the mobile app and half filled before the client saw it.
		ledger.observe(Store.BANK, items(COINS, 300_000, WHIP, 1));
		ledger.offer(3, new Offer(SHARK, true, 1_000, 700, 500, 350_000, true));
		settle();
		assertEquals(500, ledger.getBook().get(SHARK).getHeld());
		assertEquals(500, today().getTrades().getBought());
	}

	@Test
	public void offersAtTheVeryFirstLookAreNotTrades()
	{
		Ledger fresh = new Ledger();
		fresh.observe(Store.BANK, items(COINS, 650_000));
		fresh.offer(0, new Offer(SHARK, true, 1_000, 700, 500, 350_000, true));
		fresh.settle(T0, prices, UTC);
		fresh.offer(0, new Offer(SHARK, true, 1_000, 700, 500, 350_000, true));
		fresh.settle(T0 + 1_000, prices, UTC);
		assertTrue(fresh.getBook().isEmpty());
		// It goes on filling: that part is a trade.
		fresh.offer(0, new Offer(SHARK, true, 1_000, 700, 800, 560_000, true));
		fresh.settle(T0 + 2_000, prices, UTC);
		assertEquals(300, fresh.getBook().get(SHARK).getHeld());
		assertEquals(210_000, fresh.getBook().get(SHARK).getCost());
	}

	@Test
	public void deathLossesAreSetAgainstWhatComesBack()
	{
		ledger.observe(Store.EQUIPMENT, items());
		settle();
		ledger.observe(Store.EQUIPMENT, items(WHIP, 1));
		ledger.observe(Store.BANK, items(COINS, 1_000_000));
		settle();
		assertEquals(0, today().getPlay());
		ledger.died(now);
		ledger.observe(Store.INVENTORY, items());
		ledger.observe(Store.EQUIPMENT, items());
		settle();
		assertEquals(-1_508_000, today().channel(Channel.DEATHS));

		// Back from the gravestone: the whip and sharks return, and five more sharks are loot.
		now += 300_000;
		ledger.observe(Store.INVENTORY, items(SHARK, 15));
		ledger.observe(Store.EQUIPMENT, items(WHIP, 1));
		settle();
		assertEquals(0, today().channel(Channel.DEATHS));
		assertEquals(4_000, today().channel(Channel.LOOT));
		// Eating them later is supplies, not the death.
		ledger.observe(Store.INVENTORY, items(SHARK, 12));
		settle();
		assertEquals(-2_400, today().channel(Channel.USED));
		assertEquals(today().getPlay(), channels(today()));

		// Long after, sharks gained are loot again.
		ledger.died(now);
		ledger.observe(Store.INVENTORY, items());
		settle();
		now += Ledger.REGAIN_MS + 1;
		ledger.observe(Store.INVENTORY, items(SHARK, 12));
		settle();
		assertEquals(4_000 + 12 * 800, today().channel(Channel.LOOT));
	}

	@Test
	public void aSafeDeathEndsWithWhatItTookAndDoesNotTakeTheSuppliesAfter()
	{
		ledger.died(now);
		ledger.observe(Store.INVENTORY, items(SHARK, 4));
		settle();
		assertEquals(-4_800, today().channel(Channel.DEATHS));
		// Eating a shark a moment later is supplies.
		ledger.observe(Store.INVENTORY, items(SHARK, 3));
		settle();
		assertEquals(-800, today().channel(Channel.USED));
		assertEquals(-4_800, today().channel(Channel.DEATHS));
	}

	@Test
	public void pagesBeyondAMonthKeepOnlyTheirTradeTotals()
	{
		buySharks();
		for (int d = 1; d <= Ledger.DEAL_DAYS; d++)
		{
			now = T0 + d * DAY;
			settle();
		}
		Day first = ledger.getDays().get(0);
		assertTrue(first.getDeals().isEmpty());
		assertEquals(700_000, first.getTrades().getBuyCoins());
		assertEquals(700_000, Trades.of(ledger, 0, D0.plusDays(Ledger.DEAL_DAYS)).getTotal().getBuyCoins());
	}

	@Test
	public void coinsComingAndGoingAreTheirOwnChannels()
	{
		// A shop: coins out, sharks in; then an alch: a whip out, coins in.
		ledger.observe(Store.INVENTORY, items(SHARK, 20, COINS, 1_000));
		ledger.observe(Store.BANK, items(COINS, 990_000, WHIP, 1));
		settle();
		assertEquals(-9_000, today().channel(Channel.COINS_OUT));
		assertEquals(8_000, today().channel(Channel.LOOT));
		ledger.observe(Store.INVENTORY, items(SHARK, 20, COINS, 73_000));
		ledger.observe(Store.BANK, items(COINS, 990_000));
		settle();
		assertEquals(72_000, today().channel(Channel.COINS_IN));
		assertEquals(-1_500_000, today().channel(Channel.USED));
		assertEquals(today().getPlay(), channels(today()));
	}

	@Test
	public void spansAndOpenPositions()
	{
		buySharks();
		// The next day the price rises to 1,000: 980 after tax on 1,000 that cost 700.
		now += DAY;
		price.put(SHARK, 1_000L);
		settle();
		Trades today = Trades.of(ledger, 1, D0.plusDays(1));
		assertEquals(0, today.getTotal().volume());
		Trades week = Trades.of(ledger, 7, D0.plusDays(1));
		assertEquals(700_000, week.getTotal().getBuyCoins());
		assertEquals(D0, week.getFrom());
		Trades all = Trades.of(ledger, 0, D0.plusDays(1));
		assertEquals(1, all.getItems().size());
		assertNull(all.getFrom());
		assertEquals(1, all.getOpen().size());
		Trades.Open open = all.getOpen().get(0);
		assertEquals(1_000, open.getQuantity());
		assertEquals(700_000, open.getCost());
		assertEquals(980_000, open.getWorth());
		assertEquals(280_000, all.openGain());
	}

	@Test
	public void aClosedPageKeepsItsTradeTotalsWhole()
	{
		for (int i = 0; i < Day.KEPT_DEALS + 6; i++)
		{
			int item = 2_000 + i;
			price.put(item, 100L);
			ledger.offer(4, new Offer(item, true, 10, 100, 10, 1_000, false));
			settle();
			ledger.offer(4, null);
			settle();
		}
		now += DAY;
		settle();
		Day closed = ledger.getDays().get(0);
		assertEquals(Day.KEPT_DEALS, closed.getDeals().size());
		assertEquals((Day.KEPT_DEALS + 6) * 1_000L, closed.getTrades().getBuyCoins());
	}

	@Test
	public void tradesSurviveBeingSavedAndRead()
	{
		buySharks();
		ledger.died(now);
		com.google.gson.Gson gson = new com.google.gson.GsonBuilder().create();
		Ledger read = gson.fromJson(gson.toJson(ledger), Ledger.class).repair();
		assertEquals(1_000, read.getBook().get(SHARK).getHeld());
		assertEquals(700_000, read.getDays().get(0).getTrades().getBuyCoins());
		assertEquals(100_000, read.getDays().get(0).channel(Channel.EXCHANGE));
		// A page written before any of this was kept reads as nothing traded.
		String old = "{\"date\":\"2026-10-01\",\"open\":1,\"close\":1,\"high\":1,\"low\":1,\"items\":{}}";
		Day page = gson.fromJson(old, Day.class);
		assertEquals(0, page.getTrades().volume());
		assertTrue(page.getDeals().isEmpty());
	}

	@Test
	public void forecastsTheGoalAtTheMonthsPace()
	{
		// A million a day for ten days.
		for (int i = 1; i < 10; i++)
		{
			now = T0 + i * DAY;
			ledger.observe(Store.BANK, items(COINS, 1_000_000 + i * 1_000_000L, WHIP, 1));
			settle();
		}
		LocalDate today = D0.plusDays(9);
		Forecast f = Forecast.of(ledger, today, 20_000_000L);
		assertEquals(10, f.getDays());
		assertEquals(900_000, f.getPerDay(), 1);
		// 8.49M to go at 900k a day: ten more days.
		assertEquals(today.plusDays(10), f.getEta());
		assertTrue(f.isGoalSet());

		Forecast round = Forecast.of(ledger, today, 0);
		assertEquals(25_000_000L, round.getTarget());
		assertEquals(3_000_000_000L, Forecast.nextMark(2_100_000_000L));

		// Falling worth never gets there.
		ledger.observe(Store.BANK, items(WHIP, 1));
		settle();
		assertNull(Forecast.of(ledger, today, 20_000_000L).getEta());
	}

	@Test
	public void tooEarlyForAPace()
	{
		Forecast f = Forecast.of(ledger, D0, 0);
		assertEquals(1, f.getDays());
		assertNull(f.getEta());
		assertEquals(5_000_000L, f.getTarget());
	}
}

package com.codex.ledger.ui;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CardPicturesTest
{
	/** Pictures that arrive only when told to, the way RuneLite's item pictures load. */
	private static final class Late implements ItemIcons
	{
		final Map<Integer, Runnable> callbacks = new HashMap<>();
		final Set<BufferedImage> in = new HashSet<>();
		int asked;

		@Override
		public BufferedImage icon(int itemId, Runnable onLoaded)
		{
			asked++;
			BufferedImage image = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
			callbacks.put(itemId, () ->
			{
				in.add(image);
				onLoaded.run();
			});
			return image;
		}

		@Override
		public boolean hasArrived(BufferedImage image)
		{
			return in.contains(image);
		}
	}

	/** A card that is "complete" only when every picture it drew had arrived. */
	private static BufferedImage card(ItemIcons icons, Late late, List<Boolean> complete)
	{
		boolean all = true;
		for (int id : new int[]{995, 4151})
		{
			all &= late.hasArrived(icons.icon(id, null));
		}
		complete.add(all);
		return new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
	}

	@Test
	public void aCardWaitsForItsPicturesThenDrawsWithThem()
	{
		Late late = new Late();
		List<Boolean> drawn = new ArrayList<>();
		List<BufferedImage> delivered = new ArrayList<>();
		List<Runnable> waits = new ArrayList<>();
		int[] ended = {0};
		CardPictures.draw(late, icons -> card(icons, late, drawn), delivered::add, Runnable::run, waits::add, () -> ended[0]++);
		// Drawn once to learn what it needs, and nothing handed over yet.
		assertEquals(1, drawn.size());
		assertTrue(delivered.isEmpty());
		assertEquals(0, ended[0]);
		late.callbacks.get(995).run();
		assertTrue(delivered.isEmpty());
		late.callbacks.get(4151).run();
		// The last picture in draws it again, complete, with the same pictures (none asked for twice).
		assertEquals(1, delivered.size());
		assertEquals(Boolean.TRUE, drawn.get(1));
		assertEquals(2, late.asked);
		// The wait running out afterwards hands nothing over a second time, and the card ended once.
		waits.get(0).run();
		assertEquals(1, delivered.size());
		assertEquals(1, ended[0]);
	}

	@Test
	public void aPictureThatNeverComesHoldsTheCardOnlyUntilTheWaitRunsOut()
	{
		Late late = new Late();
		List<Boolean> drawn = new ArrayList<>();
		List<BufferedImage> delivered = new ArrayList<>();
		List<Runnable> waits = new ArrayList<>();
		int[] ended = {0};
		CardPictures.draw(late, icons -> card(icons, late, drawn), delivered::add, Runnable::run, waits::add, () -> ended[0]++);
		late.callbacks.get(995).run();
		waits.get(0).run();
		assertEquals(1, delivered.size());
		// A straggler after that is ignored.
		late.callbacks.get(4151).run();
		assertEquals(1, delivered.size());
	}

	@Test
	public void aCardThatFailsToDrawStillLetsTheNextPressThrough()
	{
		Late late = new Late();
		int[] ended = {0};
		List<Runnable> waits = new ArrayList<>();
		int[] calls = {0};
		CardPictures.draw(late, icons ->
		{
			icons.icon(995, null);
			if (calls[0]++ > 0)
			{
				throw new IllegalStateException("broken");
			}
			return null;
		}, c -> { }, Runnable::run, waits::add, () -> ended[0]++);
		try
		{
			late.callbacks.get(995).run();
		}
		catch (IllegalStateException expected)
		{
			// The failure reaches the caller as before.
		}
		assertEquals(1, ended[0]);
	}

	@Test
	public void picturesAlreadyInAreDrawnAtOnce()
	{
		List<BufferedImage> delivered = new ArrayList<>();
		int[] ended = {0};
		BufferedImage card = new BufferedImage(2, 2, BufferedImage.TYPE_INT_ARGB);
		ItemIcons ready = (id, cb) -> new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
		CardPictures.draw(ready, icons ->
		{
			icons.icon(995, null);
			return card;
		}, delivered::add, r -> { throw new AssertionError(); }, r -> { }, () -> ended[0]++);
		assertSame(card, delivered.get(0));
		assertEquals(1, ended[0]);
		CardPictures.draw(null, icons -> card, delivered::add);
		assertEquals(2, delivered.size());
	}

	@Test
	public void aCardStillWaitingWhenThePluginStopsIsNeverHandedOver() throws Exception
	{
		Late late = new Late();
		List<BufferedImage> delivered = new ArrayList<>();
		javax.swing.SwingUtilities.invokeAndWait(() ->
			CardPictures.draw(late, icons -> card(icons, late, new ArrayList<>()), delivered::add));
		// The plugin stops while the card waits; its pictures turn up afterwards.
		javax.swing.SwingUtilities.invokeAndWait(CardPictures::cancel);
		late.callbacks.get(995).run();
		late.callbacks.get(4151).run();
		javax.swing.SwingUtilities.invokeAndWait(() -> { });
		assertTrue(delivered.isEmpty());
		// And the next card, after a restart, is not held back by the dropped one.
		ItemIcons ready = (id, cb) -> new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
		javax.swing.SwingUtilities.invokeAndWait(() ->
			CardPictures.draw(ready, icons -> new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB), delivered::add));
		assertEquals(1, delivered.size());
	}
}

package com.codex.ledger.ui;

import com.codex.ledger.core.BankCopy;
import com.codex.ledger.core.Ledger;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.util.Collections;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Codex Bank Steward's copy of the bank ({@code codexbanksteward/bankV1}), read for the estimate shown
 * before the ledger has seen the bank. Whatever is saved there, the estimate must neither throw nor
 * claim a worth no bank could have.
 */
public class DamagedBankCopyTest
{
	private static final Gson GSON = new GsonBuilder().create();
	private static final long NOW = 1_790_000_000_000L;

	@Test
	public void anythingUnreadableIsNoCopy()
	{
		String good = "{\"version\":1,\"savedAt\":1789990000000,\"items\":{\"995\":1000,\"4151\":2},\"truncated\":false}";
		String[] saves = {null, "", "  ", "null", "{", "[]", "42", "\"bank\"", "garbage", "{\"items\":[]}", "{\"items\":\"x\"}",
			"{\"items\":null}", "{\"items\":{}}", good.substring(0, good.length() / 2), good.substring(0, good.length() - 1)};
		for (String save : saves)
		{
			BankCopy copy = survives(save);
			assertTrue(save, copy == null || !copy.getItems().isEmpty());
		}
		assertNotNull(survives(good));
	}

	@Test
	public void quantitiesAndDatesNoBankCouldHaveAreShrugged()
	{
		String[] saves = {
			"{\"version\":1,\"savedAt\":1,\"items\":{\"995\":9223372036854775807,\"4151\":9223372036854775807}}",
			"{\"version\":1,\"savedAt\":-5,\"items\":{\"995\":1e30,\"4151\":-3,\"x\":4,\"-7\":2,\"385\":\"many\"}}",
			"{\"version\":99,\"savedAt\":9223372036854775807,\"items\":{\"995\":2147483647},\"truncated\":\"yes\",\"tabs\":[1]}",
			"{\"savedAt\":\"yesterday\",\"items\":{\"995\":1.5,\"4151\":null,\"385\":[],\"2434\":{}}}",
		};
		for (String save : saves)
		{
			BankCopy copy = survives(save);
			if (copy != null)
			{
				BankCopy.Estimate e = copy.estimate(id -> id == 995 ? 1L : 2_147_483_647L);
				assertTrue(save + " " + e.getBank(), e.getBank() >= 0);
			}
		}
		// A coin stack is at most 2,147,483,647 however many are claimed.
		BankCopy max = survives(saves[0]);
		assertEquals(2_147_483_647L, (long) max.getItems().get(995));
		assertNull(survives("{\"items\":{\"0\":5,\"-1\":5}}"));
		// A copy dated in the future says nothing of when it was taken rather than "just now".
		assertEquals("Your bank as Bank Steward last saw it", LedgerPanel.copySeen(Long.MAX_VALUE, NOW));
		assertEquals("Your bank as Bank Steward last saw it", LedgerPanel.copySeen(0, NOW));
		assertEquals("Your bank as Bank Steward last saw it, 2h ago", LedgerPanel.copySeen(NOW - 7_200_000L, NOW));
	}

	private static BankCopy survives(String save)
	{
		try
		{
			BankCopy copy = BankCopy.read(GSON, save);
			LedgerPanel panel = new LedgerPanel((id, cb) -> null);
			panel.setEstimate(copy == null ? null : copy.estimate(id -> id == 995 ? 1L : 1_000_000L));
			panel.update(new Ledger(), Collections.emptyMap(), "Zezima", LedgerPanel.State.WAITING_FOR_BANK, NOW);
			panel.showTab(0);
			DamagedSaveTest.paint(panel);
			return copy;
		}
		catch (RuntimeException e)
		{
			throw new AssertionError("reading " + save + " threw " + e, e);
		}
	}

}

package com.codex.ledger.ui;

import com.codex.ledger.core.Earnings;
import com.codex.ledger.core.Ledger;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Codex Session Chronicle's journal ({@code codexsessionchronicle/journal}) is another plugin's save,
 * read for "what pays": whatever it holds, a later version's shape, a broken session or numbers no
 * session could have, the ledger must neither throw nor show figures that are not true, and one bad
 * session must not hide the good ones.
 */
public class DamagedJournalTest
{
	private static final Gson GSON = new GsonBuilder().create();
	private static final JsonParser PARSER = new JsonParser();
	private static final long DAY = 86_400_000L;
	private static final long HOUR = 3_600_000L;
	private static final long NOW = 1_790_000_000_000L + 20 * DAY;

	/** Three sessions of an hour or two, each gaining worth. */
	private static JsonArray good()
	{
		JsonArray list = new JsonArray();
		list.add(session(NOW - 3 * DAY, 2 * HOUR, 1_000_000_000L, 1_004_000_000L, "Vorkath"));
		list.add(session(NOW - 2 * DAY, HOUR, 1_004_000_000L, 1_005_000_000L, "Mining"));
		list.add(session(NOW - DAY, 3 * HOUR, 1_005_000_000L, 1_011_000_000L, "Vorkath"));
		return list;
	}

	private static JsonObject session(long startedAt, long playedMs, long worthStart, long worthNow, String activity)
	{
		JsonObject s = new JsonObject();
		s.addProperty("startedAt", startedAt);
		s.addProperty("lastSeenAt", startedAt + playedMs);
		s.addProperty("playedMs", playedMs);
		s.addProperty("worthStart", worthStart);
		s.addProperty("worthNow", worthNow);
		s.addProperty("activity", activity);
		return s;
	}

	@Test
	public void aJournalThatCannotBeReadIsNoJournal()
	{
		String whole = good().toString();
		List<String> saves = new ArrayList<>();
		Collections.addAll(saves, null, "", " ", "null", "[", "]", "{}", "{\"version\":2,\"sessions\":[]}", "42", "\"x\"",
			"[[[]]]", "garbage", whole.substring(0, whole.length() / 2), whole.substring(0, whole.length() - 1));
		for (String save : saves)
		{
			survives(save);
		}
	}

	@Test
	public void oneBrokenSessionLeavesTheOthers()
	{
		String[] bad = {"null", "\"x\"", "[]", "{}", "1e30", "-1", "true", "9223372036854775807", "-9223372036854775808"};
		for (String field : new String[]{"startedAt", "playedMs", "worthStart", "worthNow", "activity"})
		{
			for (String value : bad)
			{
				JsonArray list = good();
				list.get(1).getAsJsonObject().add(field, PARSER.parse(value));
				Earnings e = survives(list.toString());
				// Vorkath's two sessions are still counted whatever became of Mining's.
				assertEquals(field + " = " + value, "Vorkath", e.getLines().get(0).getName());
				assertEquals(field + " = " + value, 2, e.getLines().get(0).getSessions());
			}
		}
		for (String value : bad)
		{
			JsonArray list = good();
			list.set(1, PARSER.parse(value));
			Earnings e = survives(list.toString());
			assertEquals(value, 2, e.getLines().get(0).getSessions());
		}
	}

	@Test
	public void numbersNoSessionCouldHaveAreLeftOut()
	{
		long[][] sessions = {
			// Played for longer than the time since it began, or for ever.
			{NOW - HOUR, 50 * HOUR, 1_000_000L, 2_000_000L},
			{NOW - DAY, Long.MAX_VALUE, 1_000_000L, 2_000_000L},
			// Worth below nothing, or more than every coin in the game.
			{NOW - DAY, HOUR, -5_000_000L, 2_000_000L},
			{NOW - DAY, HOUR, 0, Long.MAX_VALUE},
			{NOW - DAY, HOUR, Long.MIN_VALUE, Long.MAX_VALUE},
		};
		for (long[] s : sessions)
		{
			JsonArray list = good();
			list.add(session(s[0], s[1], s[2], s[3], "Zulrah"));
			Earnings e = survives(list.toString());
			for (Earnings.Line line : e.getLines())
			{
				assertTrue(line.getName() + " " + line.perHour(), !line.getName().equals("Zulrah"));
				assertTrue(line.getPlayedMs() > 0);
			}
		}
	}

	@Test
	public void aLaterVersionsFieldsAreIgnored()
	{
		JsonArray list = good();
		for (JsonElement s : list)
		{
			s.getAsJsonObject().addProperty("version", 7);
			s.getAsJsonObject().add("sailing", PARSER.parse("{\"knots\":[1,2]}"));
		}
		Earnings e = survives(list.toString());
		assertEquals(2, e.getLines().size());
	}

	private static Earnings survives(String save)
	{
		try
		{
			List<Earnings.Logged> read = Earnings.read(GSON, save);
			Earnings earnings = Earnings.of(read, NOW);
			LedgerPanel panel = new LedgerPanel((id, cb) -> null);
			panel.setEarnings(earnings);
			Ledger ledger = new Ledger();
			ledger.observe(com.codex.ledger.core.Store.BANK, DamagedSaveTest.items(995, 1_000_000_000L));
			ledger.settle(NOW, id -> 1L, java.time.ZoneOffset.UTC);
			panel.update(ledger, Collections.emptyMap(), "Zezima", LedgerPanel.State.READY, NOW);
			panel.showTab(0);
			DamagedSaveTest.paint(panel);
			return earnings;
		}
		catch (RuntimeException e)
		{
			throw new AssertionError("reading " + save + " threw " + e, e);
		}
	}
}

package com.codex.ledger.ui;

import com.codex.ledger.core.Earnings;
