import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import org.junit.Test;

/**
 * The saved ledger ({@code codexledger/ledger}) is read back at every login, so it must survive
 * whatever a crash, a hand edit or a future version leaves in it: empty, cut short, the wrong type,
 * numbers too big or below zero, fields this version does not know, or plain garbage. None of it may
 * throw, freeze the panel or the card, or cost the parts of the ledger that are still good.
 */
public class DamagedSaveTest
{
	private static final Gson GSON = new GsonBuilder().create();
	private static final JsonParser PARSER = new JsonParser();
	private static final ZoneId UTC = ZoneOffset.UTC;
	private static final long T0 = 1_790_000_000_000L;
	private static final long DAY = 86_400_000L;
	private static final long NOW = T0 + 20 * DAY;
	private static final LedgerPanel panel = new LedgerPanel((id, cb) -> null);
	private static final Prices PRICES = id -> id == 995 ? 1L : id == 4151 ? 1_500_000L : id == 385 ? 900L : 0L;

	/** Values of every wrong kind, put in place of a good one. */
	private static final String[] BAD = {
		"null", "\"\"", "\"garbage\"", "true", "0", "-1", "-9223372036854775808", "9223372036854775807",
		"1e30", "1.5", "[]", "[1,2,3]", "{}", "{\"x\":1}", "[null]", "[{}]", "{\"BANK\":null}",
	};

	/** A ledger that saw its bank three weeks ago and has a page a day, trades and an open offer since. */
	private static Ledger good()
	{
		Ledger ledger = new Ledger();
		for (int d = 0; d <= 20; d++)
		{
			ledger.observe(Store.BANK, items(995, 400_000_000L + d * 9_000_000L, 4151, 2 + d % 3));
			ledger.observe(Store.INVENTORY, items(385, 20 - d % 5));
			ledger.offer(0, d == 20 ? new Offer(4151, true, 3, 1_500_000, 1, 1_500_000, true) : null);
			ledger.settle(T0 + d * DAY, PRICES, UTC);
		}
		return ledger;
	}

	@Test
	public void wholeSavesThatCannotBeReadStartAfresh()
	{
		String good = GSON.toJson(good());
		List<String> saves = new ArrayList<>();
		Collections.addAll(saves, null, "", " ", "null", "{", "}", "[]", "[{}]", "42", "\"ledger\"", "true", "garbage{{",
			"{\"total\":", "\u0000\u0001", "{\"total\":1}{\"total\":2}");
		for (int cut : new int[]{1, 10, good.length() / 3, good.length() / 2, good.length() - 2})
		{
			saves.add(good.substring(0, cut));
		}
		for (String save : saves)
		{
			survives(save);
		}
	}

	@Test
	public void anyOneFieldGoneWrongCostsOnlyThatField()
	{
		Ledger before = good();
		JsonObject good = tree(GSON.toJson(before));
		int points = before.getHistory().size();
		for (String key : new ArrayList<>(good.keySet()))
		{
			for (String bad : BAD)
			{
				JsonObject damaged = good.deepCopy();
				damaged.add(key, PARSER.parse(bad));
				Ledger read = survives(damaged.toString());
				if (!key.equals("history") && !key.equals("since") && !key.equals("total"))
				{
					// The worth over time is what the player would miss most; a broken other field must not take it.
					assertNotNull(key + " = " + bad, read);
					assertEquals(key + " = " + bad, points, read.getHistory().size());
				}
				if (!key.equals("days") && read != null)
				{
					assertTrue(key + " = " + bad, read.getDays().size() >= before.getDays().size() - 1);
				}
			}
		}
	}

	@Test
	public void aBrokenEntryCostsOnlyThatEntry()
	{
		Ledger before = good();
		JsonObject good = tree(GSON.toJson(before));
		int points = before.getHistory().size();
		int days = before.getDays().size();
		for (String bad : BAD)
		{
			JsonObject damaged = good.deepCopy();
			damaged.getAsJsonArray("history").set(1, PARSER.parse(bad));
			Ledger read = survives(damaged.toString());
			assertNotNull(bad, read);
			assertTrue("history[1] = " + bad, read.getHistory().size() >= points - 1);

			damaged = good.deepCopy();
			damaged.getAsJsonArray("days").set(2, PARSER.parse(bad));
			read = survives(damaged.toString());
			assertNotNull(bad, read);
			assertTrue("days[2] = " + bad, read.getDays().size() >= days - 1);
			assertEquals("days[2] = " + bad, points, read.getHistory().size());

			for (String field : new String[]{"items", "deals", "trades", "kinds", "moved", "date", "open", "ms"})
			{
				damaged = good.deepCopy();
				damaged.getAsJsonArray("days").get(3).getAsJsonObject().add(field, PARSER.parse(bad));
				read = survives(damaged.toString());
				assertNotNull(field + " = " + bad, read);
				assertTrue(field + " = " + bad, read.getDays().size() >= days - 1);
			}

			damaged = good.deepCopy();
			damaged.getAsJsonObject("stores").getAsJsonObject("BANK").add("items", PARSER.parse(bad));
			read = survives(damaged.toString());
			assertNotNull(bad, read);
			assertEquals(points, read.getHistory().size());

			damaged = good.deepCopy();
			damaged.getAsJsonObject("prices").add("4151", PARSER.parse(bad));
			damaged.getAsJsonObject("prices").add("not a number", PARSER.parse(bad));
			read = survives(damaged.toString());
			assertNotNull(bad, read);
			assertEquals(points, read.getHistory().size());

			damaged = good.deepCopy();
			damaged.getAsJsonObject("exchange").add("0", PARSER.parse(bad));
			damaged.getAsJsonObject("book").add("4151", PARSER.parse(bad));
			read = survives(damaged.toString());
			assertNotNull(bad, read);
			assertEquals(points, read.getHistory().size());
		}
	}

	@Test
	public void numbersNoAccountCouldHaveAreShrugged()
	{
		JsonObject good = tree(GSON.toJson(good()));
		long[][] points = {
			{T0, Long.MAX_VALUE}, {T0, -5}, {-1, 100}, {0, 0}, {Long.MAX_VALUE, 1}, {NOW + 400 * DAY, 2_000_000_000L},
			{T0 + DAY, Long.MIN_VALUE}, {T0 - DAY, 3}, {Long.MIN_VALUE, Long.MAX_VALUE},
		};
		for (long[] p : points)
		{
			JsonObject damaged = good.deepCopy();
			JsonObject point = new JsonObject();
			point.addProperty("t", p[0]);
			point.addProperty("v", p[1]);
			damaged.getAsJsonArray("history").add(point);
			survives(damaged.toString());
		}
		for (String key : new String[]{"total", "since", "lostUntil"})
		{
			for (long n : new long[]{Long.MAX_VALUE, Long.MIN_VALUE, -1, NOW + 1000 * DAY})
			{
				JsonObject damaged = good.deepCopy();
				damaged.addProperty(key, n);
				survives(damaged.toString());
			}
		}
		for (String field : new String[]{"open", "close", "high", "low", "play", "market", "ex", "loot", "used", "ms", "dead"})
		{
			for (long n : new long[]{Long.MAX_VALUE, Long.MIN_VALUE, -1})
			{
				JsonObject damaged = good.deepCopy();
				for (JsonElement day : damaged.getAsJsonArray("days"))
				{
					day.getAsJsonObject().addProperty(field, n);
				}
				survives(damaged.toString());
			}
		}
		JsonObject damaged = good.deepCopy();
		damaged.getAsJsonObject("stores").getAsJsonObject("BANK").getAsJsonObject("items").addProperty("995", Long.MAX_VALUE);
		damaged.getAsJsonObject("stores").getAsJsonObject("BANK").getAsJsonObject("items").addProperty("4151", -40);
		damaged.getAsJsonObject("prices").addProperty("4151", Long.MAX_VALUE);
		survives(damaged.toString());
		// A date a later version might write, or none that parses.
		for (String date : new String[]{"2026-13-45", "yesterday", "", "+999999999-12-31"})
		{
			damaged = good.deepCopy();
			damaged.getAsJsonArray("days").get(0).getAsJsonObject().addProperty("date", date);
			survives(damaged.toString());
		}
	}

	@Test
	public void aLaterVersionsFieldsAndPlacesAreIgnored()
	{
		Ledger before = good();
		JsonObject damaged = tree(GSON.toJson(before));
		damaged.addProperty("version", 99);
		damaged.add("vaults", PARSER.parse("{\"a\":[1,2]}"));
		damaged.getAsJsonObject("stores").add("SAILING_HOLD", PARSER.parse("{\"seen\":1,\"items\":{\"995\":5}}"));
		damaged.getAsJsonObject("stores").add("FUTURE_VAULT", PARSER.parse("{\"seen\":1,\"items\":{\"995\":7}}"));
		damaged.getAsJsonArray("days").get(0).getAsJsonObject().addProperty("sailed", 4);
		Ledger read = survives(damaged.toString());
		assertNotNull(read);
		assertEquals(before.getHistory().size(), read.getHistory().size());
		assertEquals(before.value(Store.BANK), read.value(Store.BANK));
	}

	@Test
	public void whateverIsLeftOutIsSetAsideBeforeItIsWrittenOver()
	{
		Ledger before = good();
		String whole = GSON.toJson(before);
		assertFalse(Ledger.read(GSON, whole).isMended());
		// A broken day page is left out, and the next save writes over it: the read says so, so the plugin
		// keeps the save aside (it once did only when nothing at all could be read).
		JsonObject damaged = tree(whole);
		damaged.getAsJsonArray("days").set(0, PARSER.parse("\"garbage\""));
		Ledger read = Ledger.read(GSON, damaged.toString());
		assertNotNull(read);
		assertTrue(read.isMended());
		// A place only a later version knows is left out too, even when the rest reads whole.
		damaged = tree(whole);
		damaged.getAsJsonObject("stores").add("SAILING_HOLD", PARSER.parse("{\"seen\":1,\"items\":{\"995\":5}}"));
		assertTrue(Ledger.read(GSON, damaged.toString()).isMended());
		// So are a later version's fields, which read without an error and would be gone at the next save.
		damaged = tree(whole);
		damaged.addProperty("version", 9);
		assertTrue(Ledger.read(GSON, damaged.toString()).isMended());
		damaged = tree(whole);
		damaged.getAsJsonArray("days").get(0).getAsJsonObject().addProperty("sailed", 4);
		assertTrue(Ledger.read(GSON, damaged.toString()).isMended());
		// Every save the plugin itself writes, trimmed to its budget or not, reads as whole.
		assertFalse(Ledger.read(GSON, new Saver(200_000).save(before, GSON::toJson)).isMended());
		assertFalse(Ledger.read(GSON, GSON.toJson(new Ledger())).isMended());
		for (String fixture : new String[]{"ledger-seen.json", "ledger-unseen.json"})
		{
			try (java.io.InputStream in = Ledger.class.getResourceAsStream(fixture))
			{
				String saved = new String(in.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8);
				assertFalse(fixture, Ledger.read(GSON, saved).isMended());
			}
			catch (java.io.IOException e)
			{
				throw new AssertionError(e);
			}
		}
		// One copy is kept: the first, then only a save at least as full, never a stub over it.
		assertTrue(Ledger.setAside(null, whole));
		assertFalse(Ledger.setAside(whole, whole));
		assertFalse(Ledger.setAside(whole, "{\"total\":1"));
		assertTrue(Ledger.setAside("{\"total\":1", whole));
		assertFalse(Ledger.setAside(null, " "));
		StringBuilder huge = new StringBuilder();
		while (huge.length() <= Ledger.MAX_ASIDE)
		{
			huge.append(whole);
		}
		assertFalse(Ledger.setAside(null, huge.toString()));
	}

	/** Reads the save as the plugin does at login, then plays, saves, shows and shares it; fails on any exception. */
	private static Ledger survives(String save)
	{
		Ledger read;
		try
		{
			read = Ledger.read(GSON, save);
		}
		catch (RuntimeException e)
		{
			throw new AssertionError("reading " + clip(save) + " threw " + e, e);
		}
		try
		{
			// Played on a second reading, so what was read stays as it was read for the caller to check.
			Ledger played = read == null ? null : Ledger.read(GSON, save);
			use(played == null ? new Ledger() : played);
		}
		catch (RuntimeException | StackOverflowError e)
		{
			throw new AssertionError("using " + clip(save) + " threw " + e, e);
		}
		return read;
	}

	static void use(Ledger ledger)
	{
		LocalDate today = Instant.ofEpochMilli(NOW).atZone(UTC).toLocalDate();
		ledger.observe(Store.BANK, items(995, 500_000_000L, 4151, 3));
		ledger.settle(NOW, PRICES, UTC);
		Report.of(ledger, 1, today, 0);
		Report.of(ledger, 30, today, 10);
		Months.of(ledger.getDays(), today, 12);
		Milestones.of(ledger.getHistory(), ledger.getTotal(), NOW);
		Forecast.of(ledger, today, 2_000_000_000L);
		Trades.of(ledger, 30, today);
		String saved = new Saver(200_000).save(ledger, GSON::toJson);
		if (Ledger.read(GSON, saved) == null)
		{
			fail("a ledger saved after damage does not read back");
		}
		Map<Integer, String> names = new HashMap<>();
		names.put(995, "Coins");
		if (LedgerCard.canDraw(ledger))
		{
			LedgerCard.Statement s = LedgerCard.Statement.of(ledger, names, "Zezima", today, NOW, UTC, 2_000_000_000L, "Twisted bow", null);
			if (s != null)
			{
				LedgerCard.render(s, (id, cb) -> null, () -> { });
			}
		}
		// One panel for every save, as the plugin keeps one for every account.
		panel.setGoal(new LedgerPanel.Goal(2_000_000_000L, "Twisted bow"));
		panel.update(ledger, names, "Zezima", ledger.isReady() ? LedgerPanel.State.READY : LedgerPanel.State.WAITING_FOR_BANK, NOW);
		for (int tab = 3; tab >= 0; tab--)
		{
			panel.showTab(tab);
			paint(panel);
		}
		for (int range = 4; range >= 0; range--)
		{
			// The worth chart over each range; paint draws the one on show.
			panel.showRange(range);
		}
		paint(panel);
	}

	static void paint(Component c)
	{
		c.setSize(225, 1200);
		layout(c);
		BufferedImage img = new BufferedImage(225, 1200, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		c.paint(g);
		g.dispose();
	}

	private static void layout(Component c)
	{
		c.doLayout();
		if (c instanceof Container)
		{
			for (Component k : ((Container) c).getComponents())
			{
				layout(k);
			}
		}
	}

	private static JsonObject tree(String json)
	{
		return PARSER.parse(json).getAsJsonObject();
	}

	private static String clip(String s)
	{
		return s == null ? "null" : s.length() > 120 ? s.substring(0, 120) + "..." : s;
	}

	static Map<Integer, Long> items(long... pairs)
	{
		Map<Integer, Long> m = new LinkedHashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put((int) pairs[i], pairs[i + 1]);
		}
		return m;
	}
}

package com.codex.ledger.ui;

import com.codex.ledger.core.Forecast;
import com.codex.ledger.core.Ledger;
import com.codex.ledger.core.Milestones;
import com.codex.ledger.core.Prices;
import com.codex.ledger.core.Report;
import com.codex.ledger.core.Saver;
import com.codex.ledger.core.Store;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The accounts at the ends: a maxed one with a bank of 1,500 kinds of item and four months of pages,
 * a save holding 10,000 points of history, and one brand new. Each must work, and what runs on the
 * client thread (settling a tick, saving, the copy the panel is sent, the plaque's figure) must stay
 * within a few milliseconds even for them. Times are the best of several runs, so a busy test machine
 * does not fail it, and printed for the record.
 */
public class ExtremeAccountTest
{
	private static final Gson GSON = new GsonBuilder().create();
	private static final ZoneId UTC = ZoneOffset.UTC;
	private static final long T0 = 1_780_000_000_000L;
	private static final long DAY = 86_400_000L;
	/** What a tick's work may take on the client thread. */
	private static final double TICK_MS = 8;
	/** What the work done once a login (reading the save) or once a few minutes (saving) may take. */
	private static final double ONCE_MS = 40;
	private static final int ITEMS = 1_500;

	/** Every kind of item a price; ids from 1,000 so coins and the bond keep their meaning. */
	private static final Prices PRICES = id -> id == 995 ? 1L : 1_000L + (id * 7919L) % 2_000_000L;

	/** A maxed account: 1,500 kinds of item in the bank, played every day for the 120 days the book keeps. */
	static Ledger maxed()
	{
		Ledger ledger = new Ledger();
		for (int d = 0; d < 120; d++)
		{
			Map<Integer, Long> bank = new HashMap<>();
			bank.put(995, 2_000_000_000L + d * 3_000_000L);
			for (int i = 0; i < ITEMS; i++)
			{
				bank.put(1_000 + i, 1L + (i + d) % 50);
			}
			ledger.observe(Store.BANK, bank);
			for (int tick = 0; tick < 4; tick++)
			{
				Map<Integer, Long> inv = new HashMap<>();
				for (int i = 0; i < 28; i++)
				{
					inv.put(5_000 + (i + tick) % 40, 1L);
				}
				ledger.observe(Store.INVENTORY, inv);
				ledger.settle(T0 + d * DAY + tick * 900_000L, PRICES, UTC);
			}
		}
		return ledger;
	}

	@Test
	public void aMaxedAccountWithAHugeBankStaysQuickOnTheClientThread()
	{
		Ledger ledger = maxed();
		assertTrue(ledger.isReady());
		assertTrue(ledger.holdings().size() > ITEMS);
		long now = T0 + 120 * DAY;
		LocalDate today = Instant.ofEpochMilli(now).atZone(UTC).toLocalDate();
		int[] tick = {0};
		double settle = best(() ->
		{
			// A tick on which the inventory changed: the common case while playing.
			Map<Integer, Long> inv = new HashMap<>();
			inv.put(385, 1L + tick[0]++ % 28);
			ledger.observe(Store.INVENTORY, inv);
			ledger.settle(now + tick[0] * 600L, PRICES, UTC);
		});
		double revalue = best(() -> ledger.settle(now + 60_000L + tick[0]++ * 600L, PRICES, UTC));
		Saver saver = new Saver(200_000);
		String[] saved = new String[1];
		double save = best(() -> saved[0] = saver.save(ledger, GSON::toJson));
		assertTrue(saved[0].length() <= 220_000);
		double copy = best(() -> Ledger.read(GSON, GSON.toJson(ledger)));
		double plaque = best(() -> Report.of(ledger, 1, today, 0));
		double read = best(() -> assertNotNull(Ledger.read(GSON, saved[0])));
		print("maxed, " + ledger.holdings().size() + " kinds held", settle, revalue, save, copy, plaque, read);
		assertTrue("settle " + settle, settle < TICK_MS);
		assertTrue("revalue " + revalue, revalue < TICK_MS);
		assertTrue("plaque " + plaque, plaque < TICK_MS);
		assertTrue("save " + save, save < ONCE_MS);
		assertTrue("copy " + copy, copy < ONCE_MS);
		assertTrue("read " + read, read < ONCE_MS);
		// And the panel draws every tab of it.
		DamagedSaveTest.use(Ledger.read(GSON, saved[0]));
	}

	@Test
	public void aSaveWithTenThousandPointsOfHistoryReadsAndShrinks()
	{
		Ledger base = maxed();
		JsonObject tree = new JsonParser().parse(GSON.toJson(base)).getAsJsonObject();
		JsonArray history = new JsonArray();
		long start = T0 - 400 * DAY;
		for (int i = 0; i < 12_000; i++)
		{
			JsonObject p = new JsonObject();
			p.addProperty("t", start + i * 3_000_000L);
			p.addProperty("v", 1_000_000_000L + i * 100_000L);
			history.add(p);
		}
		tree.add("history", history);
		String json = tree.toString();
		Ledger[] read = new Ledger[1];
		double reading = best(() -> read[0] = Ledger.read(GSON, json));
		// Read back thinned as this version keeps it, so no copy or save after carries all 12,000.
		assertTrue(read[0].getHistory().size() <= 1_200);
		assertEquals(1_000_000_000L + 11_999 * 100_000L, read[0].getHistory().get(read[0].getHistory().size() - 1).getValue());
		long now = start + 12_000 * 3_000_000L;
		Map<Integer, Long> inv = new HashMap<>();
		inv.put(385, 5L);
		// The first settle after login, on fresh copies of the save (read outside the timing), so its
		// time is the best of several first settles rather than one run a busy machine can spoil.
		double first = Double.MAX_VALUE;
		for (int i = 0; i < 12; i++)
		{
			Ledger fresh = Ledger.read(GSON, json);
			fresh.observe(Store.INVENTORY, inv);
			first = Math.min(first, once(() -> fresh.settle(now, PRICES, UTC)));
			if (i % 4 == 3)
			{
				pause();
			}
		}
		read[0].observe(Store.INVENTORY, inv);
		read[0].settle(now, PRICES, UTC);
		assertTrue(read[0].getHistory().size() <= 1_200);
		double later = best(() -> read[0].settle(now + 600L, PRICES, UTC));
		double marks = best(() -> Milestones.of(read[0].getHistory(), read[0].getTotal(), now));
		double pace = best(() -> Forecast.of(read[0], Instant.ofEpochMilli(now).atZone(UTC).toLocalDate(), 0));
		print("12,000 points", reading, first, later, marks, pace);
		// Half a megabyte, four times what this version ever saves: read once, at login.
		assertTrue("read " + reading, reading < 2.5 * ONCE_MS);
		assertTrue("first settle " + first, first < ONCE_MS);
		assertTrue("settle " + later, later < TICK_MS);
		assertTrue("milestones " + marks, marks < TICK_MS);
		DamagedSaveTest.use(read[0]);
	}

	@Test
	public void aBrandNewAccountWaitsForItsBank()
	{
		Ledger ledger = Ledger.read(GSON, GSON.toJson(new Ledger()));
		assertNotNull(ledger);
		assertFalse(ledger.isReady());
		assertEquals(0, ledger.getTotal());
		// Nothing seen, nothing to say: no milestones, a pace not yet known, an empty report.
		long now = T0;
		LocalDate today = Instant.ofEpochMilli(now).atZone(UTC).toLocalDate();
		assertTrue(Milestones.of(ledger.getHistory(), 0, now).getPassed().isEmpty());
		assertEquals(0, Report.of(ledger, 1, today, 0).change());
		assertFalse(LedgerCard.canDraw(ledger));
		// A new player's first look at the inventory, still before the bank.
		Map<Integer, Long> inv = new HashMap<>();
		inv.put(995, 25L);
		ledger.observe(Store.INVENTORY, inv);
		ledger.settle(now, PRICES, UTC);
		assertFalse(ledger.isReady());
		DamagedSaveTest.use(ledger);
	}

	/** The best of a few runs of a piece of work, in milliseconds, after warming it up. */
	private static double best(Runnable work)
	{
		// Warmed well first: a test machine's first runs are the compiler's, not the plugin's.
		for (int i = 0; i < 25; i++)
		{
			work.run();
		}
		// Then sampled in a few rounds a moment apart, so a shared test machine busy for a while (a
		// build beside it, a collection) shows the work's own time rather than its neighbours'.
		double best = Double.MAX_VALUE;
		for (int round = 0; round < 4; round++)
		{
			for (int i = 0; i < 7; i++)
			{
				best = Math.min(best, once(work));
			}
			pause();
		}
		return best;
	}

	private static void pause()
	{
		try
		{
			Thread.sleep(25);
		}
		catch (InterruptedException e)
		{
			Thread.currentThread().interrupt();
		}
	}

	private static double once(Runnable work)
	{
		long t = System.nanoTime();
		work.run();
		return (System.nanoTime() - t) / 1e6;
	}

	private static void print(String what, double... ms)
	{
		StringBuilder line = new StringBuilder(what).append(":");
		for (double m : ms)
		{
			line.append(String.format(Locale.ENGLISH, " %.2f ms", m));
		}
		System.out.println(line);
	}
}

package com.codex.ledger.ui;

import com.codex.ledger.core.Offer;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class FormatTest
{
	@Test
	public void amountsFollowTheSuiteRule()
	{
		// In full below 10,000; whole k below a million; M to one decimal; B to two.
		assertEquals("8,240", Format.amount(8_240));
		assertEquals("10k", Format.amount(10_000));
		assertEquals("41k", Format.amount(41_200));
		assertEquals("96k", Format.amount(95_700));
		assertEquals("412k", Format.amount(412_000));
		assertEquals("1.2M", Format.amount(1_240_000));
		assertEquals("2.4M", Format.amount(2_370_000));
		assertEquals("26.0M", Format.amount(26_000_000));
		assertEquals("98.7M", Format.amount(98_700_000));
		assertEquals("812.4M", Format.amount(812_400_000));
		assertEquals("2.10B", Format.amount(2_100_000_000L));
		// Rounding that reaches the next unit is written in it.
		assertEquals("100k", Format.amount(99_960));
		assertEquals("1.0M", Format.amount(999_600));
		assertEquals("999k", Format.amount(999_499));
		assertEquals("1.00B", Format.amount(999_960_000));
		assertEquals("-45k", Format.coins(-45_200));
		assertEquals("+880k", Format.signed(880_000));
		assertEquals("+880k", Format.signedCompact(880_000));
		// Round goal and milestone figures stay plain.
		assertEquals("1B", Format.mark(1_000_000_000L));
	}

	@Test
	public void columnsUseTheSameRuleAsEverywhereElse()
	{
		// The crest once read "+4.90M" over a page reading "+4.9M".
		assertEquals("+628.1M", Format.signedCompact(628_140_000L));
		assertEquals("-41k", Format.signedCompact(-41_249));
		assertEquals("1.53B", Format.compact(1_534_000_000L));
		assertEquals("8,240", Format.compact(8_240));
		assertEquals(Format.signed(4_900_000), Format.signedCompact(4_900_000));
	}

	@Test
	public void stacksUseTheSuitesLowercaseK()
	{
		assertEquals("450k", Format.stack(450_000));
		assertEquals("99999", Format.stack(99_999));
		assertEquals("12M", Format.stack(12_000_000));
	}

	@Test
	public void billionsCarryTwoPlaces()
	{
		assertEquals("1.50B", Format.coins(1_504_200_000L));
		assertEquals("676.9M", Format.coins(676_900_000L));
		assertEquals("12.40B", Format.coins(12_400_000_000L));
	}

	@Test
	public void figuresSideBySideCarryTheSamePlaces()
	{
		// The card's today, week and month once read "+4.9M", "+26M", "+98.7M".
		assertEquals("+4.9M", Format.signed(4_900_000));
		assertEquals("+26.0M", Format.signed(26_000_000));
		assertEquals("+98.7M", Format.signed(98_700_000));
		assertEquals("+3.2M", Format.signed(3_150_001));
		// Thousands are whole, as in Gear Roadmap and Session Chronicle.
		assertEquals("41k", Format.coins(41_000));
		assertEquals("60k", Format.coins(60_000));
		assertEquals("300k", Format.coins(300_000));
		assertEquals("412k", Format.coins(412_300));
		assertEquals("10k", Format.coins(10_000));
		assertEquals("8,240", Format.coins(8_240));
		// Rounding up to a thousand writes the next unit.
		assertEquals("1.0M", Format.coins(999_500));
		assertEquals("999k", Format.coins(999_499));
		assertEquals("1.00B", Format.coins(999_960_000L));
	}

	@Test
	public void roundFiguresGoByTheirNames()
	{
		assertEquals("1B", Format.mark(1_000_000_000L));
		assertEquals("1.5B", Format.mark(1_500_000_000L));
		assertEquals("750M", Format.mark(750_000_000L));
		assertEquals("10M", Format.mark(10_000_000L));
		assertEquals("1.23B", Format.mark(1_234_567_890L));
		assertEquals("300k", Format.mark(300_000L));
		assertEquals("2.25M", Format.mark(2_250_000L));
	}

	@Test
	public void sharesNeverAddUpPastTheWhole()
	{
		// Rounded one by one these read 51% and 50%.
		assertArrayEquals(new String[]{"51%", "49%"}, Format.shares(new long[]{505, 495}, 1000));
		// Three thirds make 100%, not 99%.
		int[] thirds = Format.sharePoints(new long[]{1, 1, 1}, 3);
		assertEquals(100, thirds[0] + thirds[1] + thirds[2]);
		// Part of a whole adds up to its part; a sliver still shows.
		assertArrayEquals(new String[]{"53%", "19%", "<1%"}, Format.shares(new long[]{530, 190, 2}, 1000));
		// Values over the whole are shared out of their own sum.
		assertArrayEquals(new String[]{"60%", "40%"}, Format.shares(new long[]{600, 400}, 500));
		assertArrayEquals(new String[]{"0%", "0%"}, Format.shares(new long[]{0, 0}, 0));
	}

	@Test
	public void aSliverBesideAlmostAllReadsAsBoth()
	{
		// 99.6% and 0.4% once read "100%" beside "<1%": the two must read as parts of one whole.
		assertArrayEquals(new String[]{">99%", "<1%"}, Format.shares(new long[]{996, 4}, 1000));
		assertArrayEquals(new String[]{">99%", "<1%", "<1%"}, Format.shares(new long[]{9_990, 4, 6}, 10_000));
		// All of it really is 100%, and nothing alongside is hidden by the fix.
		assertArrayEquals(new String[]{"100%", "0%"}, Format.shares(new long[]{1000, 0}, 1000));
		assertArrayEquals(new String[]{"99%", "1%"}, Format.shares(new long[]{990, 10}, 1000));
		// The rows listed may not be all of the whole (the hoard lists the dearest few): one item that is
		// 99.6% of the worth, the rest unlisted, still is not all of it.
		assertArrayEquals(new String[]{">99%"}, Format.shares(new long[]{996}, 1000));
		assertArrayEquals(new String[]{">99%", "0%"}, Format.shares(new long[]{996, 0}, 1000));
		assertArrayEquals(new String[]{"100%"}, Format.shares(new long[]{1000}, 1000));
		// One share on its own, such as a goal's progress, never reads full while short of it.
		assertEquals(">99%", Format.percent(0.996));
		assertEquals("99%", Format.percent(0.994));
		assertEquals("100%", Format.percent(1.0));
		assertEquals("<1%", Format.percent(0.004));
	}

	@Test
	public void offersSayHowFarTheyHaveGot()
	{
		assertEquals("Bought 21,000 of 50,000", LedgerPanel.offerNote(new Offer(1, true, 50_000, 160, 21_000, 3_340_000, true)));
		assertEquals("Sold 1, to collect", LedgerPanel.offerNote(new Offer(1, false, 1, 160, 1, 160, false)));
		assertEquals("Cancelled at 3 of 10", LedgerPanel.offerNote(new Offer(1, true, 10, 160, 3, 480, false)));
	}
}

package com.codex.ledger.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.List;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.AsyncBufferedImage;
import org.junit.Test;

public class IconWatchTest
{
	/** Stands in for AsyncBufferedImage: once loaded, every callback given runs again. */
	private static final class Picture
	{
		boolean loaded;
		final List<Runnable> waiting = new ArrayList<>();
		final List<Runnable> later = new ArrayList<>();

		void onLoaded(Runnable r)
		{
			if (loaded)
			{
				later.add(r);
			}
			else
			{
				waiting.add(r);
			}
		}

		void load()
		{
			loaded = true;
			waiting.forEach(Runnable::run);
			waiting.clear();
		}

		void runLater()
		{
			List<Runnable> now = new ArrayList<>(later);
			later.clear();
			now.forEach(Runnable::run);
		}
	}

	@Test
	public void aRepaintOnLoadDoesNotLoopOnceThePictureHasArrived()
	{
		IconWatch watch = new IconWatch();
		Picture picture = new Picture();
		int[] paints = {0};
		// A component that asks for its picture while painting and repaints when it loads.
		Runnable[] paint = new Runnable[1];
		paint[0] = () ->
		{
			paints[0]++;
			watch.watch(picture, () -> picture.later.add(paint[0]), picture::onLoaded);
		};
		paint[0].run();
		paint[0].run();
		picture.load();
		for (int i = 0; i < 20; i++)
		{
			picture.runLater();
		}
		assertTrue(watch.hasArrived(picture));
		// Two paints before it arrived, one repaint each from the arrival, then nothing more.
		assertEquals(4, paints[0]);
		assertTrue(picture.later.isEmpty());
	}

	@Test
	public void aPictureAlreadyLoadedRepaintsOnceAtMost()
	{
		IconWatch watch = new IconWatch();
		Picture picture = new Picture();
		picture.loaded = true;
		int[] runs = {0};
		watch.watch(picture, () -> runs[0]++, picture::onLoaded);
		picture.runLater();
		watch.watch(picture, () -> runs[0]++, picture::onLoaded);
		picture.runLater();
		assertEquals(1, runs[0]);
		assertEquals(1, watch.size());
	}

	@Test
	public void nothingToWatchIsSafe()
	{
		IconWatch watch = new IconWatch();
		watch.watch(null, () -> { }, r -> { throw new AssertionError(); });
		Picture picture = new Picture();
		watch.watch(picture, null, picture::onLoaded);
		picture.load();
		assertTrue(watch.hasArrived(picture));
	}

	/** Holds what RuneLite would run later on the client thread, so a test can run it. */
	private static final class Later extends ClientThread
	{
		final List<Runnable> queued = new ArrayList<>();

		@Override
		public void invokeLater(Runnable r)
		{
			queued.add(r);
		}

		void run()
		{
			List<Runnable> now = new ArrayList<>(queued);
			queued.clear();
			now.forEach(Runnable::run);
		}
	}

	@Test
	public void aFreshPictureForTheSameItemIsWatchedAgain()
	{
		// ItemManager keeps only so many item pictures; after one is dropped, asking for the same item
		// hands out a new blank picture that loads later. It must be watched, not taken as arrived.
		Later clientThread = new Later();
		IconWatch watch = new IconWatch();
		int[] repaints = {0};
		AsyncBufferedImage first = new AsyncBufferedImage(clientThread, 36, 32, java.awt.image.BufferedImage.TYPE_INT_ARGB);
		watch.watch(first, () -> repaints[0]++, first::onLoaded);
		first.loaded();
		assertEquals(1, repaints[0]);
		watch.watch(first, () -> repaints[0]++, first::onLoaded);
		clientThread.run();
		assertEquals(1, repaints[0]);

		AsyncBufferedImage again = new AsyncBufferedImage(clientThread, 36, 32, java.awt.image.BufferedImage.TYPE_INT_ARGB);
		assertFalse(watch.hasArrived(again));
		watch.watch(again, () -> repaints[0]++, again::onLoaded);
		again.loaded();
		assertEquals(2, repaints[0]);
		assertTrue(watch.hasArrived(again));
		assertTrue(watch.hasArrived(first));
	}

	@Test
	public void aDroppedPictureIsNotHeldOn()
	{
		IconWatch watch = new IconWatch();
		Later clientThread = new Later();
		AsyncBufferedImage picture = new AsyncBufferedImage(clientThread, 36, 32, java.awt.image.BufferedImage.TYPE_INT_ARGB);
		watch.watch(picture, null, picture::onLoaded);
		picture.loaded();
		assertEquals(1, watch.size());
		picture = null;
		for (int i = 0; i < 50 && watch.size() > 0; i++)
		{
			System.gc();
			byte[] churn = new byte[1 << 20];
			churn[0] = 1;
		}
		assertEquals(0, watch.size());
	}
}

package com.codex.ledger.ui;

import com.codex.ledger.core.Kind;
import com.codex.ledger.core.Ledger;
import com.codex.ledger.core.Prices;
import com.codex.ledger.core.Report;
import com.codex.ledger.core.Store;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class KindStoryTest
{
	private static final long T0 = 1_790_000_000_000L - 1_790_000_000_000L % 86_400_000L + 8 * 3_600_000L;
	private static final long DAY = 86_400_000L;
	private static final int WHIP = 4151;
	private static final int BOW = 20997;

	private static Kind kind(int id)
	{
		return id == WHIP || id == BOW ? Kind.GEAR : Kind.MATERIALS;
	}

	@Test
	public void coinsSpentWhileGearRisesInPriceAreNotSaidToHaveBoughtGear()
	{
		Map<Integer, Long> price = new HashMap<>();
		price.put(995, 1L);
		price.put(BOW, 1_500_000_000L);
		Prices prices = id -> price.getOrDefault(id, 0L);
		Ledger ledger = new Ledger();
		ledger.setKinds(KindStoryTest::kind);
		ledger.observe(Store.BANK, items(995, 100_000_000L, BOW, 1L));
		ledger.settle(T0, prices, ZoneOffset.UTC);

		// Next day 20M in coins goes on things used up, while the bow already owned rises 30M in price.
		price.put(BOW, 1_530_000_000L);
		ledger.observe(Store.BANK, items(995, 80_000_000L, BOW, 1L));
		ledger.settle(T0 + DAY, prices, ZoneOffset.UTC);
		Report day = Report.of(ledger, 1, date(T0 + DAY), 5);
		assertNull(LedgerPanel.kindStory(day.getKinds(), day.kindFlow()));
	}

	@Test
	public void coinsThatBecomeGearAreNamed()
	{
		Map<Integer, Long> price = new HashMap<>();
		price.put(995, 1L);
		price.put(WHIP, 1_500_000L);
		Prices prices = id -> price.getOrDefault(id, 0L);
		Ledger ledger = new Ledger();
		ledger.setKinds(KindStoryTest::kind);
		ledger.observe(Store.BANK, items(995, 5_000_000L));
		ledger.settle(T0, prices, ZoneOffset.UTC);
		ledger.observe(Store.BANK, items(995, 3_500_000L, WHIP, 1L));
		ledger.settle(T0 + 60_000, prices, ZoneOffset.UTC);
		// Measured within the ledger's first day, with no earlier page to compare against.
		Report day = Report.of(ledger, 1, date(T0), 5);
		assertEquals("About 1.5M in coins went into gear.", LedgerPanel.kindStory(day.getKinds(), day.kindFlow()));
	}

	private static LocalDate date(long t)
	{
		return Instant.ofEpochMilli(t).atZone(ZoneOffset.UTC).toLocalDate();
	}

	private static Map<Integer, Long> items(Object... pairs)
	{
		Map<Integer, Long> m = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put(((Number) pairs[i]).intValue(), ((Number) pairs[i + 1]).longValue());
		}
		return m;
	}
}

package com.codex.ledger.ui;

import com.codex.ledger.core.Forecast;
import com.codex.ledger.core.Ledger;
import com.codex.ledger.core.Milestones;
import com.codex.ledger.core.Prices;
import com.codex.ledger.core.Store;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.image.BufferedImage;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class LedgerCardTest
{
	private static final ZoneId UTC = ZoneOffset.UTC;
	private static final long T0 = 1_790_000_000_000L;
	private static final long DAY = 86_400_000L;

	/** A ledger that saw its bank, then grew from 400M past 500M over two weeks. */
	private static Ledger rising()
	{
		Map<Integer, Long> price = new HashMap<>();
		price.put(995, 1L);
		price.put(4151, 1_500_000L);
		Prices prices = id -> price.getOrDefault(id, 0L);
		Ledger ledger = new Ledger();
		for (int d = 0; d <= 14; d++)
		{
			Map<Integer, Long> bank = new HashMap<>();
			bank.put(995, 400_000_000L + d * 10_000_000L);
			bank.put(4151, 2L);
			ledger.observe(Store.BANK, bank);
			ledger.settle(T0 + d * DAY, prices, UTC);
		}
		return ledger;
	}

	private static LocalDate day(long t)
	{
		return Instant.ofEpochMilli(t).atZone(UTC).toLocalDate();
	}

	@Test
	public void nothingToShareUntilTheBankIsSeen()
	{
		assertFalse(LedgerCard.canDraw(null));
		Ledger unseen = new Ledger();
		Map<Integer, Long> inv = new HashMap<>();
		inv.put(995, 25_000L);
		unseen.observe(Store.INVENTORY, inv);
		unseen.settle(T0, id -> 1L, UTC);
		assertFalse(LedgerCard.canDraw(unseen));
		assertNull(LedgerCard.Statement.of(unseen, Collections.emptyMap(), "Zezima", day(T0), T0, UTC, 0, "", null));
	}

	@Test
	public void theStatementTakesTheMonthAndTheTopHoldings()
	{
		Ledger ledger = rising();
		long now = T0 + 14 * DAY;
		Map<Integer, String> names = new HashMap<>();
		names.put(995, "Coins");
		LedgerCard.Statement s = LedgerCard.Statement.of(ledger, names, "", day(now), now, UTC, 0, null, null);
		assertNotNull(s);
		// An empty name prints as "My ledger".
		assertNull(s.player);
		assertEquals(ledger.getTotal(), s.total);
		// The chart starts where the ledger began when that is under thirty days ago, and runs to now.
		assertEquals(T0, s.from);
		assertEquals(now, s.points.get(s.points.size() - 1).getTime());
		assertEquals("Coins", s.held.get(0).name);
		// An item with no name known still has a line.
		assertEquals("Item 4151", s.held.get(1).name);
		assertEquals(500_000_000L, s.milestones.getPassed().get(0).getAmount());
		assertTrue(s.pays.isEmpty());
	}

	@Test
	public void oneFigureIsNeverHeadedTwice()
	{
		Ledger ledger = rising();
		long now = T0 + 14 * DAY;
		Milestones m = Milestones.of(ledger.getHistory(), ledger.getTotal(), now);
		// With no goal the goal section heads for the next round figure, so the milestones leave it out.
		assertNull(LedgerCard.nextMark(m, Forecast.of(ledger, day(now), 0)));
		assertNull(LedgerCard.nextMark(m, Forecast.of(ledger, day(now), m.getNext())));
		assertEquals("next " + Format.mark(m.getNext()), LedgerCard.nextMark(m, Forecast.of(ledger, day(now), 2_000_000_000L)));
	}

	@Test
	public void titlesAndFileNames()
	{
		assertEquals("My ledger", LedgerCard.title(null));
		assertEquals("Zezima's ledger", LedgerCard.title("Zezima"));
		assertEquals("Ledger 19 October 2026.png", LedgerCard.fileName(Instant.parse("2026-10-19T12:00:00Z").toEpochMilli(), UTC));
	}

	@Test
	public void rendersAWholePageAtTwiceScaleAndAsksForEachPicture()
	{
		Ledger ledger = rising();
		long now = T0 + 14 * DAY;
		LedgerCard.Statement s = LedgerCard.Statement.of(ledger, Collections.emptyMap(), "A very long player name", day(now), now, UTC,
			2_000_000_000L, "Twisted bow and then some more", null);
		List<Integer> asked = new ArrayList<>();
		BufferedImage card = LedgerCard.render(s, (id, cb) ->
		{
			asked.add(id);
			return new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
		}, null);
		assertEquals(LedgerCard.WIDTH * LedgerCard.SCALE, card.getWidth());
		assertTrue(card.getHeight() > 600);
		// Measuring the card asks for no pictures; drawing it asks once for each holding.
		assertEquals(2, asked.size());
		// The corners are clear and the middle is drawn.
		assertEquals(0, card.getRGB(0, 0) >>> 24);
		assertEquals(255, card.getRGB(card.getWidth() / 2, card.getHeight() / 2) >>> 24);
	}

	@Test
	public void wrappedLinesEndInAnEllipsisWhenTheyRunOn()
	{
		FontMetrics fm = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics().getFontMetrics(new Font(Font.MONOSPACED, Font.PLAIN, 10));
		int width = fm.stringWidth("aaaa bbbb");
		List<String> lines = LedgerCard.lines("aaaa bbbb cccc dddd eeee ffff", fm, width, 2);
		assertEquals(2, lines.size());
		assertEquals("aaaa bbbb", lines.get(0));
		assertTrue(lines.get(1).endsWith("..."));
		assertEquals(Collections.singletonList("aaaa"), LedgerCard.lines("aaaa", fm, width, 2));
	}

	@Test
	public void gapsBetweenMilestonesReadPlainly()
	{
		assertEquals("under an hour", Format.gap(20 * 60_000L));
		assertEquals("5 hours", Format.gap(5 * 3_600_000L));
		assertEquals("1 day", Format.gap(DAY + 1));
		assertEquals("89 days", Format.gap(89 * DAY));
		assertEquals("4 months", Format.gap(120 * DAY));
		assertEquals("under an hour", Format.gap(-5));
	}
}

package com.codex.ledger.ui;

import java.util.Locale;
